function scheduleRankingListReload(){const tab=S.ranking.mode==='units'?'rankUnits':'rankCharacters';if(instantBrowseReady(tab)){const q=instantBrowseQ(tab);if(!instantBrowseQueryNeedsServer(q,tab)&&instantBrowseApply(tab,1,q)){clearTimeout(S._rankListFt);return}}clearTimeout(S._rankListFt);S._rankListFt=setTimeout(()=>{S._rankListFt=null;loadRankingList(1)},BROWSE_SEARCH_DEBOUNCE_MS)}
