const _rankingPodiumCache=new Map();
function syncRankingViewModeUi(){ensureRankingTopControlEnhancements();const vm=(S.ranking&&S.ranking.viewMode)||'list';document.querySelectorAll('.ranking-view-btn').forEach(b=>b.classList.toggle('active',b.dataset.rankingView===vm));document.querySelectorAll('.ranking-exp-switch').forEach(b=>{if(b.dataset.expKey==='pct')b.classList.toggle('active',!!(S.ranking&&S.ranking.showPercentDiff));if(b.dataset.expKey==='cmp')b.classList.toggle('active',!!(S.ranking&&S.ranking.compareMode));const t=b.querySelector('.ranking-exp-switch-track');if(t)t.classList.toggle('active',b.classList.contains('active'))});const pg=document.querySelector('#panel-ranking .pagination-bar-wrap');if(pg)pg.style.display=vm==='podium'?'none':''}
function setRankingViewMode(mode){if(mode!=='list'&&mode!=='podium')return;if(S.ranking.viewMode===mode)return;S.ranking.viewMode=mode;syncRankingViewModeUi();const cur=S.ranking.mode==='characters'?'characters':'units';const payload=_rankingLastPayloadByMode[cur];if(payload)renderRankingList(payload);else void loadRankingList(mode==='podium'?1:(cur==='characters'?S.ranking.pageChar:S.ranking.pageUnit))}
function ensureRankingExperimentalState(){if(!S.ranking)return;S.ranking.showPercentDiff=!!S.ranking.showPercentDiff;S.ranking.compareMode=!!S.ranking.compareMode;if(S.ranking.compareBaseId==null)S.ranking.compareBaseId='';if(!Array.isArray(S.ranking.compareTargetIds))S.ranking.compareTargetIds=[]}
function toggleRankingPercentDiffMode(){ensureRankingExperimentalState();S.ranking.showPercentDiff=!S.ranking.showPercentDiff;syncRankingViewModeUi();const cur=S.ranking.mode==='characters'?'characters':'units';const payload=_rankingLastPayloadByMode[cur];if(payload)renderRankingList(payload)}
function toggleRankingCompareMode(){ensureRankingExperimentalState();S.ranking.compareMode=!S.ranking.compareMode;if(!S.ranking.compareMode)clearRankingCompareSelections();syncRankingViewModeUi();const cur=S.ranking.mode==='characters'?'characters':'units';const payload=_rankingLastPayloadByMode[cur];if(payload)renderRankingList(payload)}
function rankingTailMobileRelocationActive(){try{return typeof window.matchMedia==='function'&&window.matchMedia('(max-width:768px)').matches}catch(_){return(typeof window.innerWidth==='number'&&window.innerWidth<=768)}}
function syncRankingTailControlsPlacement(){const panel=document.getElementById('panel-ranking');if(!panel)return;if(S.currentTab!=='ranking')return;const row=document.querySelector('#panel-ranking .ranking-sort-row');if(!row)return;const tails=[...panel.querySelectorAll('.ranking-tail-controls')];let tail=tails.find(el=>el.querySelector('.ranking-exp-controls'))||tails[0];tails.forEach(el=>{if(el!==tail)el.remove()});if(!tail)return;const mode=S.ranking&&S.ranking.mode;const mobile=rankingTailMobileRelocationActive();const unitsHost=document.getElementById('rankUnitListStatToggles');const charsHost=document.getElementById('rankCharListStatToggles');const browseUnits=document.querySelector('#rankingUnitToolbarHost .list-toolbar-left--browse');const browseChars=document.querySelector('#rankingCharToolbarHost .list-toolbar-left--browse');let target=null;if(mode==='units')target=mobile?unitsHost:browseUnits;else if(mode==='characters')target=mobile?charsHost:browseChars;if(target)target.appendChild(tail);else row.appendChild(tail)}
function rankingListUrlFor(mode,sortKey,page,perPage,dir,detailStatPerspective,rankingBulk){const p=Math.max(1,Number(page)||1),pp=Math.max(1,Number(perPage)||5),dv=(dir==='asc'?'asc':'desc');const o=detailStatPerspective?{detailStatPerspective:true}:undefined;const base=mode==='characters'?buildRankingCharactersListUrl(p,pp,o):buildRankingUnitsListUrl(p,pp,o);const u=new URL(base,location.origin);u.searchParams.set('sort',String(sortKey||''));u.searchParams.set('dir',dv);u.searchParams.set('page',String(p));if(rankingBulk){u.searchParams.set('ranking_bulk','1');u.searchParams.set('per_page',String(Math.min(500,Math.max(pp,100))))}else{u.searchParams.set('per_page',String(pp))}return u.pathname+u.search}
function rankingPodiumCacheKey(){return`${S.lang}:${S.ranking.mode}:${detailRankingPerspectiveKey(S.ranking.mode==='characters'?'character':'unit')}:${(document.getElementById('rankCharFilter')||{}).value||''}:${(document.getElementById('rankUnitFilter')||{}).value||''}:${JSON.stringify([S.listRankCharLineage,S.listRankCharSeries,S.listRankCharSkills,S.listRankCharAbilities,S.listRankUnitLineage,S.listRankUnitSeries,S.listRankUnitAbilities,S.listRankUnitTerrain,S.listRankUnitWeaponDebuff,S.listRankUnitWeaponRange,S.listRankUnitWeaponRangeNonMap,S.listRankUnitWeaponRangeNonMapSspExOnly,S.listRankUnitMechanism,S.listRankCharSource,S.listRankUnitSource,S.listRankCharSp,S.listRankCharCond,S.listRankUnitSp,S.listRankUnitSsp,S.listRankUnitCond,S.listRankUnitPilotCond])}`}
async function fetchRankingPodiumData(mode){const key=rankingPodiumCacheKey();if(_rankingPodiumCache.has(key))return _rankingPodiumCache.get(key);const stats=(mode==='characters'?RANK_SORT_KEYS_CHAR:RANK_SORT_KEYS_UNIT).slice();const out={};await Promise.all(stats.map(async sk=>{try{const r=await fetchJsonWithWarmupRetry(rankingListUrlFor(mode,sk,1,5,'desc'));if(!r.ok){out[sk]={rows:[],total:0,sort:sk,page:1,per_page:5,stat_bounds:null};return}const d=r.data;out[sk]={rows:Array.isArray(d&&d.rows)?d.rows.slice(0,5):[],total:Number(d&&d.total||0),sort:sk,page:1,per_page:5,stat_bounds:d&&d.stat_bounds||null}}catch(_){out[sk]={rows:[],total:0,sort:sk,page:1,per_page:5,stat_bounds:null}}}));const hasAny=Object.values(out).some(v=>v&&Array.isArray(v.rows)&&v.rows.length>0);if(hasAny){_rankingPodiumCache.set(key,out);while(_rankingPodiumCache.size>24){const k=_rankingPodiumCache.keys().next().value;_rankingPodiumCache.delete(k)}}return out}
function setRankingMode(mode){if(mode!=='characters'&&mode!=='units')return;if(S.ranking.mode===mode)return;S.ranking.mode=mode;document.querySelectorAll('.ranking-mode-btn').forEach(b=>b.classList.toggle('active',b.dataset.rankingMode===mode));const ch=document.getElementById('rankingCharToolbarHost'),un=document.getElementById('rankingUnitToolbarHost');if(ch)ch.style.display=mode==='characters'?'block':'none';if(un)un.style.display=mode==='units'?'block':'none';renderRankingStatPills();syncRankListStatToggleUi();if(document.getElementById('searchSpotlightOverlay')&&document.getElementById('searchSpotlightOverlay').classList.contains('active')){const inp=document.getElementById('searchSpotlightInput');if(inp)inp.placeholder=t(getTabSearchPlaceholderKey());debounceSpotlightResults()}void loadRankingList(1)}
let _rankPillProx=null;
function rankingStatPillProxEnabled(){try{if(typeof window.matchMedia!=='function')return false;if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return false;return window.matchMedia('(hover:hover) and (pointer:fine)').matches}catch(_){return false}}
function rankingStatPillProxEase(t){const c=Math.max(0,Math.min(1,t));return 1-Math.pow(1-c,2.65)}
function invalidateRankingStatPillProxCache(){if(_rankPillProx){_rankPillProx.dirty=true;_rankPillProx.pills=null}}
function measureRankingStatPills(host){const hr=host.getBoundingClientRect();return[...host.querySelectorAll('.ranking-stat-pill')].map(el=>{const r=el.getBoundingClientRect();return{el,cx:r.left-hr.left+r.width/2+host.scrollLeft,cy:r.top-hr.top+r.height/2+host.scrollTop}})}
function resetRankingStatPillProximity(){if(!_rankPillProx)return;const host=_rankPillProx.host;if(host){host.classList.remove('is-prox-active');host.querySelectorAll('.ranking-stat-pill').forEach(el=>{el.style.removeProperty('--rank-prox-scale');el.style.removeProperty('--rank-prox-y');el.style.removeProperty('--rank-prox-bright');el.style.zIndex='';el.style.boxShadow=''})}_rankPillProx.mx=null;_rankPillProx.my=null;_rankPillProx.pills=null;_rankPillProx.dirty=true}
function applyRankingStatPillProximity(){const s=_rankPillProx;if(!s||s.mx==null||s.my==null)return;if(s.dirty||!s.pills){s.pills=measureRankingStatPills(s.host);s.dirty=false}const mx=s.mx,my=s.my,maxDist=120,minScale=0.88,maxScale=1.14,minY=1,maxY=-4,minBright=0.78;for(const p of s.pills){const dist=Math.hypot(mx-p.cx,my-p.cy);const raw=Math.max(0,1-dist/maxDist);const factor=rankingStatPillProxEase(raw);const scale=minScale+(maxScale-minScale)*factor;const ty=minY+(maxY-minY)*factor;const bright=minBright+(1-minBright)*factor;p.el.style.setProperty('--rank-prox-scale',scale.toFixed(4));p.el.style.setProperty('--rank-prox-y',`${ty.toFixed(2)}px`);p.el.style.setProperty('--rank-prox-bright',bright.toFixed(3));if(factor>0.82){p.el.style.zIndex='3';p.el.style.boxShadow='0 8px 20px rgba(0,0,0,.35)'}else if(factor>0.38){p.el.style.zIndex='2';p.el.style.boxShadow=''}else{p.el.style.zIndex='1';p.el.style.boxShadow=''}}}
function destroyRankingStatPillProximity(){if(!_rankPillProx)return;resetRankingStatPillProximity();if(_rankPillProx.raf){cancelAnimationFrame(_rankPillProx.raf);_rankPillProx.raf=null}if(typeof _rankPillProx._destroy==='function')_rankPillProx._destroy();_rankPillProx=null}
function initRankingStatPillProximity(){const host=document.getElementById('rankingStatPills');if(!host||!rankingStatPillProxEnabled()){destroyRankingStatPillProximity();return}if(_rankPillProx&&_rankPillProx.host===host)return;destroyRankingStatPillProximity();const refresh=()=>{if(_rankPillProx)_rankPillProx.dirty=true};const onMove=e=>{if(!_rankPillProx)return;const hr=_rankPillProx.host.getBoundingClientRect();_rankPillProx.mx=e.clientX-hr.left+_rankPillProx.host.scrollLeft;_rankPillProx.my=e.clientY-hr.top+_rankPillProx.host.scrollTop;if(!_rankPillProx.raf){_rankPillProx.raf=requestAnimationFrame(()=>{_rankPillProx.raf=null;applyRankingStatPillProximity()})}};const onEnter=()=>{if(_rankPillProx){_rankPillProx.host.classList.add('is-prox-active');_rankPillProx.dirty=true}};const onLeave=()=>{if(_rankPillProx)resetRankingStatPillProximity()};host.addEventListener('pointerenter',onEnter);host.addEventListener('pointermove',onMove);host.addEventListener('pointerleave',onLeave);window.addEventListener('resize',refresh,{passive:true});let ro=null;if(typeof ResizeObserver!=='undefined'){ro=new ResizeObserver(refresh);ro.observe(host)}_rankPillProx={host,pills:null,dirty:true,mx:null,my:null,raf:null,_destroy:()=>{host.removeEventListener('pointerenter',onEnter);host.removeEventListener('pointermove',onMove);host.removeEventListener('pointerleave',onLeave);window.removeEventListener('resize',refresh);if(ro)ro.disconnect()}}}
function renderRankingStatPills(){const host=document.getElementById('rankingStatPills');if(!host)return;const mode=S.ranking.mode;const sort=mode==='characters'?S.ranking.sortChar:S.ranking.sortUnit;const keys=rankingSortKeys();host.innerHTML=keys.map(k=>`<button type="button" class="ranking-stat-pill${k===sort?' active':''}" data-rank-stat="${escAttr(k)}" onclick="setRankingSortKey('${escJs(k)}')">${esc(tStat(k,mode==='characters'?'character':'unit'))}</button>`).join('');const db=document.getElementById('rankingDirBtn');if(db){const d=mode==='characters'?S.ranking.dirChar:S.ranking.dirUnit;const isDesc=d==='desc';const ic=isDesc?'/static/images/UI/UI_Common_BtnIcon_Order_Down.webp':'/static/images/UI/UI_Common_BtnIcon_Order_UP.webp';db.innerHTML=`<img class="ranking-dir-icon" src="${imgUrl(ic)}" alt="" loading="lazy" decoding="async" onerror="this.style.display='none'">`;db.title=isDesc?t('sort_desc'):t('sort_asc');db.setAttribute('aria-label',isDesc?t('sort_desc'):t('sort_asc'))}invalidateRankingStatPillProxCache();initRankingStatPillProximity();syncRankingViewModeUi()}
function setRankingSortKey(k){const keys=rankingSortKeys();if(!keys.includes(k))return;const mode=S.ranking.mode;if(mode==='characters')S.ranking.sortChar=k;else S.ranking.sortUnit=k;renderRankingStatPills();scheduleRankingListReload()}
function toggleRankingSortDir(){const mode=S.ranking.mode;if(mode==='characters')S.ranking.dirChar=S.ranking.dirChar==='desc'?'asc':'desc';else S.ranking.dirUnit=S.ranking.dirUnit==='desc'?'asc':'desc';renderRankingStatPills();scheduleRankingListReload()}
function syncRankListStatToggleUi(){const cs=document.getElementById('rankCharListSpBtn'),cc=document.getElementById('rankCharListCondBtn'),us=document.getElementById('rankUnitListSpBtn'),ux=document.getElementById('rankUnitListSspBtn'),uc=document.getElementById('rankUnitListCondBtn'),up=document.getElementById('rankUnitListPilotCondBtn');if(cs)cs.classList.toggle('active',!!S.listRankCharSp);if(cc){cc.classList.toggle('active',!!S.listRankCharCond);cc.title=t('conditional_passive')}if(us)us.classList.toggle('active',!!S.listRankUnitSp);if(ux)ux.classList.toggle('active',!!S.listRankUnitSsp);if(uc){uc.classList.toggle('active',!!S.listRankUnitCond);uc.title=t('conditional_passive')}if(up){up.classList.toggle('active',!!S.listRankUnitPilotCond);up.title=t('pilot_exclusive_passive')||'Pilot Exclusive Passive'}}
function toggleRankListUnitPilotCond(){S.listRankUnitPilotCond=!S.listRankUnitPilotCond;syncRankListStatToggleUi();syncWeaponRangeFilterUiForCondChange();scheduleRankingListReload()}
function toggleRankListCharSp(){S.listRankCharSp=!S.listRankCharSp;syncRankListStatToggleUi();scheduleRankingListReload()}
function toggleRankListCharCond(){S.listRankCharCond=!S.listRankCharCond;syncRankListStatToggleUi();scheduleRankingListReload()}
function toggleRankListUnitSp(){if(S.listRankUnitSp){S.listRankUnitSp=false}else{S.listRankUnitSp=true;S.listRankUnitSsp=false}syncRankListStatToggleUi();scheduleRankingListReload()}
function toggleRankListUnitSsp(){if(S.listRankUnitSsp){S.listRankUnitSsp=false}else{S.listRankUnitSsp=true;S.listRankUnitSp=false}syncRankListStatToggleUi();scheduleRankingListReload()}
function toggleRankListUnitCond(){S.listRankUnitCond=!S.listRankUnitCond;syncRankListStatToggleUi();syncWeaponRangeFilterUiForCondChange();scheduleRankingListReload()}
function rankingDetailOptsFromContext(type){const o={viewRanking:true,detailVariant:'rk'};if(type==='character'){o.listCharSpPerspective=!!S.listRankCharSp;o.listCharCondPerspective=!!S.listRankCharCond;return o}o.listUnitSpPerspective=!!S.listRankUnitSp;o.listUnitSspPerspective=!!S.listRankUnitSsp;o.listUnitCondPerspective=!!S.listRankUnitCond;o.listUnitPilotCondPerspective=!!S.listRankUnitPilotCond;return o}
const _detailRankingStatsCache=new Map();
const _detailRankingStatsInflight=new Map();
function detailRankingPerspectiveKey(type){if(type==='character')return `${S.spActive?'sp':'normal'}:${S.conditionalPassiveActive?'cond':'nocond'}`;const sm=S.sspActive?'ssp':(S.spActive?'sp':'normal');return `${sm}:${S.conditionalPassiveActive?'cond':'nocond'}:${S.pilotConditionalPassiveActive?'pilot':'nopilot'}`}
function detailRankingSortKeyForStat(type,statName){const n=String(statName||'');if(type==='character'){const m={Ranged:'Ranged',Melee:'Melee',Awaken:'Awaken',Defense:'Defense',DEFENSE:'Defense',Reaction:'Reaction'};return m[n]||''}const m={HP:'HP',EN:'EN',Attack:'ATK',ATK:'ATK',Defense:'DEF',DEFENSE:'DEF',DEF:'DEF',Mobility:'MOB',MOBILITY:'MOB',MOB:'MOB'};return m[n]||''}
function detailRankingCacheKey(type,id){return`${type}:${String(id)}:${S.lang}:${detailRankingPerspectiveKey(type)}`}
function seedDetailRankingFromLastPayload(type,id,ck){try{const mode=type==='character'?'characters':'units';const p=_rankingLastPayloadByMode&&_rankingLastPayloadByMode[mode];if(!p||!Array.isArray(p.rows)||!p.rows.length)return;const sk=String(p.sort||'');if(!sk)return;const iid=String(id);const idx=p.rows.findIndex(x=>String(x&&x.id||'')===iid);if(idx<0)return;const cur=_detailRankingStatsCache.get(ck)||{};if(cur[sk])return;cur[sk]={rank:((Number(p.page)||1)-1)*(Number(p.per_page)||50)+idx+1,total:Number(p.total||0),value:Number(p.rows[idx]&&p.rows[idx][sk]||0),bounds:p.stat_bounds||null};_detailRankingStatsCache.set(ck,cur)}catch(_){}}
function refreshDetailRankingIfActive(type,id){try{if(S.currentDetailType===type&&S.currentDetailData&&String(S.currentDetailData.id)===String(id))updateDetailDynamicSections(type)}catch(_){}}
function invalidateDetailRankingCachesForPerspectiveChange(){const t=S.currentDetailType,d=S.currentDetailData;if((t!=='character'&&t!=='unit')||!d||!d.id)return;const pfx=`${t}:${String(d.id)}:`;for(const k of [..._detailRankingStatsCache.keys()]){if(String(k).startsWith(pfx))_detailRankingStatsCache.delete(k)}try{_detailRankingIndexCache.clear()}catch(_){}}
function detailRankingMetaFor(type,id,statName){const sk=detailRankingSortKeyForStat(type,statName);if(!sk)return null;const byStat=_detailRankingStatsCache.get(detailRankingCacheKey(type,id));return(byStat&&byStat[sk])||null}
function detailRankingBarWidth(meta){if(!meta||!meta.total||!meta.rank)return 0;return Math.max(2,Math.min(100,((meta.total-meta.rank+1)/meta.total)*100))}
function ordinalSuffixEn(n){const v=Math.abs(Number(n)||0);const mod100=v%100;if(mod100>=11&&mod100<=13)return'th';switch(v%10){case 1:return'st';case 2:return'nd';case 3:return'rd';default:return'th'}}
function detailRankingPosText(meta){if(!meta||!meta.rank||!meta.total)return'-';const rk=Number(meta.rank)||0,tt=Number(meta.total)||0;if(S.lang==='EN')return`${rk}${ordinalSuffixEn(rk)}/${tt}`;return`${fmtN(rk)}位/${fmtN(tt)}`}
function detailRecommendOptsForType(type){const o={viewRanking:true,detailVariant:'rk'};if(type==='character'){o.listCharSpPerspective=!!S.spActive;o.listCharCondPerspective=!!S.conditionalPassiveActive;return o}o.listUnitSpPerspective=!!S.spActive;o.listUnitSspPerspective=!!S.sspActive;o.listUnitCondPerspective=!!S.conditionalPassiveActive;return o}
function openDetailFromRecommend(type,id,viewRanking){const o=viewRanking?detailRecommendOptsForType(type):{};if(viewRanking){void ensureDetailRankingStats(type,String(id)).catch(()=>{})}else if(type==='character'&&S.currentDetailType==='unit'&&S.pilotConditionalPassiveActive&&S.currentDetailData){o.pilotCondHighlightUnitId=String(S.currentDetailData.id)}openDetail(type,String(id),Object.keys(o).length?o:undefined)}
function buildRankingCharactersListUrl(p,pp,opts){const sort=S.ranking.sortChar,dir=S.ranking.dirChar;const q=document.getElementById('rankCharFilter').value.trim();const roleQ=getRoleQuerySuffix('rankChar');const rq=getRarityQuerySuffix('rankChar');const useDp=opts&&opts.detailStatPerspective;const stQ=listStatQChar(useDp?!!S.spActive:!!S.listRankCharSp,useDp?!!S.conditionalPassiveActive:!!S.listRankCharCond);const srcQ=(cur=>{if(!cur||cur==='ALL')return '';return '&source='+encodeURIComponent(cur)})(S.listRankCharSource||'ALL');const linQ=(()=>{let sel=S.listRankCharLineage;if(sel==='ALL'||!sel)sel=[];if(!Array.isArray(sel))sel=[];if(!sel.length)return '';return '&lineage_id='+encodeURIComponent(sel.join(','))})();const linOp=(()=>{let sel=S.listRankCharLineage;if(!Array.isArray(sel)||sel.length<2)return '';return '&lineage_op='+encodeURIComponent(browseCombineOp(S.browseCombRankCharLineage))})();const serQ=(()=>{let sel=S.listRankCharSeries;if(sel==='ALL'||!sel)sel=[];if(!Array.isArray(sel)){if(String(sel).trim())sel=[String(sel)];else sel=[]}if(!sel.length)return '';return '&series_id='+encodeURIComponent(sel.join(','))})();const serOp=(()=>{let sel=S.listRankCharSeries;if(!Array.isArray(sel)||sel.length<2)return '';return '&series_op='+encodeURIComponent(browseCombineOp(S.browseCombRankCharSeries))})();const skillQ=(()=>{let sel=S.listRankCharSkills;if(sel==='ALL'||!sel)sel=[];if(!Array.isArray(sel))sel=[];if(!sel.length)return '';return '&skill_id='+encodeURIComponent(sel.join(','))})();const skOp=(()=>{let sel=S.listRankCharSkills;if(!Array.isArray(sel)||sel.length<2)return '';return '&skill_op='+encodeURIComponent(browseCombineOp(S.browseCombRankCharSkill))})();const abilQ=(()=>{let sel=S.listRankCharAbilities;if(sel==='ALL'||!sel)sel=[];if(!Array.isArray(sel))sel=[];if(!sel.length)return '';return '&ability_id='+encodeURIComponent(sel.join(','))})();const traitOp=(()=>{let sel=S.listRankCharAbilities;if(!Array.isArray(sel)||sel.length<2)return '';return '&ability_op='+encodeURIComponent(browseCombineOp(S.browseCombRankCharTrait))})();return`/api/characters?lang=${S.lang}&page=${p}&per_page=${pp}&sort=${encodeURIComponent(sort)}&dir=${dir}&stat_bounds=1&q=${encodeURIComponent(q)}${roleQ}${rq}${stQ}${srcQ}${linQ}${linOp}${serQ}${serOp}${skillQ}${skOp}${abilQ}${traitOp}`}
function buildRankingUnitsListUrl(p,pp,opts){const sort=S.ranking.sortUnit,dir=S.ranking.dirUnit;const qRaw=document.getElementById('rankUnitFilter').value.trim();const qApi=expandUnitSearchQuery(qRaw);const roleQ=getRoleQuerySuffix('rankUnit');const rq=getRarityQuerySuffix('rankUnit');const useDp=opts&&opts.detailStatPerspective;const stQ=listStatQUnit(useDp?!!S.spActive:!!S.listRankUnitSp,useDp?!!S.sspActive:!!S.listRankUnitSsp,useDp?!!S.conditionalPassiveActive:!!S.listRankUnitCond,useDp?!!S.pilotConditionalPassiveActive:!!S.listRankUnitPilotCond);const srcQ=(cur=>{if(!cur||cur==='ALL')return '';return '&source='+encodeURIComponent(cur)})(S.listRankUnitSource||'ALL');const terrQ=(()=>{let sel=S.listRankUnitTerrain;if(!Array.isArray(sel))sel=[];if(!sel.length)return '';return '&terrain='+encodeURIComponent(sel.join(','))})();const terrOp=(()=>{let sel=S.listRankUnitTerrain;if(!Array.isArray(sel)||sel.length<2)return '';return '&terrain_op='+encodeURIComponent(browseCombineOp(S.browseCombRankTerrain))})();const debQ=(()=>{let sel=S.listRankUnitWeaponDebuff;if(!Array.isArray(sel))sel=[];if(!sel.length)return '';return '&weapon_debuff='+encodeURIComponent(sel.join(','))})();const debOp=(()=>{let sel=S.listRankUnitWeaponDebuff;if(!Array.isArray(sel)||sel.length<2)return '';return '&weapon_debuff_op='+encodeURIComponent(browseCombineOp(S.browseCombRankWb))})();const wrnmQ=(()=>{let sel=S.listRankUnitWeaponRangeNonMap;if(!Array.isArray(sel))sel=[];if(!sel.length)return '';return '&weapon_range_non_map='+encodeURIComponent(sel.join(','))})();const wrnmOp=(()=>{let sel=S.listRankUnitWeaponRangeNonMap;if(!Array.isArray(sel)||sel.length<2)return '';return '&weapon_range_non_map_op='+encodeURIComponent(browseCombineOp(S.browseCombRankWrNm))})();const wrnmSex=S.listRankUnitWeaponRangeNonMapSspExOnly?'&weapon_range_non_map_ssp_ex=1':'';const mwrQ=(()=>{let deb=S.listRankUnitWeaponDebuff;if(!Array.isArray(deb)||!deb.includes('map_weapon'))return '';let sel=S.listRankUnitMapWeaponRange;if(!Array.isArray(sel))sel=[];if(!sel.length)return '';return '&map_weapon_range='+encodeURIComponent(sel.join(','))})();const mwrOp=(()=>{let deb=S.listRankUnitWeaponDebuff;if(!Array.isArray(deb)||!deb.includes('map_weapon'))return '';let sel=S.listRankUnitMapWeaponRange;if(!Array.isArray(sel)||sel.length<2)return '';return '&map_weapon_range_op='+encodeURIComponent(browseCombineOp(S.browseCombRankMapWr))})();const mechQ=(()=>{let sel=S.listRankUnitMechanism;if(!Array.isArray(sel))sel=[];if(!sel.length)return '';return '&mechanism='+encodeURIComponent(sel.join(','))})();const mechOp=(()=>{let sel=S.listRankUnitMechanism;if(!Array.isArray(sel)||sel.length<2)return '';return '&mechanism_op='+encodeURIComponent(browseCombineOp(S.browseCombRankMech))})();const linQ=(()=>{let sel=S.listRankUnitLineage;if(sel==='ALL'||!sel)sel=[];if(!Array.isArray(sel))sel=[];if(!sel.length)return '';return '&lineage_id='+encodeURIComponent(sel.join(','))})();const linOp=(()=>{let sel=S.listRankUnitLineage;if(!Array.isArray(sel)||sel.length<2)return '';return '&lineage_op='+encodeURIComponent(browseCombineOp(S.browseCombRankUnitLineage))})();const serQ=(()=>{let sel=S.listRankUnitSeries;if(sel==='ALL'||!sel)sel=[];if(!Array.isArray(sel)){if(String(sel).trim())sel=[String(sel)];else sel=[]}if(!sel.length)return '';return '&series_id='+encodeURIComponent(sel.join(','))})();const serOp=(()=>{let sel=S.listRankUnitSeries;if(!Array.isArray(sel)||sel.length<2)return '';return '&series_op='+encodeURIComponent(browseCombineOp(S.browseCombRankUnitSeries))})();const abQ=(()=>{let sel=S.listRankUnitAbilities;if(sel==='ALL'||!sel)sel=[];if(!Array.isArray(sel))sel=[];if(!sel.length)return '';return '&ability_id='+encodeURIComponent(sel.join(','))})();const abOp=(()=>{let sel=S.listRankUnitAbilities;if(!Array.isArray(sel)||sel.length<2)return '';return '&ability_op='+encodeURIComponent(browseCombineOp(S.browseCombRankUnitAbil))})();return`/api/units?lang=${S.lang}&page=${p}&per_page=${pp}&sort=${encodeURIComponent(sort)}&dir=${dir}&stat_bounds=1&q=${encodeURIComponent(qApi)}${roleQ}${rq}${stQ}${srcQ}${terrQ}${terrOp}${debQ}${debOp}${wrnmQ}${wrnmOp}${wrnmSex}${mwrQ}${mwrOp}${mechQ}${mechOp}${linQ}${linOp}${serQ}${serOp}${abQ}${abOp}`}
function renderRankingRowBar(val,bounds){if(!bounds||bounds.min==null||bounds.max==null||bounds.max===bounds.min)return'<span class="ranking-bar-track"><span class="ranking-bar-fill" style="width:50%"></span></span>';const v=Math.max(bounds.min,Math.min(bounds.max,Number(val)||0));const w=100*(v-bounds.min)/(bounds.max-bounds.min);return`<span class="ranking-bar-track"><span class="ranking-bar-fill" style="width:${w.toFixed(2)}%"></span></span>`}
function renderRankingList(d){const rows=d.rows||[];const bounds=d.stat_bounds;const sortKey=(d.sort||'');const host=document.getElementById('rankListInner');const empty=document.getElementById('rankEmpty');const load=document.getElementById('rankLoading');if(load)load.style.display='none';if(!host)return;if(!rows.length){host.innerHTML='';if(empty){empty.style.display='block';empty.querySelector('.empty-state-text').textContent=S.ranking.mode==='characters'?t('empty_char'):t('empty_unit')}return}if(empty)empty.style.display='none';const isChar=S.ranking.mode==='characters';const vm=(S.ranking&&S.ranking.viewMode)||'list';const typ=isChar?'character':'unit';if(vm==='bar'){const lim=rankingBarLimit();const topRows=rows.slice(0,lim);const vals=topRows.map(r=>Number(r&&r[sortKey]||0));const mx=Math.max(1,...vals);host.classList.add('ranking-list-inner--bar');host.innerHTML=`<div class="ranking-bar-board">${topRows.map((row,idx)=>{const rank=(d.page-1)*(d.per_page||50)+idx+1;const val=Number(row&&row[sortKey]||0);const h=Math.max(2,Math.min(100,(val/mx)*100));const ro=rankingDetailOptsFromContext(typ);const oj=encodeURIComponent(JSON.stringify(ro));const thumb=renderListThumb(row,isChar?'char':'unit',56);return`<button type="button" class="ranking-bar-col" data-detail-type="${typ}" data-detail-id="${escAttr(String(row.id))}" data-detail-opts="${oj}" onclick="openDetailFromRanking(this)"><div class="ranking-bar-val">${fmtN(val)}</div><div class="ranking-bar-rail"><span class="ranking-bar-col-fill" style="height:${h.toFixed(2)}%"></span></div><div class="ranking-bar-thumb">${thumb}</div><div class="ranking-bar-rank">#${rank}</div></button>`}).join('')}</div>`}else{host.classList.remove('ranking-list-inner--bar');let h='';rows.forEach((row,idx)=>{const rank=(d.page-1)*(d.per_page||50)+idx+1;const val=row[sortKey];const valStr=fmtN(val);const thumb=renderListThumb(row,isChar?'char':'unit',56);const name=esc(row.name||'');const ro=rankingDetailOptsFromContext(typ);const oj=encodeURIComponent(JSON.stringify(ro));h+=`<button type="button" class="ranking-row" data-detail-type="${typ}" data-detail-id="${escAttr(String(row.id))}" data-detail-opts="${oj}" onclick="openDetailFromRanking(this)"><span class="ranking-rank-num">#${rank}</span><span class="ranking-row-thumb">${thumb}</span><span class="ranking-row-name">${name}</span><span class="ranking-row-stat"><span class="ranking-stat-val">${valStr}</span>${renderRankingRowBar(val,bounds)}</span></button>`});host.innerHTML=h}renderPag('rank',d);const pp=document.getElementById('rankPerPage');if(pp){const v=String(d.per_page||50);if([...pp.options].some(o=>o.value===v))pp.value=v}const tc=document.getElementById('rankCharToolbarCount'),tu=document.getElementById('rankUnitToolbarCount');const cnt=`<span class="result-count-num">${d.total}</span> ${isChar?t('count_char'):t('count_unit')}`;if(tc)tc.innerHTML=isChar?cnt:'';if(tu)tu.innerHTML=isChar?'':cnt;syncRankingViewModeUi()}
function openDetailFromRanking(btn){const typ=btn&&btn.getAttribute('data-detail-type');const id=btn&&btn.getAttribute('data-detail-id');const raw=btn&&btn.getAttribute('data-detail-opts');let o={viewRanking:true,detailVariant:'rk'};try{if(raw)o=JSON.parse(decodeURIComponent(raw))}catch(_){}void ensureDetailRankingStats(typ,String(id)).catch(()=>{});openDetail(typ,id,o)}
