function afterBrowseCombineOpChange(ent){if(ent==='char'){browseListJsonCacheClearPrefix('/api/characters?');scheduleBrowseListReload('characters')}else if(ent==='unit'){browseListJsonCacheClearPrefix('/api/units?');scheduleBrowseListReload('units')}else if(ent==='supp'){browseListJsonCacheClearPrefix('/api/supporters?');scheduleBrowseListReload('supporters')}else if(ent==='mod'){browseListJsonCacheClearPrefix('/api/option_parts?');scheduleBrowseListReload('modifications')}else if(ent==='msyUnit'){msyBrowseFilterApplied();if(window.GgenMetaSynergy&&typeof GgenMetaSynergy.scheduleReload==='function')GgenMetaSynergy.scheduleReload()}else if(ent==='rankChar'||ent==='rankUnit')scheduleRankingListReload()}
function lineageIdsMatch(a,b){const sa=String(a||'').trim(),sb=String(b||'').trim();if(!sa||!sb)return false;if(sa===sb)return true;if(sa.length>=4&&sb.endsWith(sa))return true;if(sb.length>=4&&sa.endsWith(sb))return true;return false}
function browseCombineOp(v){return v==='or'||v==='and_or'?v:'and'}
function nextBrowseCombineMode(v){const m=browseCombineOp(v);return m==='and'?'and_or':m==='and_or'?'or':'and'}
function browseCombineModeFromClick(ev,btn){const modes=['and','and_or','or'];if(!ev.detail)return nextBrowseCombineMode(btn.dataset.combineMode||'and');const rect=btn.getBoundingClientRect();const idx=Math.min(2,Math.max(0,Math.floor(((ev.clientX-rect.left)/Math.max(rect.width,1))*3)));return modes[idx]}
function browseCombineOpSuffix(param,sel,combVal){if(!Array.isArray(sel)||sel.length<2)return '';return '&'+param+'='+encodeURIComponent(browseCombineOp(combVal))}
function browseCombineVennClipId(){browseCombineVennClipId._n=(browseCombineVennClipId._n||0)+1;return'bvcp'+browseCombineVennClipId._n}
