function refreshBrowseCombinePriorityMarks(combKey){const lineageMap={browseCombCharLineage:'char',browseCombUnitLineage:'unit',browseCombSuppLineage:'supp',browseCombModLineage:'mod',browseCombRankCharLineage:'rankChar',browseCombRankUnitLineage:'rankUnit'};const p=lineageMap[combKey];if(p)syncLineageCombinePriorityMark(p)}
