function syncBrowseCombineToggleUi(wrap,combKey){if(!wrap||!combKey)return;const mode=browseCombineOp(S[combKey]);const btn=wrap.querySelector('.browse-filter-combine-toggle');if(!btn)return;btn.classList.remove('browse-filter-combine-toggle--or','browse-filter-combine-toggle--and-or');if(mode==='or')btn.classList.add('browse-filter-combine-toggle--or');else if(mode==='and_or')btn.classList.add('browse-filter-combine-toggle--and-or');btn.dataset.combineMode=mode;btn.setAttribute('role','button');btn.removeAttribute('aria-checked');const ttKey=mode==='or'?'browse_filter_combine_tt_or':mode==='and_or'?'browse_filter_combine_tt_and_or':'browse_filter_combine_tt_and';const arKey=mode==='or'?'browse_filter_combine_aria_or':mode==='and_or'?'browse_filter_combine_aria_and_or':'browse_filter_combine_aria_and';btn.title=t(ttKey);btn.setAttribute('aria-label',t(arKey));refreshBrowseCombinePriorityMarks(combKey)}
