function invalidateBrowseFilterPanels(){S._browseFiltersByEntity=null;S._browseLineageNameHints=null;S._msyBrowseFilters=null;function zap(el){if(!el)return;el.innerHTML='';delete el.dataset.populated;delete el.dataset.bfPoolSig}['char','unit','supp','mod','rankChar','rankUnit','msyUnit'].forEach(p=>{delete S['_linLblRf'+p];zap(document.getElementById(p+'LineageFilterBody'))});['char','unit','rankChar','rankUnit','msyUnit'].forEach(p=>{zap(document.getElementById(p+'SeriesFilterBody'));zap(document.getElementById(p+'SkillGrid'));const pan=document.getElementById(p+'SkillFilterPanel');if(pan){delete pan.dataset.populated;delete pan.dataset.bfPoolSig}});{['char','rankChar'].forEach(pfx=>{zap(document.getElementById(pfx+'AbilGrid'));const ap=document.getElementById(pfx+'AbilFilterPanel');if(ap){delete ap.dataset.populated;delete ap.dataset.bfPoolSig}})}invalidateRankingBrowseFilterPanels()}
