const CHALLENGE_SERIES_IDS=['10','810','3000'];
function challengeSeriesOptions(){return(Array.isArray(S._challengeSeriesOptions)&&S._challengeSeriesOptions.length)?S._challengeSeriesOptions:null}
function challengeSeriesBrowseRows(){const api=challengeSeriesOptions();if(api)return api.map(o=>({id:String(o.id),name:String(o.name||o.id),icon:String(o.icon||'')}));const pack=getBrowsePack('unit')||getBrowsePack('char')||{series:[]};const byId={};(pack.series||[]).forEach(r=>{byId[String(r.id)]=r});return CHALLENGE_SERIES_IDS.map(id=>{const row=byId[id]||{};const fb=id==='10'?'Mobile Suit Gundam':id==='3000'?'Mobile Suit Gundam SEED':id;return{id,name:String(row.name||fb),icon:String(row.icon||'')}})}
function challengeSeriesValidId(id){if(id==='ALL')return true;return challengeSeriesBrowseRows().some(r=>String(r.id)===String(id))}
function normalizeChallengeSeriesFilter(){if(!challengeSeriesValidId(S.stages.challengeSeries))S.stages.challengeSeries='ALL'}
function challengeSeriesRowById(id){if(id==='ALL')return{name:t('stage_challenge_series_all'),icon:''};return challengeSeriesBrowseRows().find(r=>String(r.id)===String(id))||{id,name:String(id),icon:''}}
function buildStageChallengeSeriesFilterHtml(){const row=(value,iconHtml,label)=>`<label class="rarity-filter-row stage-challenge-series-row"><input type="radio" name="stageChallengeSeriesSel" value="${escAttr(value)}" onchange="onStageChallengeSeriesChange()"><span class="stage-challenge-series-row-label">${iconHtml}<span class="filter-long-label">${esc(label)}</span></span></label>`;const allA=imgSrcAttr(SERIES_FILTER_ALL_LOGO);const allIc=allA?`<img class="series-filter-opt-icon"${allA} alt="" loading="lazy" decoding="async">`:'';let h=row('ALL',allIc,t('stage_challenge_series_all'));challengeSeriesBrowseRows().forEach(r=>{const a=r.icon?imgSrcAttr(r.icon):'';const ic=a?`<img class="series-filter-opt-icon"${a} alt="" loading="lazy" decoding="async">`:`<span class="series-icon-fallback"></span>`;h+=row(r.id,ic,r.name)});return h}
