function updateStageChallengeSeriesFilterLabel(){const cur=challengeSeriesValidId(S.stages.challengeSeries)?S.stages.challengeSeries:'ALL';const label=document.getElementById('stageChallengeSeriesFilterLabel');const btn=document.getElementById('stageChallengeSeriesFilterBtn');if(!label||!btn)return;btn.title=t('list_filter_series');if(cur==='ALL'){const allA=imgSrcAttr(SERIES_FILTER_ALL_LOGO);const allIc=allA?`<img class="filter-inline-icon role-filter-chip"${allA} alt="" role="presentation">`:'';label.innerHTML=`<span class="list-filter-btn-mini series-filter-btn-all" title="${escAttr(t('stage_challenge_series_all'))}">${allIc}<span class="source-filter-btn-plain">${esc(t('stage_challenge_series_all'))}</span></span>`;btn.classList.remove('active');return}btn.classList.add('active');const row=challengeSeriesRowById(cur);const nm=row.name||String(cur);const a=row.icon?imgSrcAttr(row.icon):'';label.innerHTML=a?`<span class="series-filter-toolbar-icons"><img class="series-filter-toolbar-ic"${a} alt="" role="presentation" title="${escAttr(nm)}"></span>`:`<span class="series-filter-toolbar-fallback" title="${escAttr(nm)}"></span>`;btn.title=nm}
function closeStageChallengeSeriesPanel(){const panel=document.getElementById('stageChallengeSeriesFilterPanel');const btn=document.getElementById('stageChallengeSeriesFilterBtn');if(panel)panel.hidden=true;if(btn)btn.setAttribute('aria-expanded','false')}
function toggleStageChallengeSeriesPanel(ev){if(ev)ev.stopPropagation();const panel=document.getElementById('stageChallengeSeriesFilterPanel');const btn=document.getElementById('stageChallengeSeriesFilterBtn');const body=document.getElementById('stageChallengeSeriesFilterBody');if(!panel||!btn)return;const willOpen=panel.hidden;closeAllFilterPanels();if(willOpen){if(body)body.innerHTML=buildStageChallengeSeriesFilterHtml();fillStageChallengeSeriesPanel();panel.hidden=false;btn.setAttribute('aria-expanded','true')}}
