function ensureStageChallengeSeriesFilterDom(){let wrap=document.getElementById('stageChallengeSeriesWrap');if(wrap)return wrap;const host=document.querySelector('#panel-stages .list-toolbar-left');const diff=document.getElementById('stageDiffWrap');if(!host||!diff)return null;wrap=document.createElement('div');wrap.className='rarity-filter-wrap';wrap.id='stageChallengeSeriesWrap';wrap.innerHTML=`<button type="button" class="rarity-filter-btn role-filter-dd-btn" id="stageChallengeSeriesFilterBtn" onclick="toggleStageChallengeSeriesPanel(event)" aria-expanded="false" aria-haspopup="true"><span id="stageChallengeSeriesFilterLabel" class="filter-btn-label-inner"></span><span class="rarity-filter-caret">▾</span></button><div class="rarity-filter-panel stage-diff-filter-panel stage-challenge-series-filter-panel filter-dropdown-panel" id="stageChallengeSeriesFilterPanel" role="menu" hidden onclick="event.stopPropagation()"><div id="stageChallengeSeriesFilterBody"></div></div>`;host.insertBefore(wrap,diff);fillStageChallengeSeriesPanel();updateStageChallengeSeriesFilterLabel();return wrap}
