function getRarityQuerySuffix(which){const p=rarityPrefix(which);const keys=rarityKeysFor(which);const boxes=keys.map(k=>document.getElementById(p+'Rarity'+k));if(boxes.some(x=>!x))return '';const sel=keys.filter((k,i)=>boxes[i].checked);const allStars=sel.length===keys.length;if(which==='mod'){if(sel.length===0)return '&rarity=__NONE__';if(allStars)return '';return '&rarity='+encodeURIComponent(sel.join(','))}const ltEl=document.getElementById(p+'RarityLT');const ltOn=ltEl&&ltEl.checked;if(sel.length===0&&!ltOn)return '&rarity=__NONE__';if(ltOn){if(allStars)return '';if(sel.length===0)return '&rarity='+encodeURIComponent('LT');return '&rarity='+encodeURIComponent(['LT',...sel].join(','))}const parts=allStars?[...keys]:[...sel];if(rarityUsesExcludeLimited(ltOn,allStars,sel))parts.push('NLT');return '&rarity='+encodeURIComponent(parts.join(','))}
function updateRarityFilterButtonLabel(which){const p=rarityPrefix(which);const keys=rarityKeysFor(which);const label=document.getElementById(p+'RarityFilterLabel');const btn=document.getElementById(p+'RarityFilterBtn');const boxes=keys.map(k=>document.getElementById(p+'Rarity'+k));if(!label||!btn)return;const sel=keys.filter((k,i)=>boxes[i]&&boxes[i].checked);if(which==='mod'){if(sel.length===keys.length){label.innerHTML=rarityFilterIconsHtml(keys);btn.classList.remove('active');return}if(sel.length===0){label.textContent='—';btn.classList.add('active');return}btn.classList.add('active');label.innerHTML=rarityFilterIconsHtml(sel);return}const ltEl=document.getElementById(p+'RarityLT');const ltOn=ltEl&&ltEl.checked;const max=keys.length+(ltEl?1:0);const base=sel.length+(ltOn?1:0);const allStars=sel.length===keys.length;if(base===max&&ltOn){label.innerHTML=rarityFilterIconsHtml(keys);btn.classList.remove('active');return}if(base===0){label.textContent='—';btn.classList.add('active');return}btn.classList.add('active');let h=rarityFilterIconsHtml(sel);if(rarityUsesExcludeLimited(ltOn,allStars,sel))h+=rarityNltToolbarChipHtml();if(!h&&ltOn)label.innerHTML=rarityLtToolbarChipHtml(which);else label.innerHTML=h}
function updateRoleFilterButtonLabel(which){const p=rolePrefix(which);const label=document.getElementById(p+'RoleFilterLabel');const btn=document.getElementById(p+'RoleFilterBtn');const boxes=ROLE_LIST_IDS.map(id=>document.getElementById(p+'Role'+id));if(!label||!btn)return;const sel=ROLE_LIST_IDS.filter((id,i)=>boxes[i]&&boxes[i].checked);const n=sel.length;if(n===ROLE_LIST_IDS.length){label.innerHTML=roleFilterIconsHtml(ROLE_LIST_IDS);btn.classList.remove('active')}else if(n===0){label.textContent='—';btn.classList.add('active')}else{label.innerHTML=roleFilterIconsHtml(sel);btn.classList.add('active')}}
function getRoleQuerySuffix(which){const p=rolePrefix(which);const boxes=ROLE_LIST_IDS.map(id=>document.getElementById(p+'Role'+id));if(boxes.some(x=>!x))return '';const sel=ROLE_LIST_IDS.filter((id,i)=>boxes[i].checked);if(sel.length===0)return '&role=__NONE__';if(sel.length===ROLE_LIST_IDS.length)return '';return '&role='+encodeURIComponent(sel.join(','))}
function fillSourcePanel(which){const p=which==='rankChar'||which==='rankUnit'?which:(which==='msyUnit'?'msyUnit':(which==='char'?'char':'unit'));const cur=S[listSourceKey(which)]||'ALL';const keys=['assembly','development','other'];const set=new Set(cur==='ALL'?keys:cur.split(',').map(x=>x.trim()).filter(Boolean));if(cur!=='ALL'&&set.size===0)keys.forEach(k=>set.add(k));keys.forEach(k=>{const el=document.getElementById(p+'SourceChk'+k.charAt(0).toUpperCase()+k.slice(1));if(el)el.checked=cur==='ALL'||set.has(k)});const isCharLbl=which==='char'||which==='rankChar';const la=document.getElementById(p+'SourceLblAssembly');if(la)la.textContent=t(isCharLbl?'filter_source_assembly_char':'filter_source_assembly');const ld=document.getElementById(p+'SourceLblDevelopment');if(ld)ld.textContent=t(isCharLbl?'filter_source_development_char':'filter_source_development');const lo=document.getElementById(p+'SourceLblOther');if(lo)lo.textContent=t('filter_source_other')}
function updateSourceFilterButtonLabel(which){const p=which==='rankChar'||which==='rankUnit'?which:(which==='msyUnit'?'msyUnit':(which==='char'?'char':'unit'));const cur=S[listSourceKey(which)]||'ALL';const label=document.getElementById(p+'SourceFilterLabel');const btn=document.getElementById(p+'SourceFilterBtn');if(!label||!btn)return;btn.title=t('filter_source');const ic=SOURCE_FILTER_UI_ICONS;const isCharLbl=which==='char'||which==='rankChar';const lbl=(k)=>k==='assembly'?t(isCharLbl?'filter_source_assembly_char':'filter_source_assembly'):k==='development'?t(isCharLbl?'filter_source_development_char':'filter_source_development'):t('filter_source_other');if(cur==='ALL'){label.innerHTML=`<span class="source-filter-btn-all-icons"><img class="filter-inline-icon role-filter-chip" src="${imgUrl(ic.assembly)}" alt="" role="presentation"><img class="filter-inline-icon role-filter-chip" src="${imgUrl(ic.development)}" alt="" role="presentation"><img class="filter-inline-icon role-filter-chip" src="${imgUrl(ic.other)}" alt="" role="presentation"><span class="source-filter-btn-plain">${esc(' - ' + t('filter_source_all'))}</span></span>`;btn.classList.remove('active')}else{const parts=cur.split(',').map(x=>x.trim()).filter(Boolean).sort();const imgs=parts.map(pk=>`<img class="filter-inline-icon role-filter-chip" src="${imgUrl(ic[pk])}" alt="" role="presentation">`).join('');const tx=parts.map(lbl).join(', ');label.innerHTML=imgs+`<span class="source-filter-btn-plain" style="margin-left:4px;font-size:13px;font-weight:600">${esc(tx)}</span>`;btn.classList.add('active')}}
function toggleSourcePanel(which,ev){if(ev)ev.stopPropagation();const p=which==='rankChar'||which==='rankUnit'?which:(which==='msyUnit'?'msyUnit':(which==='char'?'char':'unit'));const panel=document.getElementById(p+'SourceFilterPanel');const btn=document.getElementById(p+'SourceFilterBtn');if(!panel||!btn)return;const willOpen=panel.hidden;closeAllFilterPanels();if(willOpen){panel.hidden=false;btn.setAttribute('aria-expanded','true');fillSourcePanel(which);ensurePanelClearButton(p+'SourceFilterPanel',()=>clearSourceOnly(which))}}
function clearBrowseFilters(which){const p=which==='char'?'char':'unit';if(which==='char')cancelBrowseListReloadTimer('characters');else cancelBrowseListReloadTimer('units');const qEl=document.getElementById(which==='char'?'charFilter':'unitFilter');if(qEl){qEl.value='';updateSearchHintVisibility(which==='char'?'charFilter':'unitFilter');if(qEl.classList.contains('filter-input--organic'))syncBrowseSearchWidth(qEl.id)}if(which==='char'){S.listCharSource='ALL';S.listCharLineage=[];S.listCharSeries=[];S.listCharSkills=[];S.listCharAbilities=[];S.listCharSp=false;S.listCharCond=false;S.browseCombCharLineage='and';S.browseCombCharSeries='or';S.browseCombCharSkill='and';S.browseCombCharTrait='and'}else{S.listUnitSource='ALL';S.listUnitLineage=[];S.listUnitSeries=[];S.listUnitAbilities=[];S.listUnitTerrain=[];S.listUnitWeaponDebuff=[];S.listUnitWeaponRange=[];S.listUnitWeaponRangeNonMap=[];S.listUnitWeaponRangeNonMapSspExOnly=false;S._unitWeaponRangeNmSspExAutoArmed=false;S.listUnitMapWeaponRange=[];S.listUnitMechanism=[];S.listUnitSp=false;S.listUnitSsp=false;S.listUnitCond=false;S.listUnitPilotCond=false;S._unitWeaponRangeSspAutoArmed=false;S.browseCombUnitLineage='and';S.browseCombUnitSeries='or';S.browseCombUnitAbil='and';S.browseCombTerrain='and';S.browseCombWb='and';S.browseCombWr='and';S.browseCombWrNm='and';S.browseCombMapWr='and';S.browseCombMech='and'}const rp=rarityPrefix(which);const ltEl=document.getElementById(p+'RarityLT');rarityKeysFor(which).forEach(k=>{const el=document.getElementById(rp+'Rarity'+k);if(el)el.checked=true});if(ltEl)ltEl.checked=true;ROLE_LIST_IDS.forEach(id=>{const el=document.getElementById(p+'Role'+id);if(el)el.checked=true});fillSourcePanel(which);syncLineageCheckboxes(p);syncSeriesCheckboxes(p);syncSkillBrowseCheckboxes(p);syncAbilBrowseCheckboxes(p);if(which==='unit')syncUnitTerrainCheckboxes();if(which==='unit')syncUnitWeaponDebuffCheckboxes();if(which==='unit')syncUnitMapWeaponRangeCheckboxes();if(which==='unit')syncUnitWeaponRangeCheckboxes();if(which==='unit')syncUnitWeaponRangeNonMapCheckboxes();if(which==='unit')syncUnitMechanismCheckboxes();updateRarityFilterButtonLabel(which);updateRoleFilterButtonLabel(which);updateSourceFilterButtonLabel(which);if(which==='unit')updateUnitTerrainFilterLabel();if(which==='unit')updateUnitWeaponDebuffFilterLabel();if(which==='unit')syncMapWeaponRangeFilterVisibility('unit');if(which==='unit')updateUnitMapWeaponRangeFilterLabel('unit');if(which==='unit')updateUnitWeaponRangeNonMapFilterLabel();if(which==='unit')updateUnitMechanismFilterLabel();updateLineageFilterButtonLabel(which==='supp'?'supp':p);updateSeriesFilterButtonLabel(p);if(which==='char'||which==='unit')updateSkillBrowseFilterLabel(p);if(which==='char')updateAbilBrowseFilterLabel(p);syncListCharToggle();syncListUnitStatToggles();syncListCondToggles();persistListStatToggles();closeAllFilterPanels();invalidateBrowseFilterPanels();if(which==='char')loadCharacters(1);else loadUnits(1)}
function applySourceFromDom(which){const p=which==='rankChar'||which==='rankUnit'?which:(which==='msyUnit'?'msyUnit':(which==='char'?'char':'unit'));const keys=['assembly','development','other'];const picked=keys.filter(k=>{const el=document.getElementById(p+'SourceChk'+k.charAt(0).toUpperCase()+k.slice(1));return el&&el.checked});if(picked.length===0){keys.forEach(k=>{const el=document.getElementById(p+'SourceChk'+k.charAt(0).toUpperCase()+k.slice(1));if(el)el.checked=true});S[listSourceKey(which)]='ALL'}else if(picked.length===3){S[listSourceKey(which)]='ALL'}else{S[listSourceKey(which)]=picked.slice().sort().join(',')}updateSourceFilterButtonLabel(which);if(which==='char')scheduleBrowseListReload('characters');else if(which==='unit')scheduleBrowseListReload('units');else if(which==='msyUnit'){msyBrowseFilterApplied();if(window.GgenMetaSynergy&&typeof GgenMetaSynergy.scheduleReload==='function')GgenMetaSynergy.scheduleReload()}else scheduleRankingListReload()}
function onSourceCheckboxChange(which){applySourceFromDom(which)}
function onSourceRowClick(which,key,ev){if(ev){ev.preventDefault();ev.stopPropagation()}const p=which==='rankChar'||which==='rankUnit'?which:(which==='msyUnit'?'msyUnit':(which==='char'?'char':'unit'));const keys=['assembly','development','other'];if(!keys.includes(key))return;keys.forEach(k=>{const el=document.getElementById(p+'SourceChk'+k.charAt(0).toUpperCase()+k.slice(1));if(el)el.checked=(k===key)});applySourceFromDom(which)}
function onSourceRowKey(ev,which,key){if(ev.key!=='Enter'&&ev.key!==' ')return;ev.preventDefault();onSourceRowClick(which,key,ev)}
function getSourceQuerySuffix(which){const cur=S[listSourceKey(which)]||'ALL';if(!cur||cur==='ALL')return '';return '&source='+encodeURIComponent(cur)}
function unitTerrainLabel(name){if(name==='Space')return t('terrain_space');if(name==='Atmospheric')return t('terrain_atmo');if(name==='Ground')return t('terrain_ground');if(name==='Sea')return t('terrain_sea');if(name==='Underwater')return t('terrain_underwater');return name}
