const MAP_WRT_FILTER_PREVIEW_WEAPONS={'1':{map_coords:[{x:0,y:2},{x:-1,y:1},{x:1,y:1},{x:-2,y:0},{x:-1,y:0},{x:1,y:0},{x:2,y:0},{x:-1,y:-1},{x:1,y:-1},{x:0,y:-2}],shooting_coords:[],is_dash:false},'2':{map_coords:[{x:0,y:1},{x:-1,y:0},{x:0,y:0},{x:1,y:0},{x:0,y:-1}],shooting_coords:[{x:0,y:3},{x:-1,y:2},{x:0,y:2},{x:1,y:2},{x:-1,y:1},{x:1,y:1}],is_dash:false},'3':{map_coords:[{x:-3,y:4},{x:-2,y:4},{x:-1,y:4},{x:0,y:4},{x:1,y:4},{x:2,y:4},{x:3,y:4},{x:-2,y:3},{x:-1,y:3},{x:0,y:3},{x:1,y:3},{x:2,y:3},{x:-1,y:2},{x:0,y:2},{x:1,y:2},{x:0,y:1}],shooting_coords:[],is_dash:false},'4':{map_coords:[{x:0,y:3},{x:0,y:2},{x:0,y:1}],shooting_coords:[{x:0,y:3},{x:0,y:2},{x:0,y:1}],is_dash:true},'2:snipe':{map_coords:[{x:0,y:0}],shooting_coords:[{x:0,y:3},{x:0,y:2},{x:0,y:1}],is_dash:false}};
function mapWeaponAfterMoveFilterIconHtml(compact){const cls=`map-wrt-filter-icon-preview${compact?' map-wrt-filter-icon-preview--toolbar':''}`;return `<div class="${cls}" aria-hidden="true"><img class="map-wrt-am-filter-icon" src="${imgUrl(MAP_WEAPON_AFTER_MOVE_ICON)}" alt="" role="presentation"></div>`}
function mapWeaponRangeFilterIconHtml(typeVal,compact){const v=normalizeMapWeaponRangeToken(typeVal);if(v==='0')return'';if(v===MAP_WEAPON_AFTER_MOVE_FILTER.token)return mapWeaponAfterMoveFilterIconHtml(!!compact);if(v==='2:snipe'){return `<img class="filter-inline-icon role-filter-chip" src="${imgUrl(MAP_WEAPON_SNIPE_ICON)}" alt="" role="presentation">`}const weapon=MAP_WRT_FILTER_PREVIEW_WEAPONS[v]||MAP_WRT_FILTER_PREVIEW_WEAPONS[v.split(':')[0]];if(!weapon)return'';return renderMapGrid(weapon,null,{iconPreview:true,compact:!!compact})}
function mapWrtFilterBtnHtml(token,labelKey,isActive,iconHtml,extraCls){const tok=String(token);const itemCls=`unit-debuff-item${iconHtml?' unit-debuff-item--map-wrt':''}${extraCls||''}${isActive?' is-active':''}`;return `<button type="button" class="${itemCls}" onclick="onUnitMapWeaponRangeRowClick('${escAttr(tok)}',event)" onkeydown="onUnitMapWeaponRangeRowKey(event,'${escAttr(tok)}')">${iconHtml||''}<span>${esc(t(labelKey))}</span></button>`}
function mapWrtTypeBlockHtml(def,selSet,subs){const active=selSet.has(String(def.value));let h=`<div class="map-wrt-type-block${active?' is-active':''}">`;h+=mapWrtFilterBtnHtml(def.value,def.labelKey,active,mapWeaponRangeFilterIconHtml(def.value),' map-wrt-type-main');h+=`<div class="map-wrt-type-subs${active?' is-open':''}"><div class="map-wrt-type-subs-inner">`;for(const sub of subs){const sIcon=sub.icon?`<img class="unit-map-sub-filter-icon" src="${imgUrl(sub.icon)}" alt="" role="presentation">`:'';h+=mapWrtFilterBtnHtml(sub.token,sub.labelKey,selSet.has(String(sub.token)),sIcon,' unit-debuff-item--map-wrt-sub map-wrt-type-sub')}h+='</div></div></div>';return h}
function buildUnitMapWeaponRangeFilterHtml(skOpt){const sk=skOpt||unitMapWeaponRangeStateKey();const selArr=Array.isArray(S[sk])?S[sk].map(normalizeMapWeaponRangeToken):[];const selSet=new Set(selArr.map(v=>String(v)));const defs=getMapWeaponRangeTypeDefsForUi().filter(d=>String(d.value)!=='0');const am=MAP_WEAPON_AFTER_MOVE_FILTER;let h='<div class="unit-debuff-grid unit-debuff-grid--map-wrt">';for(const d of defs){const subs=MAP_WEAPON_RANGE_SUB_FILTERS[String(d.value)]||[];if(subs.length)h+=mapWrtTypeBlockHtml(d,selSet,subs);else h+=mapWrtFilterBtnHtml(d.value,d.labelKey,selSet.has(String(d.value)),mapWeaponRangeFilterIconHtml(d.value),'')}h+=mapWrtFilterBtnHtml(am.token,am.labelKey,selSet.has(am.token),mapWeaponAfterMoveFilterIconHtml(false),' unit-debuff-item--map-wrt-span');h+='</div>';return h}
function mapWeaponRangeFooterOpts(pfx){const rk=S.currentTab==='ranking'&&S.ranking&&S.ranking.mode==='units';return{onClear:clearUnitMapWeaponRangeOnly,combineKey:rk?'browseCombRankMapWr':'browseCombMapWr',combineEntity:rk?'rankUnit':'unit'}}
function syncMapWeaponRangeCombineFooter(pfx){const panel=document.getElementById(pfx+'MapWeaponRangeFilterPanel');if(!panel)return;const left=panel.querySelector('.filter-panel-footer-left');if(!left)return;const sk=pfx==='rankUnit'?'listRankUnitMapWeaponRange':'listUnitMapWeaponRange';const n=(Array.isArray(S[sk])?S[sk]:[]).length;left.style.display=n>=2?'':'none'}
