function toggleUnitMapWeaponRangePanel(ev){if(ev)ev.stopPropagation();const pfx=unitWeaponRangeDomPrefix();if(!mapWeaponDebuffActiveForPfx(pfx))return;const panel=document.getElementById(pfx+'MapWeaponRangeFilterPanel');const btn=document.getElementById(pfx+'MapWeaponRangeFilterBtn');const body=document.getElementById(pfx+'MapWeaponRangeFilterBody');if(!panel||!btn)return;const willOpen=panel.hidden;closeAllFilterPanels();if(willOpen){if(body)body.innerHTML=buildUnitMapWeaponRangeFilterHtml();panel.hidden=false;btn.setAttribute('aria-expanded','true');ensureFilterPanelFooter(pfx+'MapWeaponRangeFilterPanel',mapWeaponRangeFooterOpts(pfx));syncMapWeaponRangeCombineFooter(pfx)}}
function onUnitMapWeaponRangeChange(){updateUnitMapWeaponRangeFilterLabel();if(S.currentTab==='ranking'&&S.ranking&&S.ranking.mode==='units')scheduleRankingListReload();else scheduleBrowseListReload('units')}
function onUnitMapWeaponRangeRowClick(v,ev){if(ev){ev.preventDefault();ev.stopPropagation()}const sk=unitMapWeaponRangeStateKey();let sel=Array.isArray(S[sk])?S[sk].slice():[];const sv=normalizeMapWeaponRangeToken(v);if(sel.map(normalizeMapWeaponRangeToken).includes(sv))sel=sel.filter(x=>normalizeMapWeaponRangeToken(x)!==sv);else sel.push(sv);if(sv==='2'&&!sel.map(normalizeMapWeaponRangeToken).includes('2'))sel=sel.filter(x=>normalizeMapWeaponRangeToken(x)!=='2:snipe');S[sk]=sel;syncUnitMapWeaponRangeCheckboxes();onUnitMapWeaponRangeChange()}
function onUnitMapWeaponRangeRowKey(ev,v){if(ev.key!=='Enter'&&ev.key!==' ')return;ev.preventDefault();onUnitMapWeaponRangeRowClick(v,ev)}
function updateUnitMapWeaponRangeFilterLabel(forcePfx){const pfx=forcePfx||unitWeaponRangeDomPrefix();const sk=pfx==='rankUnit'?'listRankUnitMapWeaponRange':'listUnitMapWeaponRange';const label=document.getElementById(pfx+'MapWeaponRangeFilterLabel');const btn=document.getElementById(pfx+'MapWeaponRangeFilterBtn');if(!label||!btn)return;btn.title=t('unit_filter_map_weapon_range');let sel=S[sk];if(!Array.isArray(sel))sel=[];sel=sel.map(normalizeMapWeaponRangeToken);if(!sel.length){label.innerHTML=`<span class="source-filter-btn-plain">${esc(t('unit_filter_map_weapon_range_all'))}</span>`;btn.classList.remove('active');return}btn.classList.add('active');if(sel.length===1){const txt=mapWeaponRangeFilterTokenLabel(sel[0]);const ic=mapWeaponRangeFilterIconHtml(sel[0],true);label.innerHTML=ic?`<span class="map-wrt-filter-toolbar-label">${ic}<span class="source-filter-btn-plain" style="font-size:13px;font-weight:600">${esc(txt)}</span></span>`:`<span class="source-filter-btn-plain" style="font-size:13px;font-weight:600">${esc(txt)}</span>`;return}label.innerHTML=`<span class="source-filter-btn-plain">${esc(t('unit_filter_map_weapon_range_multi').replace('{n}',String(sel.length)))}</span>`}
function clearUnitMapWeaponRangeOnly(){const sk=unitMapWeaponRangeStateKey();const rk=S.currentTab==='ranking'&&S.ranking&&S.ranking.mode==='units';if(!rk)cancelBrowseListReloadTimer('units');S[sk]=[];const pfx=unitWeaponRangeDomPrefix();const body=document.getElementById(pfx+'MapWeaponRangeFilterBody');if(body)body.innerHTML=buildUnitMapWeaponRangeFilterHtml();syncMapWeaponRangeCombineFooter(pfx);updateUnitMapWeaponRangeFilterLabel();if(rk)void loadRankingList(1);else loadUnits(1)}
