function updateUnitMechanismFilterLabel(forcePfx){const pfx=forcePfx||unitMechanismDomPrefix();const sk=pfx==='rankUnit'?'listRankUnitMechanism':'listUnitMechanism';const label=document.getElementById(pfx+'MechanismFilterLabel');const btn=document.getElementById(pfx+'MechanismFilterBtn');if(!label||!btn)return;btn.title=t('unit_filter_mechanism_tt');let sel=S[sk];if(!Array.isArray(sel))sel=[];if(!sel.length){label.innerHTML=`<span class="source-filter-btn-plain">${esc(t('unit_filter_mechanism_all'))}</span>`;btn.classList.remove('active');return}btn.classList.add('active');if(sel.length===1){const rows=Array.isArray(S.mechanismPresentRows)?S.mechanismPresentRows:[];const found=rows.find(r=>String(r&&r.id||'')===String(sel[0]));const txt=found?(found.name||sel[0]):String(sel[0]);const ic=found&&found.icon?`<img class="filter-inline-icon role-filter-chip" src="${imgUrl(found.icon)}" alt="" role="presentation">`:'';label.innerHTML=`${ic}<span class="source-filter-btn-plain" style="margin-left:4px;font-size:13px;font-weight:600">${esc(txt)}</span>`;return}label.innerHTML=`<span class="source-filter-btn-plain">${esc(t('unit_filter_mechanism_multi').replace('{n}',String(sel.length)))}</span>`}
function clearUnitMechanismOnly(){const sk=unitMechanismStateKey();const rk=S.currentTab==='ranking'&&S.ranking&&S.ranking.mode==='units';if(!rk)cancelBrowseListReloadTimer('units');S[sk]=[];const pfx=unitMechanismDomPrefix();const body=document.getElementById(pfx+'MechanismFilterBody');if(body)body.innerHTML=buildUnitMechanismFilterHtml();updateUnitMechanismFilterLabel();if(rk)void loadRankingList(1);else loadUnits(1)}
function getLineageQuerySuffix(which){const key=listLineageKey(which);let sel=S[key];if(sel==='ALL'||!sel)sel=[];if(!Array.isArray(sel))sel=[];if(!sel.length)return '';return '&lineage_id='+encodeURIComponent(sel.join(','))}
function getSeriesQuerySuffix(which){let sel=S[listSeriesKey(which)];if(sel==='ALL'||!sel)sel=[];if(!Array.isArray(sel)){if(String(sel).trim())sel=[String(sel)];else sel=[]}if(!sel.length)return '';return '&series_id='+encodeURIComponent(sel.join(','))}
function getSkillOrAbilityQuerySuffix(which){const isCharSide=which==='char'||which==='rankChar';const key=isCharSide?(which==='rankChar'?'listRankCharSkills':'listCharSkills'):(which==='rankUnit'?'listRankUnitAbilities':'listUnitAbilities');let sel=S[key];if(sel==='ALL'||!sel)sel=[];if(!Array.isArray(sel))sel=[];if(!sel.length)return '';const param=isCharSide?'skill_id':'ability_id';return '&'+param+'='+encodeURIComponent(sel.join(','))}
function expandUnitSearchQuery(q){let s=String(q||'').trim();if(!s)return'';s=s.replace(/\bdevil\s+gundam\b/gi,'dark gundam');s=s.replace(/\bfatb\b/gi,'full armor gundam thunderbolt');s=s.replace(/\bsf\b/gi,'strike freedom');s=s.replace(/\bgod\b/gi,'burning gundam');s=s.replace(/\bij\b/gi,'infinite justice');return s.trim()}
function expandTbPickerSearchQuery(q,type){if(type==='unit')return expandUnitSearchQuery(q);if(type==='character'){let s=String(q||'').trim();s=s.replace(/\bdevil\s+gundam\b/gi,'dark gundam');s=s.replace(/\bfatb\b/gi,'full armor gundam thunderbolt');s=s.replace(/\bsf\b/gi,'strike freedom');s=s.replace(/\bgod\b/gi,'burning gundam');s=s.replace(/\bij\b/gi,'infinite justice');return s.trim()}return String(q||'').trim()}
function buildBrowsePoolQuery(which){if(which==='supp'){const qEl=document.getElementById('suppFilter');const q=(qEl&&qEl.value.trim())||'';const rq=getRarityQuerySuffix('supp');const linQ=getLineageQuerySuffix('supp');const linOp=getLineageOpSuffix('supp');return `q=${encodeURIComponent(q)}${rq}${linQ}${linOp}`}if(which==='mod'){const qEl=document.getElementById('modFilter');const q=(qEl&&qEl.value.trim())||'';const rq=getRarityQuerySuffix('mod');const ef=encodeURIComponent((S.modifications&&S.modifications.effectFilter)||'ALL');const linQ=getLineageQuerySuffix('mod');const linOp=getLineageOpSuffix('mod');return `q=${encodeURIComponent(q)}${rq}&effect=${ef}${linQ}${linOp}`}const qEl=document.getElementById(which==='char'?'charFilter':'unitFilter');const qRaw=(qEl&&qEl.value.trim())||'';const q=(which==='unit'||which==='char')?expandUnitSearchQuery(qRaw):qRaw;const roleQ=getRoleQuerySuffix(which);const rq=getRarityQuerySuffix(which);const stQ=which==='unit'?getListStatQuery('unit'):'';const srcQ=getSourceQuerySuffix(which);const terrQ=which==='unit'?getUnitTerrainQuerySuffix():'';const terrOp=which==='unit'?getTerrainOpSuffix():'';const debQ=which==='unit'?getUnitWeaponDebuffQuerySuffix():'';const debOp=which==='unit'?getWeaponDebuffOpSuffix():'';const wrQ=which==='unit'?getUnitWeaponRangeQuerySuffix():'';const wrOp=which==='unit'?getWeaponRangeOpSuffix():'';const wrnmQ=which==='unit'?getUnitWeaponRangeNonMapQuerySuffix():'';const wrnmOp=which==='unit'?getWeaponRangeNonMapOpSuffix():'';const wrnmSex=which==='unit'&&S.listUnitWeaponRangeNonMapSspExOnly?'&weapon_range_non_map_ssp_ex=1':'';const mwrQ=which==='unit'?getUnitMapWeaponRangeQuerySuffix():'';const mwrOp=which==='unit'?getMapWeaponRangeOpSuffix():'';const mechQ=which==='unit'?getUnitMechanismQuerySuffix():'';const mechOp=which==='unit'?getMechanismOpSuffix():'';const linQ=getLineageQuerySuffix(which);const linOp=getLineageOpSuffix(which);const serQ=getSeriesQuerySuffix(which);const serOp=getSeriesOpSuffix(which);const skAb=getSkillOrAbilityQuerySuffix(which);const skOp=which==='char'?getCharSkillOpSuffix():getUnitBrowseAbilityOpSuffix();const abQ=which==='char'?getAbilityQuerySuffix(which):'';const traitOp=which==='char'?getCharTraitAbilityOpSuffix():'';return `q=${encodeURIComponent(q)}${roleQ}${rq}${stQ}${srcQ}${terrQ}${terrOp}${debQ}${debOp}${wrQ}${wrOp}${wrnmQ}${wrnmOp}${wrnmSex}${mwrQ}${mwrOp}${mechQ}${mechOp}${linQ}${linOp}${serQ}${serOp}${skAb}${skOp}${abQ}${traitOp}`}
function buildBrowsePoolSig(which){if(which==='supp'){const qEl=document.getElementById('suppFilter');const q=(qEl&&qEl.value.trim().toLowerCase())||'';const rq=getRarityQuerySuffix('supp');const linQ=getLineageQuerySuffix('supp');const linOp=getLineageOpSuffix('supp');return [q,rq,linQ,linOp,S.browseCombSuppLineage].join('|')}if(which==='mod'){const qEl=document.getElementById('modFilter');const q=(qEl&&qEl.value.trim().toLowerCase())||'';const rq=getRarityQuerySuffix('mod');const ef=((S.modifications&&S.modifications.effectFilter)||'ALL');const linQ=getLineageQuerySuffix('mod');const linOp=getLineageOpSuffix('mod');return [q,rq,ef,linQ,linOp,S.browseCombModLineage].join('|')}const qEl=document.getElementById(which==='char'?'charFilter':'unitFilter');const q=(qEl&&qEl.value.trim().toLowerCase())||'';const roleQ=getRoleQuerySuffix(which);const rq=getRarityQuerySuffix(which);const stQ=which==='unit'?getListStatQuery('unit'):'';const srcQ=getSourceQuerySuffix(which);const terrQ=which==='unit'?getUnitTerrainQuerySuffix():'';const terrOp=which==='unit'?getTerrainOpSuffix():'';const debQ=which==='unit'?getUnitWeaponDebuffQuerySuffix():'';const debOp=which==='unit'?getWeaponDebuffOpSuffix():'';const wrQ=which==='unit'?getUnitWeaponRangeQuerySuffix():'';const wrOp=which==='unit'?getWeaponRangeOpSuffix():'';const wrnmQ=which==='unit'?getUnitWeaponRangeNonMapQuerySuffix():'';const wrnmOp=which==='unit'?getWeaponRangeNonMapOpSuffix():'';const wrnmSex=which==='unit'&&S.listUnitWeaponRangeNonMapSspExOnly?'&weapon_range_non_map_ssp_ex=1':'';const mechQ=which==='unit'?getUnitMechanismQuerySuffix():'';const mechOp=which==='unit'?getMechanismOpSuffix():'';const linQ=getLineageQuerySuffix(which);const linOp=getLineageOpSuffix(which);const serQ=getSeriesQuerySuffix(which);const serOp=getSeriesOpSuffix(which);const skAb=getSkillOrAbilityQuerySuffix(which);const skOp=which==='char'?getCharSkillOpSuffix():getUnitBrowseAbilityOpSuffix();const abQ=which==='char'?getAbilityQuerySuffix(which):'';const traitOp=which==='char'?getCharTraitAbilityOpSuffix():'';const opState=which==='char'?[S.browseCombCharLineage,S.browseCombCharSeries,S.browseCombCharSkill,S.browseCombCharTrait].join(','):[S.browseCombUnitLineage,S.browseCombUnitSeries,S.browseCombUnitAbil,S.browseCombTerrain,S.browseCombWb,S.browseCombWr,S.browseCombWrNm,S.browseCombMapWr,S.browseCombMech].join(',');return [q,roleQ,rq,stQ,srcQ,terrQ,terrOp,debQ,debOp,wrQ,wrOp,wrnmQ,wrnmOp,wrnmSex,(which==='unit'?getUnitMapWeaponRangeQuerySuffix():''),(which==='unit'?getMapWeaponRangeOpSuffix():''),mechQ,mechOp,linQ,linOp,serQ,serOp,skAb,skOp,abQ,traitOp,opState].join('|')}
function buildMsyBrowsePoolQuery(){const roleQ=getRoleQuerySuffix('msyUnit');const rq=getRarityQuerySuffix('msyUnit');const srcQ=getSourceQuerySuffix('msyUnit');const serQ=getSeriesQuerySuffix('msyUnit');const serOp=getSeriesOpSuffix('msyUnit');const linQ=getLineageQuerySuffix('msyUnit');const linOp=getLineageOpSuffix('msyUnit');return `q=${encodeURIComponent('')}${roleQ}${rq}${srcQ}${serQ}${serOp}${linQ}${linOp}`}
