async function ensureBrowseFiltersEntity(entity){if(entity!=='char'&&entity!=='unit'&&entity!=='supp'&&entity!=='mod')return;const sigField=entity==='char'?'_poolSigChar':entity==='unit'?'_poolSigUnit':entity==='mod'?'_poolSigMod':'_poolSigSupp';const sig=buildBrowsePoolSig(entity);const cur=S._browseFiltersByEntity;if(cur&&cur._lang===S.lang&&cur[sigField]===sig)return;const infl='_bfInfl'+entity;if(S[infl])return S[infl];S[infl]=(async()=>{const q=buildBrowsePoolQuery(entity);const apiEnt=entity==='char'?'characters':entity==='unit'?'units':entity==='mod'?'option_parts':'supporters';const langAtStart=S.lang;try{const r=await fetch(`/api/browse_filters?lang=${S.lang}&entity=${apiEnt}&filter_mode=current&${q}`);const data=await r.json();if(S.lang!==langAtStart)return;if(!S._browseFiltersByEntity||S._browseFiltersByEntity._lang!==S.lang){S._browseFiltersByEntity={_lang:S.lang,_poolSigChar:null,_poolSigUnit:null,_poolSigSupp:null,_poolSigMod:null,char:{lineages:[],series:[],skills:[],abilities:[]},unit:{lineages:[],series:[],abilities:[]},supp:{lineages:[]},mod:{lineages:[]}}}const b=S._browseFiltersByEntity;b[sigField]=sig;if(entity==='char'){b.char={lineages:data.lineages||[],series:data.series||[],skills:data.skills||[],abilities:data.abilities||[]}}else if(entity==='unit'){b.unit={lineages:data.lineages||[],series:data.series||[],abilities:data.abilities||[]}}else if(entity==='mod'){b.mod={lineages:data.lineages||[]}}else{b.supp={lineages:data.lineages||[]}}}catch(e){if(S.lang!==langAtStart)return;if(!S._browseFiltersByEntity||S._browseFiltersByEntity._lang!==S.lang){S._browseFiltersByEntity={_lang:S.lang,_poolSigChar:null,_poolSigUnit:null,_poolSigSupp:null,_poolSigMod:null,char:{lineages:[],series:[],skills:[],abilities:[]},unit:{lineages:[],series:[],abilities:[]},supp:{lineages:[]},mod:{lineages:[]}}}const b=S._browseFiltersByEntity;b[sigField]=sig;if(entity==='char'){b.char={lineages:[],series:[],skills:[],abilities:[]}}else if(entity==='unit'){b.unit={lineages:[],series:[],abilities:[]}}else if(entity==='mod'){b.mod={lineages:[]}}else{b.supp={lineages:[]}}}finally{S[infl]=null}})();return S[infl]}
async function ensureBrowseFiltersMeta(){await Promise.all([ensureBrowseFiltersEntity('char'),ensureBrowseFiltersEntity('unit'),ensureBrowseFiltersEntity('supp'),ensureBrowseFiltersEntity('mod')])}
/** Warm filter pools after browse paint — never race /api/characters on cold applyLang. */
function scheduleBrowseFiltersMetaWarmup(){
  if(S._bfMetaWarmScheduled)return;
  S._bfMetaWarmScheduled=1;
  const go=()=>{
    void ensureBrowseFiltersMeta().then(()=>{
      ['char','unit','supp','mod','rankChar','rankUnit'].forEach(p=>updateLineageFilterButtonLabel(p));
      ['char','unit','rankChar','rankUnit'].forEach(p=>{updateSeriesFilterButtonLabel(p);updateSkillBrowseFilterLabel(p)});
      ['char','rankChar'].forEach(p=>updateAbilBrowseFilterLabel(p));
    }).catch(()=>{});
  };
  if(window.requestIdleCallback)requestIdleCallback(go,{timeout:12000});
  else setTimeout(go,5000);
}
