function updateSeriesFilterButtonLabel(which){const domP=which==='char'?'char':(which==='rankChar'?'rankChar':(which==='rankUnit'?'rankUnit':(which==='msyUnit'?'msyUnit':'unit')));const key=listSeriesKey(which);let sel=S[key];if(sel==='ALL'||!sel)sel=[];if(!Array.isArray(sel)){if(String(sel).trim())sel=[String(sel)];else sel=[]}const label=document.getElementById(domP+'SeriesFilterLabel');const btn=document.getElementById(domP+'SeriesFilterBtn');if(!label||!btn)return;const seriesRows=filterSeriesRowsForLabel(which);const rowForSid=sid=>seriesRows.find(x=>String(x.id)===String(sid));if(sel.length===0){label.innerHTML=`<span class="list-filter-btn-mini series-filter-btn-all" title="${escAttr(t('series_filter_all_brand'))}"><img class="filter-inline-icon role-filter-chip" src="${imgUrl(SERIES_FILTER_ALL_LOGO)}" alt="" role="presentation"><span class="source-filter-btn-plain">${esc(t('filter_series_all'))}</span></span>`;btn.classList.remove('active');btn.title=t('list_filter_series');return}btn.classList.add('active');const names=sel.map(id=>{const f=rowForSid(id);return f&&f.name?String(f.name):String(id)});btn.title=names.join(', ');const iconsHtml=sel.map(id=>{const f=rowForSid(id);const nm=f&&f.name?String(f.name):String(id);const ic=f&&f.icon;if(ic)return`<img class="series-filter-toolbar-ic" src="${imgUrl(ic)}" alt="" role="presentation" title="${escAttr(nm)}">`;return`<span class="series-filter-toolbar-fallback" title="${escAttr(nm)}"></span>`}).join('');label.innerHTML=`<span class="series-filter-toolbar-icons">${iconsHtml}</span>`}
async function toggleLineagePanel(which,ev){if(ev)ev.stopPropagation();const domP=which==='char'?'char':(which==='rankChar'?'rankChar':(which==='supp'?'supp':(which==='mod'?'mod':(which==='rankUnit'?'rankUnit':(which==='msyUnit'?'msyUnit':'unit')))));const panel=document.getElementById(domP+'LineageFilterPanel');const btn=document.getElementById(domP+'LineageFilterBtn');const body=document.getElementById(domP+'LineageFilterBody');if(!panel||!btn)return;const willOpen=panel.hidden;closeAllFilterPanels();if(willOpen){panel.hidden=false;btn.setAttribute('aria-expanded','true');if(which==='rankChar'||which==='rankUnit'){await ensureRankingBrowseFiltersEntity(which);if(body&&browseFilterPanelNeedsRebuildRanking(body,which)){body.innerHTML=buildLineageFilterHtml(domP);markBrowseFilterPanelBuiltRanking(body,which)}}else if(which==='msyUnit'){await ensureMsyBrowseFilters();if(body&&browseFilterPanelNeedsRebuildMsy(body)){body.innerHTML=buildLineageFilterHtml(domP);markBrowseFilterPanelBuiltMsy(body)}}else{await ensureBrowseFiltersEntity(domP);if(body&&browseFilterPanelNeedsRebuild(body,domP)){body.innerHTML=buildLineageFilterHtml(domP);markBrowseFilterPanelBuilt(body,domP)}}syncLineageCheckboxes(domP);syncBrowseLineageNameHints(domP);ensureFilterPanelFooter(domP+'LineageFilterPanel',{onClear:()=>clearLineageOnly(domP),combineKey:lineageCombineKeyFor(which),combineEntity:lineageCombineEntityFor(which)});focusFilterSearchInput(domP+'LineageFilterPanel','')}}
