function onSeriesItemChange(p){const key=listSeriesKey(p);const checked=Array.from(document.querySelectorAll(`input[name="${p}SeriesSel"].series-filter-item:checked`)).map(i=>i.value);S[key]=checked.length?checked:[];updateSeriesFilterButtonLabel(p);if(p==='char')scheduleBrowseListReload('characters');else if(p==='unit')scheduleBrowseListReload('units');else if(p==='msyUnit'){msyBrowseFilterApplied();if(window.GgenMetaSynergy&&typeof GgenMetaSynergy.scheduleReload==='function')GgenMetaSynergy.scheduleReload()}else if(p==='rankChar'||p==='rankUnit')scheduleRankingListReload()}
function onLineageItemChange(p){const domP=p==='char'?'char':(p==='rankChar'?'rankChar':(p==='supp'?'supp':(p==='mod'?'mod':(p==='rankUnit'?'rankUnit':(p==='msyUnit'?'msyUnit':'unit')))));delete S['_linLblRf'+domP];const key=listLineageKey(p);const checked=Array.from(document.querySelectorAll(`input[name="${p}LineageSel"].lineage-filter-item:checked`)).map(i=>String(i.value));const prev=Array.isArray(S[key])?S[key]:[];const next=[];prev.forEach(id=>{const hit=checked.find(c=>lineageIdsMatch(c,id));if(hit&&!next.some(x=>lineageIdsMatch(x,hit)))next.push(hit)});checked.forEach(id=>{if(!next.some(x=>lineageIdsMatch(x,id)))next.push(id)});S[key]=next.length?next:[];syncLineageCombinePriorityMark(p);syncBrowseLineageNameHints(p);updateLineageFilterButtonLabel(p);if(p==='char'){browseListJsonCacheClearPrefix('/api/characters?');scheduleBrowseListReload('characters')}else if(p==='supp'){browseListJsonCacheClearPrefix('/api/supporters?');scheduleBrowseListReload('supporters')}else if(p==='mod'){browseListJsonCacheClearPrefix('/api/option_parts?');scheduleBrowseListReload('modifications')}else if(p==='unit'){browseListJsonCacheClearPrefix('/api/units?');scheduleBrowseListReload('units')}else if(p==='msyUnit'){msyBrowseFilterApplied();if(window.GgenMetaSynergy&&typeof GgenMetaSynergy.scheduleReload==='function')GgenMetaSynergy.scheduleReload()}else if(p==='rankChar'||p==='rankUnit')scheduleRankingListReload()}
function listStatQChar(sp,cond){let q='';if(sp)q+='&sp=1';if(cond)q+='&cond=1';return q}
function listStatQUnit(sp,ssp,cond,pilotCond){let q='';if(ssp)q+='&stat_mode=ssp';else if(sp)q+='&stat_mode=sp';if(cond)q+='&cond=1';if(pilotCond)q+='&pilot_cond=1';return q}
function getListStatQuery(which){if(which==='char')return listStatQChar(!!S.listCharSp,!!S.listCharCond);if(which==='unit')return listStatQUnit(!!S.listUnitSp,!!S.listUnitSsp,!!S.listUnitCond,!!S.listUnitPilotCond);return ''}
const BROWSE_LIST_JSON_CACHE_MAX=128;
const _browseListJsonCache=new Map();
function browseListJsonCacheGet(url){return _browseListJsonCache.get(url)}
const FETCH_JSON_ETAG_CACHE_MAX=128;
const _fetchJsonEtagCache=new Map();
function _fetchJsonEtagCacheSet(url,etag,data){if(!url||!etag||data==null)return;_fetchJsonEtagCache.set(url,{etag,data});while(_fetchJsonEtagCache.size>FETCH_JSON_ETAG_CACHE_MAX){const k=_fetchJsonEtagCache.keys().next().value;_fetchJsonEtagCache.delete(k)}}
function _fetchJsonEtagCacheClearPrefix(pfx){for(const k of _fetchJsonEtagCache.keys()){if(String(k).startsWith(pfx))_fetchJsonEtagCache.delete(k)}}
async function waitForBrowseReady(maxWaitMs=90000){const t0=Date.now();let gap=400;while(Date.now()-t0<maxWaitMs){try{const r=await fetch('/health',{cache:'no-store'});const d=await r.json().catch(()=>({}));if(d&&d.browse_ready===true)return true;if(d&&d.phase==='error')return false}catch(_){}await new Promise(res=>setTimeout(res,gap));gap=Math.min(Math.round(gap*1.25),2000)}return false}
async function fetchJsonWithWarmupRetry(url,{maxRetries=40,timeoutMs=45000,priority}={}){let waitMs=400;for(let i=0;i<maxRetries;i++){const ctrl=typeof AbortController!=='undefined'?new AbortController():null;const timer=ctrl?setTimeout(()=>{try{ctrl.abort()}catch(_){}},timeoutMs):null;try{const prev=_fetchJsonEtagCache.get(url);const headers={};if(prev&&prev.etag)headers['If-None-Match']=prev.etag;const fetchOpts=ctrl?{signal:ctrl.signal,headers}:{headers};if(priority)fetchOpts.priority=priority;const r=await fetch(url,fetchOpts);if(r.status===304&&prev&&prev.data!=null)return{ok:true,status:304,data:prev.data};let d;try{d=await r.json()}catch(_){d={}}if(r.status===503&&d&&d.error==='warming_up'){if(typeof setBrowseToolbarCount==='function'){try{const pfx=/\/api\/units\b/.test(url)?'unit':(/\/api\/characters\b/.test(url)?'char':'');if(pfx)setBrowseToolbarCount(pfx,'<span style="color:var(--text-muted)">Warming up…</span>')}catch(_){}}if(i===0){try{await waitForBrowseReady(Math.min(25000,timeoutMs))}catch(_){}}else{await new Promise(res=>setTimeout(res,waitMs));waitMs=Math.min(Math.round(waitMs*1.35),2000)}continue}if(r.ok){const etag=r.headers.get('ETag');if(etag)_fetchJsonEtagCacheSet(url,etag,d)}return{ok:r.ok,status:r.status,data:d}}catch(e){if(i+1>=maxRetries)return{ok:false,status:0,data:{error:String(e&&e.message||e)}};await new Promise(res=>setTimeout(res,waitMs));waitMs=Math.min(Math.round(waitMs*1.35),2000)}finally{if(timer)clearTimeout(timer)}}return{ok:false,status:503,data:{error:'warming_up'}}}
async function fetchBrowseJson(url,{timeoutMs=30000}={}){const ctrl=typeof AbortController!=='undefined'?new AbortController():null;const timer=ctrl?setTimeout(()=>{try{ctrl.abort()}catch(_){}},timeoutMs):null;try{const prev=_fetchJsonEtagCache.get(url);const headers={};if(prev&&prev.etag)headers['If-None-Match']=prev.etag;const fetchOpts=ctrl?{signal:ctrl.signal,headers}:{headers};const r=await fetch(url,fetchOpts);if(r.status===304&&prev&&prev.data!=null)return{ok:true,status:304,data:prev.data};const d=await r.json().catch(()=>({}));if(r.ok){const etag=r.headers.get('ETag');if(etag)_fetchJsonEtagCacheSet(url,etag,d)}return{ok:r.ok,status:r.status,data:d}}catch(e){return{ok:false,status:0,data:{error:String(e&&e.message||e)}}}finally{if(timer)clearTimeout(timer)}}
function showBrowseLoadError(pfx,msg){showLoad(pfx,false);const em=document.getElementById(pfx+'Empty');if(em){em.style.display='block';const txt=em.querySelector('.empty-state-text');if(txt)txt.textContent=msg||t('empty_char')}setBrowseToolbarCount(pfx,'')}
function browseListJsonCacheSet(url,d){if(!d||typeof d.total!=='number')return;_browseListJsonCache.set(url,d);while(_browseListJsonCache.size>BROWSE_LIST_JSON_CACHE_MAX){const k=_browseListJsonCache.keys().next().value;_browseListJsonCache.delete(k)}}
function browseListJsonCacheClearPrefix(pfx){for(const k of _browseListJsonCache.keys()){if(String(k).startsWith(pfx))_browseListJsonCache.delete(k)}_fetchJsonEtagCacheClearPrefix(pfx);if(String(pfx).indexOf('/api/units')>=0){instantBrowseInvalidate('units');instantBrowseInvalidate('rankUnits')}if(String(pfx).indexOf('/api/characters')>=0){instantBrowseInvalidate('characters');instantBrowseInvalidate('rankCharacters')}if(String(pfx).indexOf('/api/supporters')>=0)instantBrowseInvalidate('supporters');if(String(pfx).indexOf('/api/stages')>=0)instantBrowseInvalidate('stages');if(String(pfx).indexOf('/api/option_parts')>=0)instantBrowseInvalidate('modifications')}
function buildStagesListUrl(p,pp){const s=S.stages;const dfSel=s.difficultyFilter==='ALL'?'':s.difficultyFilter;const src=s.source||'eternal';const cat=src==='score_attack'?'score_attack':src==='special_stage'?'special_stage':src==='tower_stage'?'tower_stage':src==='challenge_stage'?'challenge_stage':'eternal';const df=(cat==='eternal')?dfSel:'';const ts=(s.towerSide==='E'||s.towerSide==='W')?s.towerSide:'ALL';const cs=challengeSeriesValidId(s.challengeSeries)&&s.challengeSeries!=='ALL'?s.challengeSeries:'ALL';return`/api/stages?lang=${S.lang}&page=${p}&per_page=${pp}&q=${encodeURIComponent(s.q)}&difficulty=${encodeURIComponent(df)}&sort=${s.sort}&dir=${s.dir}&category=${encodeURIComponent(cat)}&tower_side=${encodeURIComponent(ts)}&challenge_series=${encodeURIComponent(cs)}`}
function buildCharactersListUrl(p,pp,sp,cond){const s=S.characters;const q=document.getElementById('charFilter').value.trim();const roleQ=getRoleQuerySuffix('char');const rq=getRarityQuerySuffix('char');const stQ=listStatQChar(!!sp,!!cond);const srcQ=getSourceQuerySuffix('char');const linQ=getLineageQuerySuffix('char');const linOp=getLineageOpSuffix('char');const serQ=getSeriesQuerySuffix('char');const serOp=getSeriesOpSuffix('char');const skillQ=getSkillOrAbilityQuerySuffix('char');const skOp=getCharSkillOpSuffix();const abilQ=getAbilityQuerySuffix('char');const traitOp=getCharTraitAbilityOpSuffix();const gsQ=getListViewMode('characters')==='grid'&&getListGridVariant('characters')===2?'&grid_skills=1':'';return`/api/characters?lang=${S.lang}&page=${p}&per_page=${pp}&sort=${s.sort}&dir=${s.dir}&q=${encodeURIComponent(q)}${roleQ}${rq}${stQ}${srcQ}${linQ}${linOp}${serQ}${serOp}${skillQ}${skOp}${abilQ}${traitOp}${gsQ}`}
function buildUnitsListApiUrl(p,pp,sp,ssp,cond,pilotCond){const s=S.units;const qRaw=document.getElementById('unitFilter').value.trim();const qApi=expandUnitSearchQuery(qRaw);const roleQ=getRoleQuerySuffix('unit');const rq=getRarityQuerySuffix('unit');const stQ=listStatQUnit(!!sp,!!ssp,!!cond,!!pilotCond);const srcQ=getSourceQuerySuffix('unit');const terrQ=getUnitTerrainQuerySuffix();const terrOp=getTerrainOpSuffix();const debQ=getUnitWeaponDebuffQuerySuffix();const debOp=getWeaponDebuffOpSuffix();const wrQ=getUnitWeaponRangeQuerySuffix();const wrOp=getWeaponRangeOpSuffix();const wrnmQ=getUnitWeaponRangeNonMapQuerySuffix();const wrnmOp=getWeaponRangeNonMapOpSuffix();const wrnmSex=S.listUnitWeaponRangeNonMapSspExOnly?'&weapon_range_non_map_ssp_ex=1':'';const mwrQ=getUnitMapWeaponRangeQuerySuffix();const mwrOp=getMapWeaponRangeOpSuffix();const mechQ=getUnitMechanismQuerySuffix();const mechOp=getMechanismOpSuffix();const linQ=getLineageQuerySuffix('unit');const linOp=getLineageOpSuffix('unit');const serQ=getSeriesQuerySuffix('unit');const serOp=getSeriesOpSuffix('unit');const abQ=getSkillOrAbilityQuerySuffix('unit');const abOp=getUnitBrowseAbilityOpSuffix();const gsU=getListViewMode('units')==='grid'&&getListGridVariant('units')===2?'&grid_skills=1':'';return`/api/units?lang=${S.lang}&page=${p}&per_page=${pp}&sort=${s.sort}&dir=${s.dir}&q=${encodeURIComponent(qApi)}${roleQ}${rq}${stQ}${srcQ}${terrQ}${terrOp}${debQ}${debOp}${wrQ}${wrOp}${wrnmQ}${wrnmOp}${wrnmSex}${mwrQ}${mwrOp}${mechQ}${mechOp}${linQ}${linOp}${serQ}${serOp}${abQ}${abOp}${gsU}`}
function loadPersistedListView(){const def={characters:'grid',units:'grid',supporters:'grid',stages:'grid',modifications:'grid'};try{const s=localStorage.getItem('ggen_list_view');if(s){const o=JSON.parse(s);Object.keys(def).forEach(k=>{if(o[k]==='grid'||o[k]==='table')def[k]=o[k]})}}catch(e){}S.listView=def}
function persistListView(){try{localStorage.setItem('ggen_list_view',JSON.stringify(S.listView))}catch(e){}}
function getListViewMode(tab){if(tab==='stages')return'grid';return(S.listView&&S.listView[tab])||'grid'}
function syncListViewToggleUI(tab){if(tab==='stages')return;const mode=getListViewMode(tab);const map={characters:['charViewGrid','charViewTable'],units:['unitViewGrid','unitViewTable'],supporters:['suppViewGrid','suppViewTable'],modifications:['modViewGrid','modViewTable']};const m=map[tab];if(!m)return;const g=document.getElementById(m[0]),tb=document.getElementById(m[1]);if(g)g.classList.toggle('active',mode==='grid');if(tb)tb.classList.toggle('active',mode==='table');if(tab==='characters')syncGridVariantBadge('char');else if(tab==='units')syncGridVariantBadge('unit')}
function applyListViewVisibility(tab){const map={characters:{tw:'charTableWrap',gw:'charGridWrap'},units:{tw:'unitTableWrap',gw:'unitGridWrap'},supporters:{tw:'suppTableWrap',gw:'suppGridWrap'},stages:{tw:'stageTableWrap',gw:'stageGridWrap'},modifications:{tw:'modTableWrap',gw:'modGridWrap'}};const m=map[tab];if(!m)return;const mode=getListViewMode(tab);const tw=document.getElementById(m.tw),gw=document.getElementById(m.gw);if(!tw||!gw)return;const isGrid=mode==='grid';tw.hidden=isGrid;gw.hidden=!isGrid;if(tab==='characters')syncGridVariantBadge('char');else if(tab==='units')syncGridVariantBadge('unit');scheduleSyncListTheadStickyTop()}
function setListViewMode(tab,mode){if(tab==='stages')return;if(!S.listView||S.listView[tab]===undefined)return;if(S.listView[tab]===mode)return;S.listView[tab]=mode;persistListView();syncListViewToggleUI(tab);applyListViewVisibility(tab);if(tab==='characters')loadCharacters(S.characters.page||1);else if(tab==='units')loadUnits(S.units.page||1);else if(tab==='supporters')loadSupporters(S.supporters.page||1);else if(tab==='modifications')loadModifications(S.modifications.page||1)}
function updateListViewToggleLabels(){const pairs=[['charViewGrid','charViewTable'],['unitViewGrid','unitViewTable'],['suppViewGrid','suppViewTable'],['modViewGrid','modViewTable']];pairs.forEach(([gid,tid])=>{const ge=document.getElementById(gid),te=document.getElementById(tid);if(ge){ge.title=t('view_grid');ge.setAttribute('aria-label',t('view_grid'))}if(te){te.title=t('view_table');te.setAttribute('aria-label',t('view_table'))}});document.querySelectorAll('.list-view-toggle').forEach(el=>{el.setAttribute('aria-label',t('view_grid')+' / '+t('view_table'))})}
function loadPersistedListStatToggles(){try{const gc=localStorage.getItem('ggen_list_char_cond'),gs=localStorage.getItem('ggen_list_char_sp'),uc=localStorage.getItem('ggen_list_unit_cond'),up=localStorage.getItem('ggen_list_unit_pilot_cond'),us=localStorage.getItem('ggen_list_unit_sp'),ux=localStorage.getItem('ggen_list_unit_ssp');if(gc==='1')S.listCharCond=true;else if(gc==='0')S.listCharCond=false;if(gs==='1')S.listCharSp=true;else if(gs==='0')S.listCharSp=false;if(uc==='1')S.listUnitCond=true;else if(uc==='0')S.listUnitCond=false;if(up==='1')S.listUnitPilotCond=true;else if(up==='0')S.listUnitPilotCond=false;if(us==='1')S.listUnitSp=true;else if(us==='0')S.listUnitSp=false;if(ux==='1')S.listUnitSsp=true;else if(ux==='0')S.listUnitSsp=false}catch(e){}}
function persistListStatToggles(){try{localStorage.setItem('ggen_list_char_cond',S.listCharCond?'1':'0');localStorage.setItem('ggen_list_char_sp',S.listCharSp?'1':'0');localStorage.setItem('ggen_list_unit_cond',S.listUnitCond?'1':'0');localStorage.setItem('ggen_list_unit_pilot_cond',S.listUnitPilotCond?'1':'0');localStorage.setItem('ggen_list_unit_sp',S.listUnitSp?'1':'0');localStorage.setItem('ggen_list_unit_ssp',S.listUnitSsp?'1':'0')}catch(e){}}
function syncListCharToggle(){const b=document.getElementById('charListSpBtn');if(b)b.classList.toggle('active',!!S.listCharSp)}
function syncListUnitStatToggles(){const sp=document.getElementById('unitListSpBtn'),ssp=document.getElementById('unitListSspBtn');if(sp)sp.classList.toggle('active',!!S.listUnitSp);if(ssp)ssp.classList.toggle('active',!!S.listUnitSsp)}
function syncListCondToggles(){const c=document.getElementById('charListCondBtn'),u=document.getElementById('unitListCondBtn'),up=document.getElementById('unitListPilotCondBtn');if(c){c.classList.toggle('active',!!S.listCharCond);c.title=t('conditional_passive')}if(u){u.classList.toggle('active',!!S.listUnitCond);u.title=t('conditional_passive')}if(up){up.classList.toggle('active',!!S.listUnitPilotCond);up.title=t('pilot_exclusive_passive')||'Pilot Exclusive Passive'}}
function toggleListUnitPilotCond(){S.listUnitPilotCond=!S.listUnitPilotCond;syncListCondToggles();persistListStatToggles();syncWeaponRangeFilterUiForCondChange();scheduleBrowseListReload('units',S.units.page||1)}
function toggleListCharSp(){S.listCharSp=!S.listCharSp;syncListCharToggle();persistListStatToggles();scheduleBrowseListReload('characters',S.characters.page||1)}
function toggleListCharCond(){S.listCharCond=!S.listCharCond;syncListCondToggles();persistListStatToggles();scheduleBrowseListReload('characters',S.characters.page||1)}
function toggleListUnitSp(){if(S.listUnitSp){S.listUnitSp=false}else{S.listUnitSp=true;S.listUnitSsp=false}syncListUnitStatToggles();persistListStatToggles();scheduleBrowseListReload('units',S.units.page||1)}
function toggleListUnitSsp(){if(S.listUnitSsp){S.listUnitSsp=false}else{S.listUnitSsp=true;S.listUnitSp=false}syncListUnitStatToggles();persistListStatToggles();browseListJsonCacheClearPrefix('/api/units?');scheduleBrowseListReload('units',S.units.page||1)}
function syncWeaponRangeFilterUiForCondChange(){['listUnitWeaponRangeNonMap','listRankUnitWeaponRangeNonMap'].forEach(sk=>{let sel=Array.isArray(S[sk])?S[sk]:[];const pruned=sel.filter(v=>isUnitWeaponRangeNonMapAvailable(v,sk));if(pruned.length!==sel.length)S[sk]=pruned});['unit','rankUnit'].forEach(pfx=>{const nmBody=document.getElementById(pfx+'WeaponRangeNonMapFilterBody');if(nmBody)nmBody.innerHTML=buildUnitWeaponRangeNonMapFilterHtml(pfx==='rankUnit'?'listRankUnitWeaponRangeNonMap':'listUnitWeaponRangeNonMap');updateUnitWeaponRangeNonMapFilterLabel(pfx)})}
function toggleListUnitCond(){S.listUnitCond=!S.listUnitCond;syncListCondToggles();persistListStatToggles();syncWeaponRangeFilterUiForCondChange();scheduleBrowseListReload('units',S.units.page||1)}
function onRoleRowClick(which,id,ev){if(ev){ev.preventDefault();ev.stopPropagation()}const p=rolePrefix(which);if(!ROLE_LIST_IDS.includes(id))return;const boxes=ROLE_LIST_IDS.map(rid=>document.getElementById(p+'Role'+rid));ROLE_LIST_IDS.forEach((rid,i)=>{if(boxes[i])boxes[i].checked=(rid===id)});onRoleFilterChange(which)}
function onRoleRowKey(ev,which,id){if(ev.key!=='Enter'&&ev.key!==' ')return;ev.preventDefault();onRoleRowClick(which,id,ev)}
function onRoleCheckboxChange(which,id,ev){onRoleFilterChange(which)}
function onRoleFilterChange(which){updateRoleFilterButtonLabel(which);if(which==='char')scheduleBrowseListReload('characters');else if(which==='unit')scheduleBrowseListReload('units');else if(which==='msyUnit'){msyBrowseFilterApplied();if(window.GgenMetaSynergy&&typeof GgenMetaSynergy.scheduleReload==='function')GgenMetaSynergy.scheduleReload()}else if(which==='rankChar'||which==='rankUnit')scheduleRankingListReload()}
function onRarityRowClick(which,key,ev){if(ev){ev.preventDefault();ev.stopPropagation()}const p=rarityPrefix(which);const keys=rarityKeysFor(which);if(!keys.includes(key))return;const boxes=keys.map(k=>document.getElementById(p+'Rarity'+k));const ltEl=document.getElementById(p+'RarityLT');keys.forEach((k,i)=>{if(boxes[i])boxes[i].checked=(k===key)});if(ltEl)ltEl.checked=false;onRarityFilterChange(which)}
function onRarityRowKey(ev,which,key){if(ev.key!=='Enter'&&ev.key!==' ')return;ev.preventDefault();onRarityRowClick(which,key,ev)}
function onRarityStarCheckboxChange(which,key,ev){onRarityFilterChange(which)}
function onRarityLtCheckboxChange(which,ev){onRarityFilterChange(which)}
function onRarityLtRowClick(which,ev){if(ev){ev.preventDefault();ev.stopPropagation()}const p=rarityPrefix(which);const keys=rarityKeysFor(which);const boxes=keys.map(k=>document.getElementById(p+'Rarity'+k));const ltEl=document.getElementById(p+'RarityLT');keys.forEach((k,i)=>{if(boxes[i])boxes[i].checked=false});if(ltEl)ltEl.checked=true;onRarityFilterChange(which)}
function onRarityLtRowKey(ev,which){if(ev.key!=='Enter'&&ev.key!==' ')return;ev.preventDefault();onRarityLtRowClick(which,ev)}
function onRarityFilterChange(which){updateRarityFilterButtonLabel(which);if(which==='char'){const se=document.getElementById('charSkillFilterSearch'),grid=document.getElementById('charSkillGrid');if(se&&grid&&grid.dataset.populated)filterSkillDropdown('char',se.value||'');scheduleBrowseListReload('characters')}else if(which==='rankChar'){const se=document.getElementById('rankCharSkillFilterSearch'),grid=document.getElementById('rankCharSkillGrid');if(se&&grid&&grid.dataset.populated)filterSkillDropdown('rankChar',se.value||'');scheduleRankingListReload()}else if(which==='unit'){const se=document.getElementById('unitSkillFilterSearch'),grid=document.getElementById('unitSkillGrid');if(se&&grid&&grid.dataset.populated)filterSkillDropdown('unit',se.value||'');scheduleBrowseListReload('units')}else if(which==='rankUnit'){const se=document.getElementById('rankUnitSkillFilterSearch'),grid=document.getElementById('rankUnitSkillGrid');if(se&&grid&&grid.dataset.populated)filterSkillDropdown('rankUnit',se.value||'');scheduleRankingListReload()}else if(which==='msyUnit'){msyBrowseFilterApplied();if(window.GgenMetaSynergy&&typeof GgenMetaSynergy.scheduleReload==='function')GgenMetaSynergy.scheduleReload()}else if(which==='mod'){browseListJsonCacheClearPrefix('/api/option_parts?');scheduleBrowseListReload('modifications')}else scheduleBrowseListReload('supporters')}
function switchTab(tab,opts){opts=opts||{};if(tab==='meta_synergy'){tab='units';}const _prevTab=S.currentTab;if(_prevTab==='meta_synergy'&&tab!=='meta_synergy'&&window.GgenMetaSynergy&&typeof GgenMetaSynergy.onTabHidden==='function')GgenMetaSynergy.onTabHidden();if(!opts.fromPopstate&&!opts.skipHistory){const _dm=document.getElementById('detailModal');if(_dm&&_dm.classList.contains('active'))closeModalDomOnly()}S.currentTab=tab;document.querySelectorAll('.nav-tab').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));document.querySelectorAll('.tab-panel').forEach(x=>x.classList.toggle('active',x.id===`panel-${tab}`));bindSearchRecallObserver();if(document.getElementById('searchSpotlightOverlay')&&document.getElementById('searchSpotlightOverlay').classList.contains('active')){const inp=document.getElementById('searchSpotlightInput'),real=getActiveSearchInput();if(inp&&real){inp.value=real.value;if(real.classList.contains('filter-input--organic'))syncBrowseSearchWidth(real.id)}const tl=document.getElementById('searchSpotlightTabLine');if(tl)tl.textContent=getTabNameForSpotlight();debounceSpotlightResults()}if(tab==='latest_release'){tryLoadLatestRelease()}else if(tab==='banner_timeline'){armScrollTopFabBaseline();loadBannerTimeline()}else if(tab==='master_league'){armScrollTopFabBaseline();loadMasterLeague()}else if(tab==='investment_priority'){armScrollTopFabBaseline();void loadInvestmentPriority()}else if(tab==='calculator'){if(/^\/op\/[^/]+\/?$/.test(location.pathname))replaceHistoryToBrowsePath('/');renderDcStageDropdown();_dcEnsureAttackerSlots();renderDcAtkUnit();renderDcAtkChar();renderDcOptionParts();renderDcSupporters();renderDcDefStats();onDcParamChange()}else if(tab==='team_builder'){if(/^\/op\/[^/]+\/?$/.test(location.pathname))replaceHistoryToBrowsePath('/');initTeamBuilder();void tbRefreshSlottedUnitData().then(async()=>{await tbAutoFillEmptyOptionParts({skipRender:true});renderTeamBuilder();setTimeout(tbPrimePickerCaches,0)})}else if(tab==='ranking'){if(/^\/(?:u|c|s|es|op)\/[^/]+\/?$/.test(location.pathname))replaceHistoryToBrowsePath('/rk');onRankingTabShown()}else if(tab==='meta_synergy'){if(/^\/(?:u|c|s|es|op|rk)\/[^/]+\/?$/.test(location.pathname))replaceHistoryToBrowsePath('/msy');if(window.GgenMetaSynergy&&typeof GgenMetaSynergy.onTabShown==='function')GgenMetaSynergy.onTabShown()}else{if(tab!=='latest_release'&&/^\/new\/?$/.test(location.pathname))replaceHistoryToBrowsePath('/');if(tab!=='banner_timeline'&&/^\/banners\/?$/.test(location.pathname))replaceHistoryToBrowsePath('/');if(tab!=='master_league'&&/^\/ml\/?$/.test(location.pathname))replaceHistoryToBrowsePath('/');if(tab!=='investment_priority'&&/^\/ip\/?$/.test(location.pathname))replaceHistoryToBrowsePath('/');if(tab!=='stages'&&isStagesCategoryPath(location.pathname))replaceHistoryToBrowsePath('/');if(tab!=='modifications'&&/^\/op\/[^/]+\/?$/.test(location.pathname))replaceHistoryToBrowsePath('/');if(tab!=='ranking'&&/^\/rk\/?$/.test(location.pathname))replaceHistoryToBrowsePath('/');if(tab!=='meta_synergy'&&/^\/msy\/?$/.test(location.pathname))replaceHistoryToBrowsePath('/');applyListViewVisibility(tab);if(!(opts.fromPopstate&&_prevTab===tab))reloadBrowseTab(tab);if(tab==='stages')syncStageSourceToolbar()}armScrollTopFabBaseline();updateScrollTopFabVisibility();_cmpSyncForTabChange(tab);if(!opts.skipHistory&&!S._historyApplyingPopstate&&_prevTab!==tab){let _tabPath=MAIN_TAB_PATH_SHORT[tab]||'/';if(tab==='stages')_tabPath=stagesBrowsePathForSource(S.stages.source||'eternal');pushHistoryToBrowsePath(_tabPath)}requestAnimationFrame(()=>{scrollActiveNavTabIntoView();syncNavTabsOverflowHints()});}
function updateSearchHintVisibility(inputId){const inp=document.getElementById(inputId);if(!inp)return;const wrap=inp.closest('.filter-input-wrap');if(!wrap)return;const has=!!inp.value.trim();wrap.classList.toggle('has-value',has);wrap.classList.remove('show-hint');if(has)wrap.classList.add('hint-suppressed');else wrap.classList.remove('hint-suppressed')}
function clearFilterInput(inputId){const inp=document.getElementById(inputId);if(!inp)return;inp.value='';updateSearchHintVisibility(inputId);if(inp.classList.contains('filter-input--organic'))syncBrowseSearchWidth(inputId);const tabById={charFilter:'characters',unitFilter:'units',suppFilter:'supporters',stageFilter:'stages',modFilter:'modifications'};if(inputId==='rankCharFilter'||inputId==='rankUnitFilter')scheduleRankingListReload();else if(tabById[inputId])debounceLoad(tabById[inputId]);inp.focus()}
function initSearchHints(){document.querySelectorAll('.filter-input-wrap').forEach(wrap=>{const inp=wrap.querySelector('.filter-input');if(!inp)return;if(!wrap.querySelector('.filter-input-clear')){const btn=document.createElement('button');btn.type='button';btn.className='filter-input-clear';btn.setAttribute('aria-label','Clear search');btn.title='Clear';btn.textContent='\u00d7';btn.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();clearFilterInput(inp.id)});wrap.appendChild(btn)}function refresh(){updateSearchHintVisibility(inp.id);if(inp.classList.contains('filter-input--organic'))syncBrowseSearchWidth(inp.id)}inp.addEventListener('input',refresh);refresh()})}
function getActiveSearchInput(){if(S.currentTab==='ranking'){const id=S.ranking.mode==='characters'?'rankCharFilter':'rankUnitFilter';return document.getElementById(id)}const m={characters:'charFilter',units:'unitFilter',supporters:'suppFilter',stages:'stageFilter',modifications:'modFilter'};const id=m[S.currentTab];return id?document.getElementById(id):null}
function getTabSearchPlaceholderKey(){if(S.currentTab==='ranking')return S.ranking.mode==='characters'?'search_char':'search_unit';const m={characters:'search_char',units:'search_unit',supporters:'search_supporter',stages:'search_stage',modifications:'search_mod'};return m[S.currentTab]||'search_char'}
function getTabNameForSpotlight(){if(S.currentTab==='ranking')return t('tab_ranking');if(S.currentTab==='meta_synergy')return t('tab_meta_synergy');const m={characters:'tab_char',units:'tab_unit',supporters:'tab_supporter',stages:'tab_stage',modifications:'tab_mod'};return t(m[S.currentTab]||'tab_char')}
function onSearchSpotlightInput(){const real=getActiveSearchInput();const inp=document.getElementById('searchSpotlightInput');if(!real||!inp)return;real.value=inp.value;updateSearchHintVisibility(real.id);if(real.classList.contains('filter-input--organic'))syncBrowseSearchWidth(real.id);const tabById={charFilter:'characters',unitFilter:'units',suppFilter:'supporters',stageFilter:'stages',modFilter:'modifications'};const tab=tabById[real.id];if(real.id==='rankCharFilter'||real.id==='rankUnitFilter')scheduleRankingListReload();else if(tab)debounceLoad(tab);debounceSpotlightResults()}
function clearSpotlightResults(){const box=document.getElementById('searchSpotlightResults');if(box){box.innerHTML='';box.hidden=true}}
function debounceSpotlightResults(){clearTimeout(S._spotlightFt);S._spotlightFt=setTimeout(refreshSpotlightResults,220)}
async function refreshSpotlightResults(){const ov=document.getElementById('searchSpotlightOverlay');const box=document.getElementById('searchSpotlightResults');if(!ov||!ov.classList.contains('active')||!box)return;const qEl=getActiveSearchInput();const q=qEl?qEl.value.trim():'';if(!q){clearSpotlightResults();return}box.hidden=false;box.innerHTML='<div class="search-spotlight-results-loading">…</div>';const tab=S.currentTab;const pp=8;try{let url='';if(tab==='characters'){const s=S.characters;const roleQ=getRoleQuerySuffix('char');const rq=getRarityQuerySuffix('char');const stQ=getListStatQuery('char');const srcQ=getSourceQuerySuffix('char');const linQ=getLineageQuerySuffix('char');const linOp=getLineageOpSuffix('char');const serQ=getSeriesQuerySuffix('char');const serOp=getSeriesOpSuffix('char');const skillQ=getSkillOrAbilityQuerySuffix('char');const skOp=getCharSkillOpSuffix();const abilQ=getAbilityQuerySuffix('char');const traitOp=getCharTraitAbilityOpSuffix();const gsQ=getListViewMode('characters')==='grid'&&getListGridVariant('characters')===2?'&grid_skills=1':'';url=`/api/characters?lang=${S.lang}&page=1&per_page=${pp}&sort=${s.sort}&dir=${s.dir}&q=${encodeURIComponent(q)}${roleQ}${rq}${stQ}${srcQ}${linQ}${linOp}${serQ}${serOp}${skillQ}${skOp}${abilQ}${traitOp}${gsQ}`}else if(tab==='units'){const s=S.units;const qU=expandUnitSearchQuery(q);const roleQ=getRoleQuerySuffix('unit');const rq=getRarityQuerySuffix('unit');const stQ=getListStatQuery('unit');const srcQ=getSourceQuerySuffix('unit');const terrQ=getUnitTerrainQuerySuffix();const terrOp=getTerrainOpSuffix();const debQ=getUnitWeaponDebuffQuerySuffix();const debOp=getWeaponDebuffOpSuffix();const mechQ=getUnitMechanismQuerySuffix();const mechOp=getMechanismOpSuffix();const linQ=getLineageQuerySuffix('unit');const linOp=getLineageOpSuffix('unit');const serQ=getSeriesQuerySuffix('unit');const serOp=getSeriesOpSuffix('unit');const abQ=getSkillOrAbilityQuerySuffix('unit');const abOp=getUnitBrowseAbilityOpSuffix();const gsU=getListViewMode('units')==='grid'&&getListGridVariant('units')===2?'&grid_skills=1':'';url=`/api/units?lang=${S.lang}&page=1&per_page=${pp}&sort=${s.sort}&dir=${s.dir}&q=${encodeURIComponent(qU)}${roleQ}${rq}${stQ}${srcQ}${terrQ}${terrOp}${debQ}${debOp}${mechQ}${mechOp}${linQ}${linOp}${serQ}${serOp}${abQ}${abOp}${gsU}`}else if(tab==='supporters'){const s=S.supporters;const rq=getRarityQuerySuffix('supp');const linQ=getLineageQuerySuffix('supp');const linOp=getLineageOpSuffix('supp');url=`/api/supporters?lang=${S.lang}&page=1&per_page=${pp}&sort=${s.sort}&dir=${s.dir}&q=${encodeURIComponent(q)}${rq}${linQ}${linOp}`}else if(tab==='stages'){const s=S.stages;const df=s.difficultyFilter==='ALL'?'':s.difficultyFilter;const cat=(s.source||'eternal')==='score_attack'?'score_attack':'eternal';url=`/api/stages?lang=${S.lang}&page=1&per_page=${pp}&q=${encodeURIComponent(q)}&difficulty=${encodeURIComponent(df)}&sort=${s.sort}&dir=${s.dir}&category=${encodeURIComponent(cat)}`}else if(tab==='modifications'){const s=S.modifications;const rq=getRarityQuerySuffix('mod');const ef=encodeURIComponent(s.effectFilter||'ALL');const linQ=getLineageQuerySuffix('mod');const linOp=getLineageOpSuffix('mod');url=`/api/option_parts?lang=${S.lang}&page=1&per_page=${pp}&sort=${s.sort}&dir=${s.dir}&q=${encodeURIComponent(q)}${rq}&effect=${ef}${linQ}${linOp}`}else if(tab==='ranking'){url=S.ranking.mode==='characters'?buildRankingCharactersListUrl(1,pp):buildRankingUnitsListUrl(1,pp)}else{clearSpotlightResults();return}const r=await fetch(url);const d=await r.json();const rows=d.rows||[];if(!rows.length){box.innerHTML=`<div class="search-spotlight-results-empty">${esc(t('search_spotlight_empty'))}</div>`;return}let h='';if(tab==='characters'){rows.forEach(row=>{h+=`<button type="button" class="search-spotlight-row" data-detail-type="character" data-detail-id="${escAttr(String(row.id))}" onclick="openDetail('character','${escJs(row.id)}')">${renderListThumb(row,'char',44)}<div class="search-spotlight-row-text"><div class="search-spotlight-row-name">${esc(row.name)}</div><div class="search-spotlight-row-meta">${esc(row.rarity||'')}</div></div></button>`})}else if(tab==='units'){rows.forEach(row=>{h+=`<button type="button" class="search-spotlight-row" data-detail-type="unit" data-detail-id="${escAttr(String(row.id))}" onclick="openDetail('unit','${escJs(row.id)}')">${renderListThumb(row,'unit',44)}<div class="search-spotlight-row-text"><div class="search-spotlight-row-name">${esc(row.name)}</div><div class="search-spotlight-row-meta">${esc(row.rarity||'')}</div></div></button>`})}else if(tab==='supporters'){rows.forEach(row=>{h+=`<button type="button" class="search-spotlight-row" data-detail-type="supporter" data-detail-id="${escAttr(String(row.id))}" onclick="openDetail('supporter','${escJs(row.id)}')">${renderListThumb(row,'supp',44)}<div class="search-spotlight-row-text"><div class="search-spotlight-row-name">${esc(row.name)}</div><div class="search-spotlight-row-meta">${esc(row.rarity||'')}</div></div></button>`})}else if(tab==='stages'){rows.forEach(row=>{const locked=!!row.content_locked;const rowName=locked?esc(t('er_stage_redacted_row')):esc(row.name);const metaLn=locked?'—':row.stage_category==='score_attack'?`#${fmtN(row.stage_number)}`:`${esc(row.difficulty_name||'')} · #${fmtN(row.stage_number)}`;h+=`<button type="button" class="search-spotlight-row" data-detail-type="stage" data-detail-id="${escAttr(String(row.id))}" onclick="openDetail('stage','${escJs(row.id)}')"><div class="search-spotlight-stage-thumb">${renderStageBrowseThumb(row,{variant:'compact'})}</div><div class="search-spotlight-row-text"><div class="search-spotlight-row-name">${rowName}</div><div class="search-spotlight-row-meta">${metaLn}</div></div></button>`})}else if(tab==='modifications'){rows.forEach(row=>{const vt=escJs(String(row.variant_tag_id||''));h+=`<button type="button" class="search-spotlight-row" data-detail-type="option_part" data-detail-id="${escAttr(String(row.id))}" onclick="closeSearchSpotlight();openOptionPartDetail('${escJs(String(row.id))}','${vt}')">${renderListThumb(row,'mod',44,{pickerThumb:true})}<div class="search-spotlight-row-text"><div class="search-spotlight-row-name">${esc(row.name)}</div><div class="search-spotlight-row-meta">${esc(row.rarity||'')}</div></div></button>`})}else if(tab==='ranking'){if(S.ranking.mode==='characters'){rows.forEach(row=>{const ro=rankingDetailOptsFromContext('character');h+=`<button type="button" class="search-spotlight-row" data-detail-type="character" data-detail-id="${escAttr(String(row.id))}" onclick='openDetail("character","${escJs(row.id)}",${JSON.stringify(ro)})'>${renderListThumb(row,'char',44)}<div class="search-spotlight-row-text"><div class="search-spotlight-row-name">${esc(row.name)}</div><div class="search-spotlight-row-meta">${esc(row.rarity||'')}</div></div></button>`})}else{rows.forEach(row=>{const ro=rankingDetailOptsFromContext('unit');h+=`<button type="button" class="search-spotlight-row" data-detail-type="unit" data-detail-id="${escAttr(String(row.id))}" onclick='openDetail("unit","${escJs(row.id)}",${JSON.stringify(ro)})'>${renderListThumb(row,'unit',44)}<div class="search-spotlight-row-text"><div class="search-spotlight-row-name">${esc(row.name)}</div><div class="search-spotlight-row-meta">${esc(row.rarity||'')}</div></div></button>`})}}box.innerHTML=h}catch(e){box.innerHTML=`<div class="search-spotlight-results-empty">${esc(String(e))}</div>`}}
function closeSearchSpotlight(){const ov=document.getElementById('searchSpotlightOverlay');if(!ov||!ov.classList.contains('active'))return;clearSpotlightResults();const real=getActiveSearchInput();const inp=document.getElementById('searchSpotlightInput');if(real&&inp){real.value=inp.value;updateSearchHintVisibility(real.id);if(real.classList.contains('filter-input--organic'))syncBrowseSearchWidth(real.id)}ov.classList.remove('active');ov.setAttribute('aria-hidden','true');document.body.classList.remove('search-spotlight-open');releaseBackgroundScrollLock();updateScrollTopFabVisibility()}
function scrollActiveListToolbarIntoView(){try{const pan=document.getElementById('panel-'+S.currentTab);const el=pan&&pan.querySelector('.list-toolbar');if(el)el.scrollIntoView({behavior:'smooth',block:'start'})}catch(_){}}
function afterListLoadIfSpotlightOpen(){const ov=document.getElementById('searchSpotlightOverlay');if(!ov||!ov.classList.contains('active'))return;requestAnimationFrame(()=>scrollActiveListToolbarIntoView())}
function openSearchSpotlight(){if(S.currentTab==='latest_release'||S.currentTab==='banner_timeline'||S.currentTab==='master_league'||S.currentTab==='investment_priority'||S.currentTab==='calculator'||S.currentTab==='team_builder'||S.currentTab==='meta_synergy')return;const real=getActiveSearchInput();if(!real)return;const ov=document.getElementById('searchSpotlightOverlay');const inp=document.getElementById('searchSpotlightInput');const hint=document.getElementById('searchSpotlightHint');const tabLine=document.getElementById('searchSpotlightTabLine');const title=document.getElementById('searchSpotlightTitle');const foot=document.getElementById('searchSpotlightFoot');if(!ov||!inp)return;const spotWasActive=ov.classList.contains('active');inp.value=real.value;inp.placeholder=t(getTabSearchPlaceholderKey());if(title)title.textContent=t('search_spotlight_title');if(tabLine)tabLine.textContent=getTabNameForSpotlight();if(hint)hint.innerHTML=t('search_hint_html');if(foot)foot.textContent=t('search_spotlight_foot');const sc=document.getElementById('searchSpotlightClose');if(sc)sc.setAttribute('aria-label',t('search_spotlight_close'));ov.classList.add('active');ov.setAttribute('aria-hidden','false');document.body.classList.add('search-spotlight-open');if(!spotWasActive)applyBackgroundScrollLock();requestAnimationFrame(()=>{try{inp.focus({preventScroll:true});inp.select()}catch(_){inp.focus()}});debounceSpotlightResults()}
function recallSearchBar(){openSearchSpotlight()}
function bindSearchRecallObserver(){const fab=document.getElementById('searchRecallFab');if(S._searchRecallObs){S._searchRecallObs.disconnect();S._searchRecallObs=null}if(!fab)return;if(S.currentTab==='latest_release'||S.currentTab==='banner_timeline'||S.currentTab==='master_league'||S.currentTab==='investment_priority'||S.currentTab==='calculator'||S.currentTab==='team_builder'||S.currentTab==='meta_synergy'){fab.classList.remove('visible');return}const panel=document.getElementById('panel-'+S.currentTab);if(!panel){fab.classList.remove('visible');return}let anchor=null;if(S.currentTab==='ranking'){anchor=document.getElementById(S.ranking&&S.ranking.mode==='characters'?'rankCharFilter':'rankUnitFilter')}if(!anchor)anchor=panel.querySelector('.browse-toolbar-top-row');if(!anchor)anchor=panel.querySelector('.list-toolbar-left>.browse-toolbar-leading');if(!anchor)anchor=panel.querySelector('.list-toolbar');if(!anchor){fab.classList.remove('visible');return}function applyRecallFabFromIO(ents){const e=ents&&ents[0];fab.classList.toggle('visible',!!e&&!e.isIntersecting)}S._searchRecallObs=new IntersectionObserver(applyRecallFabFromIO,{root:null,threshold:0,rootMargin:'-72px 0px 0px 0px'});S._searchRecallObs.observe(anchor);requestAnimationFrame(()=>{try{applyRecallFabFromIO(S._searchRecallObs.takeRecords())}catch(_){}})}
function tryLoadLatestRelease(){loadLatestRelease()}
