function ensureESimulatorLoaded(){if(window.ESimulator)return Promise.resolve(window.ESimulator);const lazy=window.__GGEN_LAZY__;if(lazy&&typeof lazy.ensureEsim==='function')return lazy.ensureEsim();return Promise.resolve(null)}
function ensureUnitBestPilotsLoaded(){if(window.GgenUnitBestPilots)return Promise.resolve(window.GgenUnitBestPilots);const lazy=window.__GGEN_LAZY__;if(lazy&&typeof lazy.ensureUnitBestPilots==='function')return lazy.ensureUnitBestPilots();return Promise.resolve(null)}
function ensureMasterLeagueCss(){const lazy=window.__GGEN_LAZY__;if(lazy&&typeof lazy.ensureMasterLeagueCss==='function')return lazy.ensureMasterLeagueCss();return Promise.resolve()}
function ensureSpInvestmentLoaded(){if(window.GgenSpInvestment&&window.GgenSpInvestment._ready)return Promise.resolve(window.GgenSpInvestment);const lazy=window.__GGEN_LAZY__;if(lazy&&typeof lazy.ensureSpInvestment==='function')return lazy.ensureSpInvestment();return Promise.resolve(null)}
function ensureCraftUiCss(){const lazy=window.__GGEN_LAZY__;if(lazy&&typeof lazy.ensureCraftUiCss==='function')return lazy.ensureCraftUiCss();return Promise.resolve()}
function showLrLockModal(){const o=document.getElementById('lrLockOverlay');if(!o)return;o.style.display='flex';const err=document.getElementById('lrLockErr');if(err)err.textContent='';const inp=document.getElementById('lrLockInput');if(inp)inp.value='';fillLrLockTexts();setTimeout(()=>{if(inp)inp.focus()},80)}
function hideLrLockModal(){const o=document.getElementById('lrLockOverlay');if(o)o.style.display='none'}
async function submitLrUnlock(){const inp=document.getElementById('lrLockInput');const pw=inp?String(inp.value||''):'';const err=document.getElementById('lrLockErr');if(err)err.textContent='';try{const r=await fetch('/api/latest_release/unlock',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:pw})});const d=await r.json().catch(()=>({}));if(!r.ok){if(err)err.textContent=t('lr_pw_wrong');return}hideLrLockModal();S.lrCacheKey=null;S.lrCacheData=null;S.btCacheKey=null;S.btCacheData=null;_dcStagesCache=null;_dcStagesFetchLang=null;if(S.currentTab==='stages')loadStages(S.stages.page||1);if(S.currentTab==='calculator'){await renderDcStageDropdown();const _st=document.getElementById('dcStageSelect');if(_st&&_st.value)void onDcStageChange()}if(S.currentTab==='characters')loadCharacters(S.characters.page||1);else if(S.currentTab==='units')loadUnits(S.units.page||1);else if(S.currentTab==='supporters')loadSupporters(S.supporters.page||1);loadLatestRelease()}catch(e){if(err)err.textContent=String(e)}}
async function loadLatestRelease(loadAll){const root=document.getElementById('latestReleaseRoot');const load=document.getElementById('latestReleaseLoading');if(!root)return;hideLrLockModal();const fullQ=loadAll===true?'&full=1':'';const cacheKey=S.lang+'|'+(loadAll===true?'full':'recent');if(S.lrCacheKey===cacheKey&&S.lrCacheData){renderLatestRelease(S.lrCacheData);if(S.currentTab==='latest_release')markLatestReleaseSeenFromNotices();return}if(load)load.style.display='flex';try{const r=await fetch('/api/latest_release?lang='+encodeURIComponent(S.lang)+fullQ,{credentials:'same-origin'});if(r.status===401){const d=await r.json().catch(()=>({}));if(d.locked){showLrLockModal();root.innerHTML='';if(load)load.style.display='none';return}}if(!r.ok)throw new Error('HTTP '+r.status);const d=await r.json();S.lrCacheKey=cacheKey;S.lrCacheData=d;renderLatestRelease(d);if(S.currentTab==='latest_release')markLatestReleaseSeenFromNotices()}catch(e){S.lrCacheKey=null;S.lrCacheData=null;root.innerHTML='<div class="empty-state"><div class="empty-state-text">'+esc(String(e))+'</div></div>'}finally{if(load)load.style.display='none'}}
function loadMoreLatestRelease(){loadLatestRelease(true)}
function renderLatestRelease(d){const root=document.getElementById('latestReleaseRoot');const groups=d.groups||[];const hasMore=!!d.has_more;const scope=d.scope||'recent';function cardsForGroup(g){let s='';(g.items||[]).forEach(it=>{const typeLabel=it.type==='unit'?t('lr_type_unit'):(it.type==='character'?t('lr_type_char'):t('lr_type_supp'));const row={thum:it.thum,rarity:it.rarity||'N',role_icon:it.role_icon||'',acquisition_icon:it.acquisition_icon||'',special_icons:it.special_icons||[],is_ultimate:it.is_ultimate,is_limited_time:!!it.is_limited_time};const thumb=renderListThumb(row,it.type==='supporter'?'supp':it.type,72);s+='<div class="lr-card" data-detail-type="'+escAttr(String(it.type))+'" data-detail-id="'+escAttr(String(it.id))+'" onclick="openDetail(\''+it.type+'\',\''+escJs(it.id)+'\')"><div class="lr-card-type">'+esc(typeLabel)+'</div><div class="lr-card-thumb">'+thumb+'</div><div class="lr-card-name">'+esc(it.name)+'</div></div>'});return s}if(!groups.length){if(hasMore){root.innerHTML='<div class="lr-page-title">'+esc(t('latest_gasha_title'))+'</div><div class="empty-state"><div class="empty-state-text">'+esc(t('lr_empty_recent'))+'</div></div><div class="lr-load-more-wrap"><button type="button" class="lr-load-more-btn" onclick="loadMoreLatestRelease()">'+esc(t('lr_load_more'))+'</button></div>';return}root.innerHTML='<div class="empty-state"><div class="empty-state-icon">📭</div><div class="empty-state-text">'+t('lr_empty')+'</div></div>';return}let h='<div class="lr-page-title">'+esc(t('latest_gasha_title'))+'</div>';groups.forEach(g=>{const inner=g.locked?'<div class="lr-locked-banner"><span class="lr-locked-icon">🔒</span><span class="lr-locked-text">'+esc(t('lr_section_locked'))+'</span><button type="button" class="lr-unlock-inline-btn" onclick="showLrLockModal()">'+esc(t('lr_unlock_btn'))+'</button></div>':'<div class="lr-row">'+cardsForGroup(g)+'</div>';h+='<section class="lr-section"><h2 class="lr-date">'+esc(g.start_datetime_jst||'')+'</h2>'+inner+'</section>'});if(hasMore&&scope!=='full'){h+='<div class="lr-load-more-wrap"><button type="button" class="lr-load-more-btn" onclick="loadMoreLatestRelease()">'+esc(t('lr_load_more'))+'</button></div>'}root.innerHTML=h}
const BT_VOTE_UI={mission:'/static/images/UI/UI_Home_Menu_Icon_Mission.webp',cursor:'/static/images/UI/UI_Battle_MapUI_Supporter_TargetAreaCursor.webp',check:'/static/images/UI/UI_Common_BtnIcon_Check_Posi_S.webp',poolAll:'/static/images/UI/IMG_StageTop_MaterialStage.webp'};const UI_NOTICE_FLARE_PATH='/static/images/UI/UI_MapEventEffect_FlareCircleRed.webp';const BT_VOTE_DISABLED_GASHA_IDS=new Set(['2504100101','2604300101']);const BT_VOTE_BUSY={};
function uiNoticeFlareHtml(){const src=safeImgSrc(imgUrlWebp(imgUrlPreferCdn(UI_NOTICE_FLARE_PATH)));if(!src)return'';return'<span class="ui-notice-flare" aria-hidden="true"><img class="ui-notice-flare-img" src="'+escAttr(src)+'" alt="" decoding="async" onerror="this.parentElement.style.display=\'none\'"></span>'}
function btVoteEnabledBanners(){return(S.btCacheData&&S.btCacheData.banners||[]).filter(btVoteEnabledForBanner)}
function btVoteNoticeBannerIdsKey(){return btVoteEnabledBanners().map(b=>String(b.gasha_id||'')).filter(Boolean).sort().join(',')}
function btVoteNoticeClearDismissIfBannersChanged(){const ids=btVoteNoticeBannerIdsKey();if(!ids)return;let prev='';try{prev=localStorage.getItem('ggen_bt_vote_notice_banner_ids')||''}catch(_){}if(prev&&prev!==ids){try{localStorage.removeItem('ggen_bt_vote_notice_off')}catch(_){}}try{localStorage.setItem('ggen_bt_vote_notice_banner_ids',ids)}catch(_){}}
function btVoteNoticeDismissed(){try{return localStorage.getItem('ggen_bt_vote_notice_off')==='1'}catch(_){return false}}
function btMarkVoteNoticeDismissed(){try{localStorage.setItem('ggen_bt_vote_notice_off','1')}catch(_){}updateBtVoteNotices()}
function btUserHasUnvotedPool(){return btVoteEnabledBanners().some(b=>{const gid=String(b.gasha_id||'');return gid&&!btVoteMineList(gid).length})}
function btUserNeedsVoteNotice(){btVoteNoticeClearDismissIfBannersChanged();if(btVoteNoticeDismissed())return false;if(!S._btVoteStatusLoaded)return false;return btUserHasUnvotedPool()}
function updateBtVoteNotices(){if(window.GgenContentNotices){GgenContentNotices.setBtState({banners:S.btCacheData&&S.btCacheData.banners,mine:S.btVoteMine,totals:S.btVoteTotals,loaded:S._btVoteStatusLoaded});GgenContentNotices.updateBtVoteNotices();return}const show=btUserNeedsVoteNotice();const showBtn=show&&!S.btVoteMode;const tab=document.getElementById('navBannerTimelineTab');if(tab)tab.classList.toggle('has-ui-notice',show);document.querySelectorAll('.bt-vote-mode-btn').forEach(btn=>{const anchor=btn.closest('.ui-notice-anchor')||btn;anchor.classList.toggle('has-ui-notice',showBtn)});syncNavTabsOverflowHints()}
async function bootstrapBtVoteNotices(){try{const vr=await fetch('/api/banner_timeline/votes',{credentials:'same-origin',cache:'no-store'});if(vr&&vr.ok){const d=await vr.json();S.btVoteTotals=d.totals||{};S.btVoteMine=d.mine||{}}if(!S.btCacheData){const br=await fetch('/api/banner_timeline?lang='+encodeURIComponent(S.lang||'EN'),{credentials:'same-origin'});if(br&&br.ok)S.btCacheData=await br.json()}S._btVoteStatusLoaded=true}catch(_){}updateBtVoteNotices();if(window.GgenContentNotices){GgenContentNotices.setBtState({banners:S.btCacheData&&S.btCacheData.banners,mine:S.btVoteMine,totals:S.btVoteTotals,loaded:S._btVoteStatusLoaded});GgenContentNotices.updateBtVoteNotices()}}
function ensureNavBannerTimelineNoticeFlare(){const tab=document.getElementById('navBannerTimelineTab');if(!tab||tab.querySelector('.ui-notice-flare'))return;tab.insertAdjacentHTML('beforeend',uiNoticeFlareHtml())}
const GAME_NEWS_SEEN_KEY='ggen_game_news_seen';
function normalizeGameNewsLangKey(lang){const k=String(lang||'EN').trim().toUpperCase()||'EN';return k==='JA'?'JP':k}
function readGameNewsSeen(lang){const k=normalizeGameNewsLangKey(lang);try{const all=JSON.parse(localStorage.getItem(GAME_NEWS_SEEN_KEY)||'{}');const row=all[k]||all[k==='JP'?'JA':''];return row&&typeof row==='object'?{at:Number(row.at)||0,fp:String(row.fp||'')}:{at:0,fp:''}}catch(_){return{at:0,fp:''}}}
function writeGameNewsSeen(lang,patch){const k=normalizeGameNewsLangKey(lang);try{const all=JSON.parse(localStorage.getItem(GAME_NEWS_SEEN_KEY)||'{}');const prev=all[k]&&typeof all[k]==='object'?all[k]:{};all[k]={at:Number(patch&&patch.at!=null?patch.at:prev.at)||0,fp:String(patch&&patch.fp!=null?patch.fp:prev.fp||'')};localStorage.setItem(GAME_NEWS_SEEN_KEY,JSON.stringify(all))}catch(_){}}
function ensureNavGameNewsNoticeFlare(){const tab=document.getElementById('navGameNewsTab');if(!tab||tab.querySelector('.ui-notice-flare'))return;tab.insertAdjacentHTML('beforeend',uiNoticeFlareHtml())}
function navTabScrollerEl(){return document.getElementById('navTabs')||document.querySelector('.app-header .nav-tabs')}
function navTabsHiddenRightNoticeTabs(scroller){if(!scroller)return[];const sl=scroller.scrollLeft,vw=scroller.clientWidth,maxX=sl+vw-4;return Array.from(scroller.querySelectorAll('.nav-tab.has-ui-notice')).filter(tab=>tab.offsetLeft+Math.min(tab.offsetWidth,24)>maxX)}
function navTabsHiddenLeftNoticeTabs(scroller){if(!scroller)return[];const sl=scroller.scrollLeft,minX=sl+4;return Array.from(scroller.querySelectorAll('.nav-tab.has-ui-notice')).filter(tab=>tab.offsetLeft+Math.max(tab.offsetWidth-24,0)<minX)}
function ensureNavTabsEdgeFlares(){['navTabsEdgeFlareWrapLeft','navTabsEdgeFlareWrapRight'].forEach(id=>{const wrap=document.getElementById(id);if(!wrap||wrap.querySelector('.ui-notice-flare'))return;wrap.insertAdjacentHTML('beforeend',uiNoticeFlareHtml())})}
function syncNavTabsEdgeHintLabels(){const hintL=document.getElementById('navTabsEdgeHintLeft'),hintR=document.getElementById('navTabsEdgeHintRight');if(hintL){const lbl=t('nav_tabs_hidden_notice_hint_left');hintL.setAttribute('aria-label',lbl);hintL.title=lbl}if(hintR){const lbl=t('nav_tabs_hidden_notice_hint');hintR.setAttribute('aria-label',lbl);hintR.title=lbl}}
function scrollActiveNavTabIntoView(){
  const scroller=navTabScrollerEl();
  const tab=scroller&&scroller.querySelector('.nav-tab.active');
  if(!scroller||!tab)return;
  const pad=12;
  const sl=scroller.scrollLeft;
  const vw=scroller.clientWidth;
  const tabL=tab.offsetLeft;
  const tabR=tabL+tab.offsetWidth;
  if(tabL<sl+pad)scroller.scrollLeft=Math.max(0,tabL-pad);
  else if(tabR>sl+vw-pad)scroller.scrollLeft=Math.max(0,tabR-vw+pad);
}
function syncNavTabsOverflowHints(){const scroller=navTabScrollerEl(),shell=document.getElementById('navTabsShell'),hintL=document.getElementById('navTabsEdgeHintLeft'),hintR=document.getElementById('navTabsEdgeHintRight'),flareL=document.getElementById('navTabsEdgeFlareWrapLeft'),flareR=document.getElementById('navTabsEdgeFlareWrapRight');if(!scroller||!shell||!hintL||!hintR)return;const edgePad=8;const canScroll=scroller.scrollWidth>scroller.clientWidth+2;const hasLeft=canScroll&&scroller.scrollLeft>edgePad;const hasRight=canScroll&&scroller.scrollLeft+scroller.clientWidth<scroller.scrollWidth-edgePad;const hiddenLeft=navTabsHiddenLeftNoticeTabs(scroller);const hiddenRight=navTabsHiddenRightNoticeTabs(scroller);shell.classList.toggle('nav-tabs-shell--scroll-left',hasLeft);shell.classList.toggle('nav-tabs-shell--scroll-right',hasRight);shell.classList.toggle('nav-tabs-shell--hidden-notice-left',hiddenLeft.length>0);shell.classList.toggle('nav-tabs-shell--hidden-notice-right',hiddenRight.length>0);hintL.hidden=!hasLeft;hintR.hidden=!hasRight;if(flareL){flareL.classList.toggle('has-ui-notice',hiddenLeft.length>0);hintL.dataset.noticeTarget=hiddenLeft[0]?hiddenLeft[0].id:''}if(flareR){flareR.classList.toggle('has-ui-notice',hiddenRight.length>0);hintR.dataset.noticeTarget=hiddenRight[0]?hiddenRight[0].id:''}}
function scrollNavTabsToHiddenNotice(side){const scroller=navTabScrollerEl();if(!scroller)return;const hidden=side==='left'?navTabsHiddenLeftNoticeTabs(scroller):navTabsHiddenRightNoticeTabs(scroller);const target=hidden[0]||null;if(target)target.scrollIntoView({behavior:'smooth',inline:'nearest',block:'nearest'});else scroller.scrollBy({left:side==='left'?-Math.max(120,scroller.clientWidth*.65):Math.max(120,scroller.clientWidth*.65),behavior:'smooth'})}
function initNavTabsOverflowHints(){if(S._navTabsOverflowInit)return;S._navTabsOverflowInit=1;ensureNavTabsEdgeFlares();syncNavTabsEdgeHintLabels();const scroller=navTabScrollerEl(),hintL=document.getElementById('navTabsEdgeHintLeft'),hintR=document.getElementById('navTabsEdgeHintRight');if(!scroller||!hintL||!hintR)return;let raf=0;const sync=()=>{if(raf)return;raf=requestAnimationFrame(()=>{raf=0;syncNavTabsOverflowHints()})};scroller.addEventListener('scroll',sync,{passive:true});window.addEventListener('resize',sync,{passive:true});hintL.addEventListener('click',()=>scrollNavTabsToHiddenNotice('left'));hintR.addEventListener('click',()=>scrollNavTabsToHiddenNotice('right'));sync()}
function updateGameNewsNavNotice(show){const tab=document.getElementById('navGameNewsTab');if(!tab)return;tab.classList.toggle('has-ui-notice',!!show);syncNavTabsOverflowHints()}
async function bootstrapGameNewsNotices(){if(window.GgenContentNotices){GgenContentNotices.setLang(S.lang||'EN');return GgenContentNotices.bootstrapGameNews()}ensureNavGameNewsNoticeFlare();const lang=normalizeGameNewsLangKey(S.lang||'EN');const seen=readGameNewsSeen(lang);try{const r=await fetch('/api/game_news/status?lang='+encodeURIComponent(lang)+'&last_seen_at='+encodeURIComponent(String(seen.at||0))+'&last_seen_fp='+encodeURIComponent(seen.fp||''),{credentials:'same-origin',cache:'no-store'});if(!r.ok){updateGameNewsNavNotice(false);return}const d=await r.json();const hasNew=!!d.has_new;S._gameNewsStatus=d;updateGameNewsNavNotice(hasNew)}catch(_){updateGameNewsNavNotice(false)}}
