function initGameNewsNoticeRefresh(){if(S._gameNewsNoticeRefreshInit)return;S._gameNewsNoticeRefreshInit=1;window.addEventListener('pageshow',ev=>{if(ev.persisted)void bootstrapGameNewsNotices()});window.addEventListener('storage',ev=>{if(ev.key===GAME_NEWS_SEEN_KEY)void bootstrapGameNewsNotices()})}
function btVoteEnabledForBanner(b){if(!b)return false;if(b.vote_enabled===false)return false;const gid=String(b.gasha_id||'');return gid&&gid!=='0'&&!BT_VOTE_DISABLED_GASHA_IDS.has(gid)}
