function btSyncVoteModeChrome(){const voteOn=!!S.btVoteMode;const title=t(voteOn?'bt_vote_mode_on':'bt_vote_mode_off');document.querySelectorAll('.bt-vote-mode-btn').forEach(btn=>{btn.setAttribute('aria-pressed',voteOn?'true':'false');btn.title=title});document.querySelectorAll('.bt-vote-mode-caption').forEach(el=>{if(voteOn)el.removeAttribute('hidden');else el.setAttribute('hidden','')});const table=document.querySelector('#bannerTimelineRoot .bt-table');if(table)table.classList.toggle('bt-vote-mode-on',voteOn)}
function renderBannerTimelineTable(rows){const sorted=btSortBannerRows(rows||[]);const dir=S.btBannerSortDir||'desc';const arrow=dir==='desc'?'▼':'▲';const voteOn=!!S.btVoteMode;const voteBtnHead=btVoteHeaderToolsMarkup('btVoteModeCaption','btVoteModeBtn');const thead='<thead><tr><th class="bt-th-banner bt-th-sortable" scope="col" role="button" tabindex="0" onclick="toggleBtBannerTimelineSort()" onkeydown="if(event.key===\'Enter\'||event.key===\' \'){event.preventDefault();toggleBtBannerTimelineSort()}" title="'+escAttr(t('bt_sort_start_hint'))+'" aria-label="'+escAttr(t('bt_sort_start_hint'))+'">'+esc(t('bt_col_banner'))+' <span class="bt-sort-ind" aria-hidden="true">'+arrow+'</span></th><th class="bt-th-combo" scope="col"><div class="bt-th-combo-inner"><span class="bt-th-combo-label">'+esc(t('bt_col_featured'))+'</span>'+voteBtnHead+'</div></th></tr></thead>';const body='<tbody>'+btBuildBannerTbodyHtml(sorted)+'</tbody>';return'<div class="bt-table-wrap"><table class="data-table bt-table'+(voteOn?' bt-vote-mode-on':'')+'">'+thead+body+'</table></div>'}
function btSortBannerRows(rows){const dir=S.btBannerSortDir||'desc';const xs=(rows||[]).slice().sort((a,b)=>{const sa=a&&a.start_ms?+a.start_ms:0,sb=b&&b.start_ms?+b.start_ms:0;if(sa!==sb)return dir==='desc'?sb-sa:sa-sb;return String(a.gasha_id||'').localeCompare(String(b.gasha_id||''))});return xs}
