async function btToggleVote(gid,key){if(!btVoteEnabledForGid(gid))return;const busyKey=gid+':'+key;if(BT_VOTE_BUSY[busyKey])return;BT_VOTE_BUSY[busyKey]=1;const tr=btVoteRowEl(gid);const tile=tr?tr.querySelector('.bt-vote-tile[data-vote-key="'+String(key).replace(/\\/g,'\\\\').replace(/"/g,'\\"')+'"]'):null;if(tile)tile.classList.add('bt-vote-tile--busy');try{const r=await fetch('/api/banner_timeline/vote',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({gasha_id:gid,choice:key,action:'toggle'})});const d=await r.json().catch(()=>({}));if(!r.ok){const msg=d.error==='voter_ip_required'?t('bt_vote_err_ip'):(d.error||'HTTP '+r.status);throw new Error(msg)}if(!S.btVoteMine)S.btVoteMine={};if(Array.isArray(d.mine))S.btVoteMine[gid]=d.mine;if(d.totals){if(!S.btVoteTotals)S.btVoteTotals={};S.btVoteTotals[gid]=d.totals}S._btVoteStatusLoaded=true;updateBtVoteNotices();btVoteRefreshRowUi(gid)}catch(e){alert(t('bt_vote_err')+' '+String(e))}finally{delete BT_VOTE_BUSY[busyKey];if(tile)tile.classList.remove('bt-vote-tile--busy')}}
function btBindVoteDelegation(){const panel=document.getElementById('panel-banner_timeline');if(!panel||panel._btVoteBound)return;panel._btVoteBound=1;panel.addEventListener('change',ev=>{if(ev.target&&ev.target.classList&&ev.target.classList.contains('bt-gacha-pick-sortie'))_syncRegularGachaSortieCutin(ev.target)},{passive:true});panel.addEventListener('click',ev=>{const prevBtn=ev.target.closest('.bt-gacha-preview-btn');if(prevBtn){const gid=prevBtn.getAttribute('data-gasha-preview')||prevBtn.getAttribute('data-gacha-preview');const sid=prevBtn.getAttribute('data-gasha-setting')||prevBtn.getAttribute('data-gacha-setting');if(gid&&sid){ev.preventDefault();ev.stopPropagation();openGachaPullPreview(gid,sid);return}}const voteBtn=ev.target.closest('.bt-vote-mode-btn');if(voteBtn){ev.preventDefault();toggleBtVoteMode();return}const tile=ev.target.closest('.bt-vote-tile[data-vote-key]');if(!tile)return;if(S.btVoteMode){ev.preventDefault();ev.stopPropagation();const gid=tile.getAttribute('data-gasha-id');const key=tile.getAttribute('data-vote-key');if(!gid||!key||!btVoteEnabledForGid(gid))return;btToggleVote(gid,key);return}const typ=tile.getAttribute('data-detail-type');const id=tile.getAttribute('data-detail-id');if(typ&&id)openDetail(typ,id)},{passive:false})}
let _gachaPullState=null;
