function _loadLbVideoAndPlay(candidates,loadGen){const st=_gachaPullState;const v=_mediaVideoEl();if(!st||st.mode!=='single'||st._lbLoadGen!==loadGen||!v||!candidates.length)return;st._videoCandidates=candidates;st._videoCandIdx=0;st._videoOnReady=null;st._videoLoadQuiet=false;st._lbLastRepeat=0;_loadCurrentVideoCandidate();_consumeMediaVideoPlayGesture()}
