function syncUnitLbVideoUi(){const slot=document.getElementById('unitLbVideoBtnSlot');if(!slot)return;const d=S.currentDetailData;const showLb=unitLbVideoVisible(d);const showGacha=unitGachaPullVideoVisible(d);if(!showLb&&!showGacha){slot.innerHTML='';return}const ic=escAttr(imgUrl('/static/images/UI/UI_Common_ThumbIcon_Movie.webp'));let html='';if(showGacha)html+='<button type="button" class="unit-gacha-pull-video-btn" data-gacha-pull-movie-id="'+escAttr(String(d.gacha_pull_movie_id))+'" title="'+escAttr(t('video_gacha_pull_play'))+'" aria-label="'+escAttr(t('video_gacha_pull_aria'))+'"><img class="unit-gacha-pull-video-btn-icon" src="'+ic+'" alt="" loading="lazy" decoding="async" onerror="this.style.display=\'none\'"></button>';if(showLb)html+='<button type="button" class="unit-lb-video-btn" data-lb-movie-id="'+escAttr(String(d.limit_break_movie_id))+'" title="'+escAttr(t('video_lb_play'))+'" aria-label="'+escAttr(t('video_lb_aria'))+'"><img class="unit-lb-video-btn-icon" src="'+ic+'" alt="" loading="lazy" decoding="async" onerror="this.style.display=\'none\'"></button>';slot.innerHTML=html}
function bindUnitLbVideoDelegation(){if(document._unitLbVideoBound)return;document._unitLbVideoBound=1;document.addEventListener('click',ev=>{const gachaBtn=ev.target.closest('.unit-gacha-pull-video-btn[data-gacha-pull-movie-id]');if(gachaBtn){ev.preventDefault();playUnitGachaPullVideo(gachaBtn.getAttribute('data-gacha-pull-movie-id'));return}const btn=ev.target.closest('.unit-lb-video-btn[data-lb-movie-id]');if(!btn)return;ev.preventDefault();playUnitLbVideo(btn.getAttribute('data-lb-movie-id'))})}
async function loadBannerTimeline(){const root=document.getElementById('bannerTimelineRoot');const load=document.getElementById('bannerTimelineLoading');if(!root)return;if(S.currentTab==='banner_timeline')armScrollTopFabBaseline();const cacheKey=S.lang;if(S.btCacheKey===cacheKey&&S.btCacheData){await fetchBtVoteTotals();S._btVoteStatusLoaded=true;renderBannerTimeline(S.btCacheData);updateBtVoteNotices();return}if(load)load.style.display='flex';if(S._softListReload)S._softListReload=0;try{const[r1,r2]=await Promise.all([fetch('/api/banner_timeline?lang='+encodeURIComponent(S.lang),{credentials:'same-origin'}),fetch('/api/banner_timeline/votes',{credentials:'same-origin',cache:'no-store'})]);if(!r1.ok)throw new Error('HTTP '+r1.status);const data=await r1.json();if(r2.ok){const vd=await r2.json();S.btVoteTotals=vd.totals||{};S.btVoteMine=vd.mine||{}}S.btCacheKey=cacheKey;S.btCacheData=data;S._btVoteStatusLoaded=true;renderBannerTimeline(data);updateBtVoteNotices()}catch(e){S.btCacheKey=null;S.btCacheData=null;root.innerHTML='<div class="empty-state"><div class="empty-state-text">'+esc(String(e))+'</div></div>';requestAnimationFrame(()=>{armScrollTopFabBaseline();updateScrollTopFabVisibility()})}finally{if(load)load.style.display='none'}}
function mlTerrainLabel(name){const m={Space:'terrain_space',Atmospheric:'terrain_atmo',Ground:'terrain_ground',Land:'terrain_ground',Sea:'terrain_sea',Underwater:'terrain_underwater'};return t(m[name]||'terrain')}
function mlFmtTerrainPrimary(terrain){return t('ml_stage_label').replace('{terrain}',esc(mlTerrainLabel(terrain)||terrain))}
function mlStatusLabel(st){if(st==='active')return t('ml_status_active');if(st==='upcoming')return t('ml_status_upcoming');return t('ml_status_ended')}
function mlTagBrowseQuery(tag){if(!tag||!tag.name)return'';if(tag.tag_type==='series')return'series:'+tag.name;return tag.name}
function mlRenderBoostTag(tag){const tagObj={name:tag.name||'',type:tag.tag_type==='series'?'series':'',id:tag.tag_type==='series'?String(tag.target_id||''):''};return createTagHtml(tagObj,{defaultTarget:'unit'})}
function mlRenderBoostPortrait(p){if(!p||!p.portrait)return'';const side=p.side==='right'?'right':'left';const click=p.unit_id?` onclick="event.stopPropagation();openDetail('unit','${escJs(String(p.unit_id))}')" role="button" tabindex="0" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();openDetail('unit','${escJs(String(p.unit_id))}')}"`:'';return'<div class="ml-boost-portrait ml-boost-portrait--'+side+'"'+click+' title="'+escAttr(p.name||'')+'"><img class="ml-boost-portrait-img" src="'+imgUrl(p.portrait)+'" alt="'+escAttr(p.name||'')+'" loading="lazy" decoding="async" onerror="this.closest(\'.ml-boost-portrait\')?.remove()"></div>'}
function mlSeasonUsesSparkBanner(season){if(!season)return false;if(season.spark_banner===true)return true;if(season.status==='upcoming')return true;const sn=Number(season.season_number);return Number.isFinite(sn)&&sn>=0&&sn<=8}
function mlRenderBoostCard(season){const ML_BOOST_BANNER_BG='/static/images/UI/UI_Event_ML_BG_Result_FrontSpark.webp';const useSparkBanner=mlSeasonUsesSparkBanner(season);const showPortraits=useSparkBanner;const battleBg=!useSparkBanner&&season.motif_images&&season.motif_images.battle_background?imgUrl(season.motif_images.battle_background):'';let bgLayer='';let bgStyle='';let cardCls='ml-boost-card';if(useSparkBanner){bgLayer='<img class="ml-boost-spark-bg" src="'+escAttr(imgUrlPreferCdn(ML_BOOST_BANNER_BG))+'" alt="" loading="lazy" decoding="async" aria-hidden="true" onerror="gameImageUrlFallback(this)">';cardCls+=' ml-boost-card--spark-bg'}else if(battleBg){bgStyle='--ml-boost-bg:url(\''+escAttr(battleBg)+'\')'}const terrIcs=(season.terrain_icons||[]).map(ic=>'<img class="ml-boost-terrain-ic" src="'+imgUrl(ic.icon)+'" alt="'+escAttr(mlTerrainLabel(ic.label))+'" title="'+escAttr(mlTerrainLabel(ic.label))+'" loading="lazy" decoding="async" onerror="this.style.display=\'none\'">').join('');const portraits=showPortraits?(season.boost_portraits||[]).map(mlRenderBoostPortrait).join(''):'';if(showPortraits&&portraits)cardCls+=' ml-boost-card--portraits';const tagsHtml=(season.boost_tags||[]).map(mlRenderBoostTag).join('');const buffLine=season.buff_percent?'<div class="ml-boost-pct">'+esc(t('ml_buff_all_stats').replace('{n}',String(season.buff_percent)))+'</div>':'';const tagBlock=(tagsHtml||buffLine)?'<div class="ml-boost-tag-block"><div class="ml-boost-heading">'+esc(t('ml_boost_heading'))+'</div>'+(tagsHtml?'<div class="ml-boost-tags">'+tagsHtml+'</div>':'')+buffLine+'</div>':'';const portraitLayer=(showPortraits&&portraits)?'<div class="ml-boost-portraits">'+portraits+'</div>':'';const inner='<div class="ml-boost-inner"><div class="ml-boost-stage-row"><span class="ml-boost-stage-label">'+mlFmtTerrainPrimary(season.terrain_primary)+'</span><span class="ml-boost-terrain-icons">'+terrIcs+'</span></div>'+tagBlock+'</div>';const card='<div class="'+cardCls+'"'+(bgStyle?' style="'+bgStyle+'"':'')+'>'+bgLayer+portraitLayer+inner+'</div>';if(showPortraits&&portraits)return'<div class="ml-boost-banner">'+card+'</div>';return card}
function mlRenderScoreMilestones(milestones){return(milestones||[]).map(ms=>{const rewards=(ms.rewards||[]).map(mlRenderRewardChip).join('');return'<div class="ml-rank-row"><div class="ml-rank-head"><span class="ml-rank-badge">'+esc(fmtN(ms.target_score))+'</span></div><div class="ml-rank-rewards">'+(rewards||'<span class="ml-rank-none">'+esc(t('none'))+'</span>')+'</div></div>'}).join('')}
function mlProfileTitleRewardIcon(path){if(!path)return'<span class="ml-reward-chip-fallback ml-reward-chip-fallback--title" aria-hidden="true">PT</span>';return pictureRasterHtml(imgUrlPreferCdn(path),{cls:'ml-reward-chip-ic ml-reward-chip-ic--title',alt:'',loading:'lazy',decoding:'async',lazy:false,onerror:'profileTitleRewardIconOnError(this)'})}
function mlRenderRewardIcon(path,cls){if(!path)return'';const src=imgUrlPreferCdn(path);return pictureRasterHtml(src,{cls:cls||'ml-reward-chip-ic',alt:'',loading:'lazy',decoding:'async',lazy:false})}
function renderRewardItemIcon(path,style,cls){if(!path)return'';const extra=style?` style="${style}"`:'';return pictureRasterHtml(imgUrlPreferCdn(path),{cls:cls||'',alt:'',loading:'lazy',decoding:'async',lazy:false,extra})}
/** Plain reward icons that ship with large transparent margins (e.g. SP conversion materials). */
function rewardItemIconNeedsOpticalBoost(path){return/(?:^|\/)spm_\d/i.test(String(path||''))}
/** Style for plain item icons inside a fixed reward box — boost padded chips, fill box otherwise. */
function rewardPlainItemIconStyle(path,boxSz){const sz=Number(boxSz)>0?Number(boxSz):54;if(rewardItemIconNeedsOpticalBoost(path)){const base=Math.min(42,sz);return`width:${base}px;height:${base}px;object-fit:contain;display:block;transform:scale(1.32);transform-origin:center center;`}const base=Math.min(42,sz);return`width:${base}px;height:${base}px;object-fit:contain;display:block;`}
function mlRenderRewardChip(r){const meta=rewardRowDetailClickMeta(r);const{dataAttrs,clickAttrs}=rewardRowClickHandlerAttrs(meta);const clickable=!!meta;const rt=String(r.reward_type_index||'');const isProfileTitle=rt==='30';const spChipHtml=renderSpConversionChipThumb(r,40);const lbThumbHtml=renderLimitBreakMaterialThumb(r);const ptId=meta&&meta.id?meta.id:(r.detail_id||r.target_id||'');const ptIcon=r.icon||(ptId?('/static/images/Item/profile_title_'+ptId+'.webp'):'');const thumb=(r.thumb_type==='char'&&r.thumb)?renderListThumb({thum:r.thumb,rarity:r.rarity||'N',role_icon:r.role_icon||'',acquisition_icon:r.acquisition_icon||''},'char',40):(r.thumb_type==='unit'&&r.thumb)?renderListThumb({thum:r.thumb,rarity:r.rarity||'N',role_icon:r.role_icon||'',acquisition_icon:r.acquisition_icon||''},'unit',40):(r.thumb_type==='option_part'&&r.thumb)?renderListThumb({thum:r.thumb,rarity:r.rarity||'N'},'unit',40,{pickerThumb:true}):(spChipHtml?spChipHtml:(lbThumbHtml?lbThumbHtml:(isProfileTitle?mlProfileTitleRewardIcon(ptIcon):(r.icon?mlRenderRewardIcon(r.icon):'<span class="ml-reward-chip-fallback" aria-hidden="true">×</span>'))));const tag=clickable?'button type="button"':'div';return`<${tag} class="ml-reward-chip${clickable?' ml-reward-chip--clickable':''}"${dataAttrs}${clickAttrs}>${thumb}<span class="ml-reward-chip-name">${esc(r.name||'')}</span><span class="ml-reward-chip-count">×${fmtN(r.count||0)}</span></${clickable?'button':'div'}>`}
function mlRenderRankEmblem(icon,label){if(!icon)return'';return mlRenderRewardIcon(icon,'ml-rank-emblem')}
function mlRenderRankTiers(tiers){return(tiers||[]).map(rt=>{const rewards=(rt.rewards||[]).map(mlRenderRewardChip).join('');const emblem=mlRenderRankEmblem(rt.emblem_icon,rt.rank_label);return'<div class="ml-rank-row"><div class="ml-rank-head"><span class="ml-rank-badge">'+emblem+esc(rt.rank_label||'')+'</span><span class="ml-rank-pts"><span class="ml-rank-pts-k">'+esc(t('ml_col_score'))+'</span><span class="ml-rank-pts-v">'+esc(fmtN(rt.target_score))+'</span></span></div><div class="ml-rank-rewards">'+(rewards||'<span class="ml-rank-none">'+esc(t('none'))+'</span>')+'</div></div>'}).join('')}
function mlRenderMotifHero(season){const logo=season&&season.motif_images&&season.motif_images.logo;if(!logo)return'';return'<img class="ml-motif-logo" src="'+imgUrl(logo)+'" alt="" loading="lazy" decoding="async" onerror="this.style.display=\'none\'">'}
function mlUpdateHero(season){const host=document.getElementById('mlHeroHost');if(!host)return;host.innerHTML=mlRenderMotifHero(season)}
function mlRenderSeasonDetail(season,scoring){let h='<div class="ml-page">';h+=mlRenderBoostCard(season);h+='<div class="ml-section"><h3 class="ml-section-title">'+esc(t('ml_section_schedule'))+'</h3><div class="ml-meta-grid"><div class="ml-meta-item"><span class="ml-meta-k">'+esc(t('ml_chall_start'))+'</span><span class="ml-meta-v">'+esc(season.challenge_start_label||'-')+'</span></div><div class="ml-meta-item"><span class="ml-meta-k">'+esc(t('ml_chall_end'))+'</span><span class="ml-meta-v">'+esc(season.challenge_end_label||'-')+'</span></div></div></div>';if(season.rank_tiers&&season.rank_tiers.length)h+='<div class="ml-section"><h3 class="ml-section-title">'+esc(t('ml_section_ranks'))+'</h3><div class="ml-rank-list">'+mlRenderRankTiers(season.rank_tiers)+'</div></div>';if(season.score_milestones&&season.score_milestones.length)h+='<div class="ml-section"><h3 class="ml-section-title">'+esc(t('ml_section_score_milestones'))+'</h3><div class="ml-rank-list">'+mlRenderScoreMilestones(season.score_milestones)+'</div></div>';if(scoring){h+='<div class="ml-section ml-section--scoring"><h3 class="ml-section-title">'+esc(t('ml_section_scoring'))+'</h3><ul class="ml-scoring-list">';const ig=scoring.ingame||{};if(ig.damage_bonus_rate!=null)h+='<li>'+esc(t('ml_scoring_damage'))+': +'+esc(String(ig.damage_bonus_rate))+'%</li>';if(ig.kill_bonus_rate!=null)h+='<li>'+esc(t('ml_scoring_kill'))+': +'+esc(String(ig.kill_bonus_rate))+'%</li>';if(ig.victory_bonus_rate!=null)h+='<li>'+esc(t('ml_scoring_victory'))+': +'+esc(String(ig.victory_bonus_rate))+'%</li>';(scoring.turn_bonuses||[]).forEach(tb=>{h+='<li>'+esc(t('ml_scoring_turn').replace('{n}',String(tb.turn)))+': +'+esc(String(tb.bonus_rate))+'%</li>'});(scoring.rank_bonuses||[]).forEach(rb=>{if(rb.bonus_value>0)h+='<li>'+esc(t('ml_scoring_rank_bonus').replace('{rank}',rb.rank_label||''))+': +'+esc(fmtN(rb.bonus_value))+'</li>'});h+='</ul></div>'}h+='</div>';return h}
function mlSeasonsPastActive(seasons){return(seasons||[]).filter(s=>s&&s.status!=='upcoming')}
function mlSeasonsUpcoming(seasons){return(seasons||[]).filter(s=>s&&s.status==='upcoming')}
function mlDefaultSeasonEventId(data){const seasons=(data&&data.seasons)||[];const active=seasons.find(s=>s.status==='active');if(active)return String(active.event_id);const past=mlSeasonsPastActive(seasons);if(past.length)return String(past[past.length-1].event_id);const up=mlSeasonsUpcoming(seasons);if(up.length)return String(up[0].event_id);return seasons.length?String(seasons[seasons.length-1].event_id):''}
function closeMlSeasonPanels(){['mlSeasonPast','mlSeasonUpcoming'].forEach(prefix=>{const panel=document.getElementById(prefix+'Panel');const btn=document.getElementById(prefix+'Btn');if(panel)panel.hidden=true;if(btn)btn.setAttribute('aria-expanded','false')})}
function toggleMlSeasonPanel(which,ev){if(ev)ev.stopPropagation();const prefix=which==='upcoming'?'mlSeasonUpcoming':'mlSeasonPast';const panel=document.getElementById(prefix+'Panel');const btn=document.getElementById(prefix+'Btn');if(!panel||!btn||btn.disabled)return;const willOpen=panel.hidden;closeAllFilterPanels();if(willOpen){panel.hidden=false;btn.setAttribute('aria-expanded','true')}}
function mlPickSeason(eventId){closeMlSeasonPanels();if(!eventId||!S.mlCacheData)return;renderMasterLeague(S.mlCacheData,String(eventId))}
function mlBuildSeasonPanelHtml(rows,selectedId){if(!rows||!rows.length)return'<div class="ml-season-empty">'+esc(t('none'))+'</div>';return rows.map(s=>{const id=String(s.event_id);const sel=id===String(selectedId);return'<button type="button" role="menuitem" class="ml-season-opt'+(sel?' is-selected':'')+'" onclick="mlPickSeason(\''+escJs(id)+'\')">'+esc(s.title||('S'+s.season_number))+'</button>'}).join('')}
function mlPopulateSeasonSelect(data,selectedId){const seasons=data.seasons||[];const past=mlSeasonsPastActive(seasons);const upcoming=mlSeasonsUpcoming(seasons);const pick=String(selectedId||mlDefaultSeasonEventId(data)||data.active_event_id||'');S.mlSelectedEventId=pick;const inPast=!!(pick&&past.some(s=>String(s.event_id)===pick));const inUp=!!(pick&&upcoming.some(s=>String(s.event_id)===pick));const pastActive=inPast||(!inPast&&!inUp);const pastSeason=past.find(s=>String(s.event_id)===pick);const upSeason=upcoming.find(s=>String(s.event_id)===pick);const pastCat=document.getElementById('mlSeasonPastCatLbl');const upCat=document.getElementById('mlSeasonUpcomingCatLbl');if(pastCat)pastCat.textContent=t('ml_status_ended')+' / '+t('ml_status_active');if(upCat)upCat.textContent=t('ml_status_upcoming');const pastBtn=document.getElementById('mlSeasonPastBtn');const upBtn=document.getElementById('mlSeasonUpcomingBtn');const pastLabel=document.getElementById('mlSeasonPastLabel');const upLabel=document.getElementById('mlSeasonUpcomingLabel');const pastBody=document.getElementById('mlSeasonPastBody');const upBody=document.getElementById('mlSeasonUpcomingBody');const pastWrap=document.getElementById('mlSeasonPastWrap');const upWrap=document.getElementById('mlSeasonUpcomingWrap');if(pastLabel)pastLabel.textContent=pastSeason?(pastSeason.title||('S'+pastSeason.season_number)):(past.length?(past[past.length-1].title||('S'+past[past.length-1].season_number)):'—');if(upLabel)upLabel.textContent=upSeason?(upSeason.title||('S'+upSeason.season_number)):(upcoming.length?(upcoming[0].title||('S'+upcoming[0].season_number)):'—');if(pastBody)pastBody.innerHTML=mlBuildSeasonPanelHtml(past,pick);if(upBody)upBody.innerHTML=mlBuildSeasonPanelHtml(upcoming,pick);if(pastBtn){pastBtn.disabled=!past.length;pastBtn.classList.toggle('active',pastActive&&!!pastSeason);pastBtn.setAttribute('aria-label',t('ml_season_select_aria')+' — '+t('ml_status_ended')+' / '+t('ml_status_active'))}if(upBtn){upBtn.disabled=!upcoming.length;upBtn.classList.toggle('active',inUp&&!!upSeason);upBtn.setAttribute('aria-label',t('ml_season_select_aria')+' — '+t('ml_status_upcoming'))}if(pastWrap){pastWrap.classList.toggle('is-active',pastActive);pastWrap.classList.toggle('is-inactive',!pastActive)}if(upWrap){upWrap.classList.toggle('is-active',inUp);upWrap.classList.toggle('is-inactive',!inUp)}}
function mlUpdateStatusPill(season){const pill=document.getElementById('mlSeasonStatus');if(!pill||!season){if(pill)pill.hidden=true;return}pill.hidden=false;pill.textContent=mlStatusLabel(season.status);pill.className='ml-status-pill ml-status-pill--'+(season.status||'ended')}
function renderMasterLeague(data,eventId){const root=document.getElementById('masterLeagueRoot');if(!root)return;const seasons=data.seasons||[];if(!seasons.length){mlUpdateHero(null);root.innerHTML='<div class="ml-empty">'+esc(t('ml_empty'))+'</div>';return}const eid=String(eventId||S.mlSelectedEventId||mlDefaultSeasonEventId(data)||data.active_event_id||'');mlPopulateSeasonSelect(data,eid);const season=seasons.find(s=>String(s.event_id)===eid)||seasons[seasons.length-1];mlUpdateStatusPill(season);mlUpdateHero(season);root.innerHTML=mlRenderSeasonDetail(season,data.scoring||{});wireRewardDetailClicks(root);requestAnimationFrame(()=>{armScrollTopFabBaseline();updateScrollTopFabVisibility()})}
function mlOpenUnitsForTag(q){if(!q)return;switchTab('units');const inp=document.getElementById('unitFilter');if(inp){inp.value=q;syncBrowseSearchWidth('unitFilter')}loadUnits(1);try{window.scrollTo({top:0,behavior:'smooth'})}catch(_){window.scrollTo(0,0)}}
async function loadMasterLeague(){await ensureMasterLeagueCss();const root=document.getElementById('masterLeagueRoot');const load=document.getElementById('masterLeagueLoading');if(!root)return;if(S.currentTab==='master_league')armScrollTopFabBaseline();const cacheKey=S.lang+'_v25';if(S.mlCacheKey===cacheKey&&S.mlCacheData){renderMasterLeague(S.mlCacheData);if(S.currentTab==='master_league')markMasterLeaguePageVisited();return}if(load)load.style.display='flex';try{const r=await fetch('/api/master_league?lang='+encodeURIComponent(S.lang),{credentials:'same-origin'});if(!r.ok)throw new Error('HTTP '+r.status);const data=await r.json();S.mlCacheKey=cacheKey;S.mlCacheData=data;renderMasterLeague(data);if(S.currentTab==='master_league')markMasterLeaguePageVisited()}catch(e){S.mlCacheKey=null;S.mlCacheData=null;root.innerHTML='<div class="ml-empty">'+esc(String(e))+'</div>'}finally{if(load)load.style.display='none'}}
async function loadInvestmentPriority(){await ensureSpInvestmentLoaded();if(S.currentTab==='investment_priority')armScrollTopFabBaseline();if(window.GgenSpInvestment&&typeof GgenSpInvestment.onTabShown==='function'){await GgenSpInvestment.onTabShown();GgenSpInvestment._ready=true}}
function pageScrollY(){return Math.max(window.scrollY||0,document.documentElement.scrollTop||0,document.body.scrollTop||0)}
function getScrollTopFabEl(){return document.getElementById('bannerTimelineScrollTopFab')}
function scrollToTop(){try{window.scrollTo({top:0,behavior:'smooth'})}catch(_){window.scrollTo(0,0)}}
function scrollBannerTimelineToTop(){scrollToTop()}
function scrollTopFabIsBlocked(){
if(document.body.classList.contains('detail-modal-open'))return true;
if(document.documentElement.classList.contains('page-scroll-lock'))return true;
const spot=document.getElementById('searchSpotlightOverlay');
if(spot&&spot.classList.contains('active'))return true;
return false;
}
function armScrollTopFabBaseline(){
const st=pageScrollY();
S._scrollTopFabLastSt=st;
S._scrollTopFabShown=false;
S._scrollTopFabDownAccum=0;
const b=getScrollTopFabEl();
if(b)b.hidden=true;
}
function armBannerTimelineScrollFabBaseline(){armScrollTopFabBaseline()}
function updateScrollTopFabVisibility(){
const b=getScrollTopFabEl();
if(!b)return;
if(scrollTopFabIsBlocked()){b.hidden=true;return}
const st=pageScrollY();
const topTol=56,jitUp=14,downNeed=36;
if(typeof S._scrollTopFabLastSt!=='number'){S._scrollTopFabLastSt=st;b.hidden=true;return}
const d=st-S._scrollTopFabLastSt;
S._scrollTopFabLastSt=st;
if(st<=topTol){S._scrollTopFabShown=false;S._scrollTopFabDownAccum=0}else{
if(d>0)S._scrollTopFabDownAccum=(S._scrollTopFabDownAccum||0)+d;
if(d<-jitUp){S._scrollTopFabShown=false;S._scrollTopFabDownAccum=0}else if((S._scrollTopFabDownAccum||0)>=downNeed)S._scrollTopFabShown=true;
}
b.hidden=S._scrollTopFabShown!==true;
}
function updateBannerTimelineScrollFabVisibility(){updateScrollTopFabVisibility()}
function initScrollTopFab(){
if(S._scrollTopFabInit)return;
S._scrollTopFabInit=1;
armScrollTopFabBaseline();
window.addEventListener('scroll',updateScrollTopFabVisibility,{passive:true});
window.addEventListener('resize',updateScrollTopFabVisibility,{passive:true});
}
function initBannerTimelineExtras(){initScrollTopFab();if(S._bannerTimelineExtras)return;S._bannerTimelineExtras=1;if(typeof S.btVoteMode!=='boolean')S.btVoteMode=false;if(!S.btVoteMine)S.btVoteMine={};btBindVoteDelegation();initNavTabsOverflowHints();/* notices: scheduleDeferredContentBootstraps after browse paint */}
function goHome(){closeAlipayhkModal();closeWhatsNew();closeModal();switchTab('characters')}
function setupKeys(){document.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){if(e.altKey||e.ctrlKey||e.metaKey||e.shiftKey)return;const m=document.getElementById('detailModal');if(!m||!m.classList.contains('active')||!detailBrowseNavEligible())return;const ae=document.activeElement;if(ae&&(ae.tagName==='INPUT'||ae.tagName==='TEXTAREA'||ae.tagName==='SELECT'||ae.isContentEditable))return;e.preventDefault();void detailBrowseNavStep(e.key==='ArrowLeft'?-1:1);return}if(e.key==='Escape'){const sdp=document.getElementById('dcStageDdPanel');if(sdp&&!sdp.hidden){e.preventDefault();_dcCloseDcStageDd();return}if(document.getElementById('searchSpotlightOverlay')&&document.getElementById('searchSpotlightOverlay').classList.contains('active')){e.preventDefault();closeSearchSpotlight();return}const tbPickOv=document.getElementById('tbPickerOverlay');if(tbPickOv&&tbPickOv.classList.contains('active')){e.preventDefault();closeTbPicker();return}const aho=document.getElementById('alipayhkOverlay');if(aho&&aho.classList.contains('active')){e.preventDefault();closeAlipayhkModal();return}const wno=document.getElementById('whatsNewOverlay');if(wno&&wno.classList.contains('active')){e.preventDefault();closeWhatsNew();return}const sfo=document.getElementById('siteFeedbackOverlay');if(sfo&&sfo.classList.contains('active')){e.preventDefault();closeSupportFeedback();return}const tbf=document.getElementById('tbFormationOverlay');if(tbf&&tbf.classList.contains('active')){e.preventDefault();closeTbFormationModal();return}const tbr=document.getElementById('tbRearrangeOverlay');if(tbr&&tbr.classList.contains('active')){e.preventDefault();tbRearrangeCancel();return}if(document.querySelector('.list-toolbar [id$="FilterPanel"]:not([hidden])')){e.preventDefault();closeAllFilterPanels();return}const _mvo=_mediaVideoOverlay();if(_mvo&&_mvo.classList.contains('active')){e.preventDefault();closeMediaVideoOverlay();return}if(document.getElementById('skillModal').classList.contains('active'))closeSkillModalForce();else if(document.getElementById('tagModal').classList.contains('active'))closeTagModalForce();else closeModal()}})}
function openWhatsNew(){const ov=document.getElementById('whatsNewOverlay'),body=document.getElementById('whatsNewBody'),title=document.getElementById('whatsNewTitleEl');if(!ov||!body)return;document.getElementById('langDropdown').classList.remove('active');if(title)title.innerHTML='<img class="whats-new-ic" src="'+imgUrl('/static/images/UI/UI_Common_BtnIcon_News.webp')+'" alt=""> <span>'+esc(t('whats_new_title'))+'</span>';body.innerHTML='<div class="loading-overlay" style="min-height:200px"><div class="spinner"></div></div>';ov.classList.add('active');ov.setAttribute('aria-hidden','false');applyBackgroundScrollLock();const u='/api/whats_new?lang='+encodeURIComponent(S.lang||'EN')+'&t='+Date.now();fetch(u,{cache:'no-store',credentials:'same-origin'}).then(r=>r.json()).then(d=>{const tabs=(d&&d.tabs)||[];if(tabs.length){body.innerHTML=renderWhatsNewTabsHTML(tabs);if(window.GgenContentNotices)void GgenContentNotices.markWhatsNewSeen();return}const entries=(d&&d.entries)||[];if(!entries.length){body.innerHTML='<p style="color:var(--text-muted);margin:0">'+esc(t('whats_new_empty'))+'</p>';if(window.GgenContentNotices)void GgenContentNotices.markWhatsNewSeen();return}body.innerHTML=entries.map(renderWhatsNewBlock).join('');if(window.GgenContentNotices)void GgenContentNotices.markWhatsNewSeen()}).catch(err=>{body.innerHTML='<p style="color:var(--text-muted);margin:0">'+esc(String(err))+'</p>'})}
function whatsNewTabLabel(tab){if(!tab||typeof tab!=='object')return'';const k=tab.kind;function endLabel(){const x=tab.label!=null&&String(tab.label).trim()!==''?String(tab.label):(tab.date!=null&&String(tab.date).trim()!==''?String(tab.date):'');return x}if(k==='pending'){const d=endLabel();return d||t('whats_new_tab_pending')}if(k==='manual'){const d=tab.date!=null&&String(tab.date).trim()!==''?String(tab.date):'';return d?d+' · '+t('whats_new_tab_manual'):t('whats_new_tab_manual')}if(k==='history'){const d=endLabel();return d||'—'}return String(tab.id||'')}
function whatsNewTabIsEmpty(tab){const ch=tab.changes||[],ad=tab.added||[];return !ch.length&&!ad.length}
function renderWhatsNewTabPanelInner(tab){if(whatsNewTabIsEmpty(tab))return'<p class="whats-new-tab-empty">'+esc(t('whats_new_tab_empty'))+'</p>';return renderWhatsNewBlock({date:tab.date,changes:tab.changes||[],added:tab.added||[]})}
function sortWhatsNewTabsLatestFirst(tabs){return tabs.slice().sort(function(a,b){const da=String((a&&a.date)||(a&&a.label)||'').trim();const db=String((b&&b.date)||(b&&b.label)||'').trim();const cmp=db.localeCompare(da);if(cmp!==0)return cmp;return String((b&&b.id)||'').localeCompare(String((a&&a.id)||''))})}
function renderWhatsNewTabsHTML(tabs){const sorted=sortWhatsNewTabsLatestFirst(tabs);const activeIdx=0;let h='<div class="whats-new-date-wrap">';h+='<label class="whats-new-date-label" for="whatsNewDateSelect">'+esc(t('whats_new_select_period'))+'</label>';h+='<select id="whatsNewDateSelect" class="whats-new-date-select" aria-label="'+esc(t('whats_new_select_period'))+'" onchange="whatsNewSelectTab(parseInt(this.value,10))">';sorted.forEach(function(tab,i){const lab=whatsNewTabLabel(tab);h+='<option value="'+i+'"'+(i===activeIdx?' selected':'')+'>'+esc(lab)+'</option>'});h+='</select></div>';sorted.forEach(function(tab,i){const sel=i===activeIdx?' active':'';h+='<div class="whats-new-tab-panel'+sel+'" role="tabpanel" id="whatsNewTabPanel'+i+'">'+renderWhatsNewTabPanelInner(tab)+'</div>'});return h}
function whatsNewSelectTab(idx){const sel=document.getElementById('whatsNewDateSelect');if(sel)sel.value=String(idx);document.querySelectorAll('#whatsNewBody .whats-new-tab-panel').forEach(function(p,i){p.classList.toggle('active',i===idx)})}

function renderWhatsNewSlotRows(rows,isAbility){
  if(!rows||!rows.length)return '';
  function cellText(r,which){
    const ft=r.from_text,tt=r.to_text;
    if(which==='from'){
      if(ft!=null&&ft!=='')return String(ft);
      const a=r.from!=null?String(r.from):'';const d=isAbility&&r.from_detail?String(r.from_detail):'';
      return d?a+'\n\n'+d:a;
    }
    if(tt!=null&&tt!=='')return String(tt);
    const b=r.to!=null?String(r.to):'';const d=isAbility&&r.to_detail?String(r.to_detail):'';
    return d?b+'\n\n'+d:b;
  }
  let h='<div class="wn-diff-grid">';
  h+='<div class="wn-diff-header-row"><div class="wn-diff-h-slot">'+esc(t('whats_new_slot'))+'</div><div class="wn-diff-h-before">'+esc(t('whats_new_before'))+'</div><div class="wn-diff-h-after">'+esc(t('whats_new_after'))+'</div></div>';
  rows.forEach(function(r){
    h+='<div class="wn-diff-body-row"><div class="wn-diff-slot">'+esc(String(r.slot))+'</div>';
    h+='<div class="wn-diff-pre-col wn-diff-pre--before"><div class="wn-diff-pre">'+esc(cellText(r,'from'))+'</div></div>';
    h+='<div class="wn-diff-pre-col wn-diff-pre--after"><div class="wn-diff-pre">'+esc(cellText(r,'to'))+'</div></div></div>';
  });
  h+='</div>';
  return h;
}
function whatsNewShortcut(linkType,linkId){
  closeWhatsNew();
  const id=String(linkId||'').trim();
  if(!id)return;
  const lt=String(linkType||'').trim();
  if(lt==='unit'||lt==='character'){
    openDetail(lt,id);
    return;
  }
  if(lt==='supporter'){
    openDetail('supporter',id);
    return;
  }
  if(lt==='modification'){
    switchTab('modifications');
    openDetail('option_part',id);
    try{window.scrollTo({top:0,behavior:'smooth'})}catch(_){window.scrollTo(0,0)}
  }
}
function wnCardAttrs(c){
  if(!c||typeof c!=='object')return' class="wn-change-card"';
  const lt=c.link_type,lid=c.link_id;
  if(lt&&lid!=null&&String(lid).trim()!==''){
    return ' class="wn-change-card wn-change-card--link" onclick="whatsNewShortcut(\''+escJs(lt)+'\',\''+escJs(String(lid))+'\')"';
  }
  return' class="wn-change-card"';
}
function renderWhatsNewChangeItem(c){
  if(!c||typeof c!=='object')return'<article class="wn-change-card"><p class="wn-change-head">'+esc(String(c))+'</p></article>';
  if((c.kind==='unit_abilities'||c.kind==='char_abilities')&&Array.isArray(c.rows)){
    const kb=c.kind==='unit_abilities'?t('whats_new_kind_unit_abilities'):t('whats_new_kind_char_abilities');
    return'<article'+wnCardAttrs(c)+'><div class="wn-change-head"><span class="wn-kbadge">'+esc(kb)+'</span> '+esc(c.title||'')+'</div>'+renderWhatsNewSlotRows(c.rows,true)+'</article>';
  }
  if(c.kind==='unit_weapons'&&Array.isArray(c.rows)){
    return'<article'+wnCardAttrs(c)+'><div class="wn-change-head"><span class="wn-kbadge">'+esc(t('whats_new_kind_unit_weapons'))+'</span> '+esc(c.title||'')+'</div>'+renderWhatsNewSlotRows(c.rows,false)+'</article>';
  }
  if(c.from!==undefined||c.to!==undefined){
    const fr=esc(String(c.from!=null?c.from:'')),t2=esc(String(c.to!=null?c.to:''));
    return'<article class="wn-change-card"><div class="wn-change-head">'+esc(t('whats_new_manual_note'))+'</div><div class="wn-fromto-block"><span class="whats-new-fromto"><span class="w-from">'+fr+'</span> <span class="w-arrow">→</span> <span class="w-to">'+t2+'</span></span></div></article>';
  }
  return'<article class="wn-change-card"><p class="wn-change-head">'+esc(String(c))+'</p></article>';
}
function renderWhatsNewAddedItem(x){
  if(typeof x==='string')return'<li class="wn-added-li wn-added-li--plain">'+esc(x)+'</li>';
  const o=x||{};
  if(o.link_type&&o.link_id!=null&&String(o.link_id).trim()!==''&&o.kind){
    let lbl='';
    if(o.kind==='new_unit')lbl=t('whats_new_label_new_unit');
    else if(o.kind==='new_character')lbl=t('whats_new_label_new_char');
    else if(o.kind==='new_option_part')lbl=t('whats_new_label_new_mod');
    else if(o.kind==='new_supporter')lbl=t('whats_new_label_new_supporter');
    const lblHtml=lbl?esc(lbl)+' ':'';
    return'<li class="wn-added-li"><button type="button" class="wn-added-btn" onclick="whatsNewShortcut(\''+escJs(o.link_type)+'\',\''+escJs(String(o.link_id))+'\')">'+lblHtml+'<span class="wn-added-name">'+esc(o.name||'')+'</span></button></li>';
  }
  return'<li class="wn-added-li wn-added-li--plain">'+esc(typeof x==='object'?JSON.stringify(x):String(x))+'</li>';
}
function renderWhatsNewBlock(ent){
  const date=ent.date!=null?String(ent.date):'';
  let ch=ent.changes;if(!Array.isArray(ch))ch=[];
  const changesHtml=ch.length?'<ol class="whats-new-change-ol">'+ch.map(function(x){return'<li>'+renderWhatsNewChangeItem(x)+'</li>';}).join('')+'</ol>':'';
  let ad=ent.added;if(!Array.isArray(ad))ad=[];
  const addedHtml=ad.length?'<ul class="wn-added-list">'+ad.map(renderWhatsNewAddedItem).join('')+'</ul>':'';
  return'<section class="whats-new-block">'+(date?'<div class="wn-date-row"><span class="wn-label">'+esc(t('whats_new_date'))+'</span> '+esc(date)+'</div>':'')+(changesHtml?'<div style="margin-top:14px"><span class="wn-label">'+esc(t('whats_new_changes'))+'</span>'+changesHtml+'</div>':'')+(addedHtml?'<div style="margin-top:18px"><span class="wn-label">'+esc(t('whats_new_added'))+'</span>'+addedHtml+'</div>':'')+'</section>';
}
function openAlipayhkModal(){const ov=document.getElementById('alipayhkOverlay');if(!ov)return;document.getElementById('langDropdown').classList.remove('active');const title=document.getElementById('alipayhkModalTitle');if(title)title.textContent=t('support_alipayhk_modal_title');const hint=document.getElementById('alipayhkModalHint');if(hint)hint.textContent=t('support_alipayhk_modal_hint');const qr=document.getElementById('alipayhkModalQr');if(qr)qr.setAttribute('alt',t('support_alipayhk_modal_hint'));const closeBtn=document.getElementById('alipayhkModalCloseBtn');if(closeBtn)closeBtn.setAttribute('aria-label',t('whats_new_close'));const hb=document.getElementById('alipayhkHeaderBtn');if(hb){hb.title=t('support_alipayhk_btn');hb.setAttribute('aria-label',t('support_alipayhk_btn'))}ov.classList.add('active');ov.setAttribute('aria-hidden','false');applyBackgroundScrollLock()}
