const numeric={ATK:1,DEF:1,MOB:1,HP:1,EN:1,MOV:1,rarity_sort:1,role_sort:1,Ranged:1,Melee:1,Awaken:1,Defense:1,Reaction:1,stage_number:1,recommended_cp:1};
