function instantBrowseApplyNow(tab,page,q){
const st=_instantBrowse[tab];
if(!st||!st.rows)return false;
if(instantBrowseQueryNeedsServer(q,tab))return false;
const chipSig=instantBrowseChipSig(tab);
const qn=String(q||'').trim();
/* Prefix-narrow only when the *expanded* query still extends the previous expanded
   query. Raw prefix (go→god, fat→fatb) is wrong: shortcuts rewrite the match text, so
   intermediate keys drop the target before the alias fires. */
const qnExp=(tab==='units'||tab==='rankUnits'||tab==='characters'||tab==='rankCharacters')?expandUnitSearchQuery(qn):qn;
const lastExp=(tab==='units'||tab==='rankUnits'||tab==='characters'||tab==='rankCharacters')?expandUnitSearchQuery(st.lastQ||''):(st.lastQ||'');
let pool;
if(st.lastChipSig===chipSig&&st.lastQ!=null&&qnExp.indexOf(lastExp)===0&&Array.isArray(st.lastFiltered)){
pool=qn===st.lastQ?st.lastFiltered:st.lastFiltered.filter(r=>instantBrowseRowMatch(r,qn,tab));
}else{
pool=instantBrowseChipPool(tab);
if(qn)pool=pool.filter(r=>instantBrowseRowMatch(r,qn,tab));
}
st.lastChipSig=chipSig;
st.lastQ=qn;
st.lastFiltered=pool;
if(!pool.length&&isLikelyIdQuery(qn)&&(tab==='units'||tab==='characters'||tab==='rankUnits'||tab==='rankCharacters'))return false;
const sorted=instantBrowseSort(pool,tab);
const pp=instantBrowsePerPage(tab);
const total=sorted.length;
const tp=Math.max(1,Math.ceil(total/Math.max(1,pp)));
const pg=Math.min(Math.max(1,Number(page)||1),tp);
const rows=sorted.slice((pg-1)*pp,pg*pp);
const payload={rows,total,page:pg,per_page:pp,total_pages:tp,_sorted:sorted};
instantBrowsePaint(tab,payload,qn,pg);
markBrowseFirstPaintForNotices();afterListLoadIfSpotlightOpen();return true;
}
function instantBrowseApply(tab,page,q){
const st=_instantBrowse[tab];
if(!st||!st.rows)return false;
if(instantBrowseQueryNeedsServer(q,tab))return false;
st._pending={page,q};
if(st._raf)return true;
st._raf=requestAnimationFrame(()=>{
st._raf=0;
const p=st._pending;
st._pending=null;
if(p)instantBrowseApplyNow(tab,p.page,p.q);
});
return true;
}
function scheduleInstantBrowseWarm(tab){
if(!_instantBrowse[tab])return;
const url=instantBrowseCatalogUrl(tab);
const st=_instantBrowse[tab];
if(!st||!url)return;
if(st.key===url&&st.rows&&st.rows.length)return;
if(st.inflight===url)return;
const gen=++st.gen;
st.inflight=url;
const go=async()=>{
try{
const r=await fetchJsonWithWarmupRetry(url,{timeoutMs:60000,priority:'low'});
if(gen!==st.gen)return;
if(!r.ok||!r.data||!Array.isArray(r.data.rows)||!r.data.rows.length)return;
st.key=url;
st.rows=instantBrowseIngest(r.data.rows,tab);
st.lastQ=null;st.lastFiltered=null;st.lastChipSig=null;
if(r.data.challenge_series_options||r.data.effect_filter_icons){
st.meta=Object.assign({},st.meta||{});
if(r.data.challenge_series_options)st.meta.challenge_series_options=r.data.challenge_series_options;
if(r.data.effect_filter_icons)st.meta.effect_filter_icons=r.data.effect_filter_icons;
}
browseListJsonCacheSet(url,r.data);
if(instantBrowseIsCurrentView(tab))instantBrowseApply(tab,instantBrowseCurrentPage(tab),instantBrowseQ(tab));
}catch(_){}
finally{if(gen===st.gen)st.inflight=null}
};
const kick=()=>{if(gen!==st.gen)return;void go()};
if(window.requestIdleCallback)requestIdleCallback(kick,{timeout:120});
else setTimeout(kick,0);
}
