async function loadModifications(p=1){await ensureCraftUiCss();const s=S.modifications;s.page=p;s.q=document.getElementById('modFilter').value.trim();if(instantBrowseReady('modifications')&&!instantBrowseQueryNeedsServer(s.q,'modifications')&&instantBrowseApply('modifications',p,s.q)){scheduleInstantBrowseWarm('modifications');return}const pp=document.getElementById('modPerPage').value;const rq=getRarityQuerySuffix('mod');const ef=encodeURIComponent(s.effectFilter||'ALL');const linQ=getLineageQuerySuffix('mod');const linOp=getLineageOpSuffix('mod');const url=`/api/option_parts?lang=${S.lang}&page=${p}&per_page=${pp}&sort=${s.sort}&dir=${s.dir}&q=${encodeURIComponent(s.q)}${rq}&effect=${ef}${linQ}${linOp}`;showLoad('mod',true);setBrowseToolbarCount('mod','<span style="color:var(--text-muted)">\u2026</span>');try{const r=await fetchBrowseJson(url);if(!r.ok||!r.data||typeof r.data.total!=='number'){showBrowseLoadError('mod',t('empty_mod'));return}const d=r.data;if(d.effect_filter_icons)S._modEffectFilterIcons=d.effect_filter_icons;else S._modEffectFilterIcons=null;renderModT(d);renderPag('mod',d);setBrowseToolbarCount('mod',`<span class="result-count-num">${d.total}</span> ${t('count_mod')}`);updateModEffectFilterLabel();applyModEffectDropdownIcons();scheduleInstantBrowseWarm('modifications')}catch(e){showBrowseLoadError('mod',String(e&&e.message||e))}finally{showLoad('mod',false);afterListLoadIfSpotlightOpen()}}
function showLoad(pfx,s){document.getElementById(`${pfx}Loading`).style.display=s?'flex':'none';document.getElementById(`${pfx}Empty`).style.display='none';/* Soft lang-switch: keep prior rows under the spinner so locale changes don't flash empty. */
if(s&&!S._softListReload){document.getElementById(`${pfx}Body`).innerHTML='';const gid=pfx==='char'?'charGrid':pfx==='unit'?'unitGrid':pfx==='supp'?'suppGrid':pfx==='stage'?'stageGrid':pfx==='mod'?'modGrid':'';if(gid){const g=document.getElementById(gid);if(g)g.innerHTML=''}}if(!s&&S._softListReload)S._softListReload=0}
function charListStatCell(r,k){const tot=Number(r[k]||0);const b=r[k+'_base'];const base=b===undefined||b===null?NaN:Number(b);const boosted=!isNaN(base)&&tot>base;const cls=boosted?' stat-boosted':'';const tip=boosted?` title="${esc(t('char_list_stat_base_hint').replace('{n}',String(fmtN(base))))}"`:'';return`<span class="stat-value${cls}"${tip}>${fmtN(tot)}</span>`}
function renderSkillTags(std){if(!std||!std.length)return'';return std.map(sk=>{let tags=sk.tags||[];if(!tags.length)return'';let sep='';if(sk.separator==='and')sep=`<span style="display:flex;align-items:center;color:#a855f7;font-weight:900;font-size:16px;margin:0 2px;">+</span>`;else if(sk.separator==='or')sep=`<span style="display:flex;align-items:center;color:#a855f7;font-weight:900;font-size:13px;margin:0 4px;">${t('tag_or')}</span>`;else sep='<span style="margin:0 2px;"> </span>';return tags.map(tag=>{let cn=tag.name||'',ct=tag.type||'',cTags,cOp;if(sk.separator==='and'){cTags=tags.map(tg=>tg.name).join(',');cOp='and'}else{cTags=cn;cOp='or'}let li='';if(ct==='unit')li='/static/images/UI/UI_Common_Icon_Category_MS_Main.webp';else if(ct==='character')li='/static/images/UI/UI_Common_Icon_Category_Chara_Main.webp';else li='/static/images/UI/UI_Common_Icon_Category_MS_Main.webp';return`<div class="tag-composite" onclick="event.stopPropagation();openTagModal('${esc(cTags)}','${cOp}')" title="Click to view"><div class="tag-part-icon">${li?`<img class="tag-icon-fg" src="${imgUrl(li)}" alt="" loading="lazy" onerror="this.style.display='none'">`:''}</div><div class="tag-part-value">${esc(cn)}</div></div>`}).join(sep)}).join('<div style="width:100%;height:6px;"></div>')}
function openSeriesModal(seriesSid,listTab,seriesName){const sid=String(seriesSid||'').trim();if(!sid||sid==='0')return;S._tagModalMode='series';S._seriesModalSid=sid;S._seriesModalName=seriesName!=null?String(seriesName):'';S._tagTargetType=listTab==='units'?'unit':'character';const tm=document.getElementById('tagModal');const ta=document.getElementById('tagTabAffinity');if(ta)ta.style.display='none';document.getElementById('tagTabUnit').classList.toggle('active',S._tagTargetType==='unit');document.getElementById('tagTabChar').classList.toggle('active',S._tagTargetType==='character');if(ta)ta.classList.remove('active');tm.classList.add('active');applyBackgroundScrollLock();S._tagRarityFilter='ALL';S._tagAcqFilter='ALL';updateSeriesModalTitle();fetchAndRenderSeriesModal()}
function initSeriesIconNav(){document.addEventListener('click',function(e){const hit=e.target.closest('.series-icon-hitbox');if(!hit)return;const sid=(hit.getAttribute('data-series-id')||'').trim();const tab=hit.getAttribute('data-list-tab')||'';if(!sid||sid==='0')return;if(tab!=='characters'&&tab!=='units')return;e.preventDefault();e.stopPropagation();if(typeof e.stopImmediatePropagation==='function')e.stopImmediatePropagation();const name=hit.getAttribute('data-series-name')||'';openSeriesModal(sid,tab,name)},true)}
function applySeriesSearchFromList(seriesName,tab,seriesSid){closeModal();switchTab(tab);const sid=seriesSid!=null&&String(seriesSid).trim()!==''?String(seriesSid).trim():'';const q=(sid&&sid!=='0')?`series_id:${sid}`:`series: ${seriesName}`;const ppOpt={perPage:100};const ppSel=document.getElementById(tab==='characters'?'charPerPage':'unitPerPage');if(ppSel)ppSel.value='100';if(tab==='characters'){document.getElementById('charFilter').value=q;syncBrowseSearchWidth('charFilter');loadCharacters(1,ppOpt)}else{document.getElementById('unitFilter').value=q;syncBrowseSearchWidth('unitFilter');loadUnits(1,ppOpt)}try{window.scrollTo({top:0,behavior:'smooth'})}catch(_){window.scrollTo(0,0)}}
function browseRowPaintSig(r){return [r.id,r.name,r.thum,r.HP,r.EN,r.ATK,r.DEF,r.MOB,r.MOV,r.Ranged,r.Melee,r.Awaken,r.Defense,r.Reaction].join('|')}
function browseSuppRowPaintSig(r){return [r.id,r.name,r.thum,r.series_tag,r.boost,r.active_icon,JSON.stringify(r.skill_tag_data||[])].join('|')}
function browseModRowPaintSig(r){return [r.id,r.name,r.thum,r.rarity,r.details,r.variant_tag_id,JSON.stringify(r.tags||[])].join('|')}
function browseStageRowPaintSig(r){return [r.id,r.name,r.portrait,r.stage_number,r.recommended_cp,r.terrain,r.difficulty_code,r.content_locked,r.challenge_is_hard].join('|')}
function browseKeyedReplace(host,rows,htmlFn,sigFn){
if(!host)return;
const sigOf=sigFn||browseRowPaintSig;
const list=Array.isArray(rows)?rows:[];
const kids=host.children;
if(kids.length===list.length){
let same=true;
for(let i=0;i<list.length;i++){
if(kids[i].getAttribute('data-detail-id')!==String(list[i].id)||kids[i].getAttribute('data-row-sig')!==sigOf(list[i])){same=false;break}
}
if(same)return;
}
const prev=new Map();
for(let i=0;i<kids.length;i++){
const id=kids[i].getAttribute('data-detail-id');
if(id)prev.set(id,kids[i]);
}
const frag=document.createDocumentFragment();
const isTr=host.tagName==='TBODY';
const box=document.createElement(isTr?'table':'div');
const mount=isTr?(box.appendChild(document.createElement('tbody'))):box;
for(let i=0;i<list.length;i++){
const r=list[i];
const id=String(r.id);
const sig=sigOf(r);
let el=prev.get(id);
if(el&&el.getAttribute('data-row-sig')===sig){frag.appendChild(el);continue}
mount.innerHTML=htmlFn(r,i);
el=mount.firstElementChild;
if(el){el.setAttribute('data-row-sig',sig);frag.appendChild(el)}
}
host.replaceChildren(frag);
}
function renderCharTable(data){const thSz=tableListThumbSize();browseKeyedReplace(document.getElementById('charBody'),data.rows,(r,idx)=>`<tr data-detail-type="character" data-detail-id="${escAttr(String(r.id))}" onclick="openDetail('character','${r.id}')"><td class="col-thum">${renderListThumb(r,'char',thSz,{eager:idx<BROWSE_THUMB_EAGER_COUNT})}</td><td class="col-name"><div class="name-cell"><span class="name-text">${esc(r.name)}</span></div></td><td class="col-stat">${charListStatCell(r,'Ranged')}</td><td class="col-stat">${charListStatCell(r,'Melee')}</td><td class="col-stat">${charListStatCell(r,'Awaken')}</td><td class="col-stat">${charListStatCell(r,'Defense')}</td><td class="col-stat">${charListStatCell(r,'Reaction')}</td></tr>`)}
