function stageBrowseThumbTitleHtml(r,locked){if(locked)return`<span class="stage-browse-thumb__title">${esc(t('er_stage_redacted_row'))}</span>`;const isSa=r.stage_category==='score_attack';const isSs=r.stage_category==='special_stage';const isTs=r.stage_category==='tower_stage';const isCh=r.stage_category==='challenge_stage';if(isSs)return`<span class="stage-browse-thumb__title">${esc(r.name)}</span><span class="stage-browse-thumb__subtitle">${esc(t('stage_source_special'))}</span>`;if(isCh){const hard=!!r.challenge_is_hard;if(hard)return`<span class="stage-browse-thumb__title"><b>${esc(t('col_stage_no'))} ${fmtN(r.stage_number)}</b></span>`;return`<span class="stage-browse-thumb__title"><b>${esc(t('col_stage_no'))} ${fmtN(r.stage_number)}</b> ${esc(r.name)}</span>`}if(isTs||isSa)return`<span class="stage-browse-thumb__title">${esc(r.name)}</span>`;return`<span class="stage-browse-thumb__title"><b>${esc(t('col_stage_no'))} ${fmtN(r.stage_number)}</b> ${esc(r.name)}</span>`}
function renderStageBrowseThumb(r,opts){opts=opts||{};const variant=opts.variant||'table';const eager=!!opts.eager;const locked=!!r.content_locked;const isSa=r.stage_category==='score_attack';const isSs=r.stage_category==='special_stage';const isTs=r.stage_category==='tower_stage';const isCh=r.stage_category==='challenge_stage';const isChHard=isCh&&!!r.challenge_is_hard;const posterPortrait=isSs||isTs||isSa||isCh;const noShade=posterPortrait;const showDiff=!locked&&!(isSa||isSs||isTs||isCh);const diffCode=esc(r.difficulty_code||'unknown');const diffHtml=showDiff?`<span class="stage-diff-badge stage-diff-${diffCode} stage-browse-thumb__diff">${esc(r.difficulty_name||'-')}</span>`:'';const hardBadge=(!locked&&isChHard)?`<span class="stage-browse-thumb__hard-badge stage-browse-thumb__hard-badge--inline">${esc(t('stage_challenge_hard_label'))}</span>`:'';const portCls=(isSs||isSa||isCh)?' stage-browse-thumb__portrait--banner':isTs?' stage-browse-thumb__portrait--poster':' stage-browse-thumb__portrait--unit';const phPoster=(isSs||isSa||isCh)?' stage-browse-thumb__ph--banner':isTs?' stage-browse-thumb__ph--poster':' stage-browse-thumb__ph--unit';const portrait=locked?'':(r.portrait?imgTag(r.portrait,{cls:'stage-browse-thumb__portrait'+portCls,webp:true,alt:'',lazy:!eager,loading:eager?'eager':'lazy',fetchpriority:eager?'high':'low',decoding:'async',onerror:"this.style.display='none'"}) :'');const phFallback=!locked&&!r.portrait?'<span class="stage-browse-thumb__ph'+phPoster+'" aria-hidden="true">🗺️</span>':'';const lockOv=locked?'<span class="stage-browse-thumb__lock" aria-hidden="true">🔒</span>':'';const vCls=variant==='grid'?' stage-browse-thumb--grid':variant==='compact'?' stage-browse-thumb--compact':'';const themeCls=isSs?' stage-browse-thumb--special':(isTs||isSa)?' stage-browse-thumb--tower':'';const hardCls=isChHard?' stage-browse-thumb--hard':'';const lockCls=locked?' stage-browse-thumb--locked':'';const shadeHtml=noShade?'':'<div class="stage-browse-thumb__shade" aria-hidden="true"></div>';const headInner=stageBrowseThumbTitleHtml(r,locked);const headCls=`stage-browse-thumb__head${diffHtml?'':' stage-browse-thumb__head--no-diff'}${isChHard?' stage-browse-thumb__head--hard':''}`;const headHtml=`<div class="${headCls}">${hardBadge}${diffHtml}${headInner}</div>`;return`<div class="stage-browse-thumb${vCls}${themeCls}${hardCls}${lockCls}" role="presentation"><div class="stage-browse-thumb__bg" aria-hidden="true"></div><div class="stage-browse-thumb__stripes" aria-hidden="true"></div>${portrait}${phFallback}${shadeHtml}${lockOv}<div class="stage-browse-thumb__ui">${headHtml}</div></div>`}
