const STAGE_SOURCE_SPECIAL_ICON='/static/images/UI/UI_Event_SpecialStage_Logo.webp'
function syncStageSourceBrandButton(btn,kind,active){if(!btn)return;const cfg={eternal:{labelKey:'stage_source_btn_eternal',ariaKey:'stage_source_eternal',bg:'2',mod:'eternal'},challenge:{labelKey:'stage_source_btn_challenge',ariaKey:'stage_source_challenge',bg:'1',mod:'challenge'},tower:{labelKey:'stage_source_btn_tower',ariaKey:'stage_source_tower',bg:'2',mod:'tower'},score:{labelKey:'stage_source_btn_score',ariaKey:'stage_source_score',bg:'2',mod:'score'},special:{icon:STAGE_SOURCE_SPECIAL_ICON,ariaKey:'stage_source_special',mod:'special'}}[kind];if(!cfg)return;const aria=t(cfg.ariaKey);btn.classList.toggle('active',!!active);btn.setAttribute('aria-pressed',active?'true':'false');btn.title=aria;btn.setAttribute('aria-label',aria);btn.classList.add('stage-source-toggle-btn--brand');btn.classList.remove('stage-source-toggle-btn--brand-icon','stage-source-toggle-btn--eternal','stage-source-toggle-btn--challenge','stage-source-toggle-btn--tower','stage-source-toggle-btn--score','stage-source-toggle-btn--special');btn.classList.add('stage-source-toggle-btn--'+cfg.mod);if(cfg.icon){btn.classList.add('stage-source-toggle-btn--brand-icon');btn.style.backgroundImage='';const srcA=imgSrcAttr(cfg.icon);btn.innerHTML=srcA?'<img class="stage-source-brand-icon" alt="'+escAttr(aria)+'"'+srcA+' loading="lazy" decoding="async">':esc(aria);return}btn.classList.remove('stage-source-toggle-btn--brand-icon');const bgUrl=_stageSourceBtnBgUrl(cfg.bg);btn.style.backgroundImage=bgUrl?'url("'+escAttr(bgUrl)+'")':'';btn.innerHTML='<span class="stage-source-brand-label">'+esc(t(cfg.labelKey))+'</span>'}
