const stats_no_cond=_npcEmbedStatRows(emb.stats_raw||{},emb.bonus_amounts||{},order);
const hasCond=emb.stats_raw_with_cond&&typeof emb.stats_raw_with_cond==='object';
const stats_with_cond=hasCond?_npcEmbedStatRows(emb.stats_raw_with_cond,emb.bonus_amounts_with_cond||{},order):stats_no_cond;
const block={stats_no_cond,stats_with_cond,sp_stats_no_cond:stats_no_cond,sp_stats_with_cond:stats_with_cond,ssp_stats_no_cond:stats_no_cond,ssp_stats_with_cond:stats_with_cond};
