const NPC_SUPPORT_STAT_DEFAULT_CAP=5;
const NPC_SUPPORT_ATK_EXPLICIT_PATTERNS=[/Support\s+Attack\s*\/\s*Counter[\s\S]{0,200}?[+\uFF0B]\s*(\d+)/gi,/Support\s+Attack(?!\s*\/\s*Counter)[\s\S]{0,160}?[+\uFF0B]\s*(\d+)/gi,/「支援攻[撃擊][/／]反[擊撃]」[+\uFF0B]\s*(\d+)回/g,/「支援攻[撃擊][/／]反[擊撃]」[+\uFF0B]\s*(\d+)次/g];
const NPC_SUPPORT_CHANCE_EXPLICIT_PATTERNS=[/Force\s+activate\s+Chance\s+Step\s+(\d+)/gi,/チャンスステップを(\d+)回強制発動/g,/強制發動(\d+)次額外行動/g,/get\s+(\d+)\s+Guaranteed\s+Chance\s+Step(?:s)?/gi,/Guaranteed\s+Chance\s+Step(?:s)?\s*[+＋]\s*(\d+)/gi,/Chance\s+Step\s*[+＋]\s*(\d+)\s*time/gi,/Chance\s+Step\s*[+＋]\s*(\d+)/gi,/額外行動\s*[+＋]\s*(\d+)/g,/チャンスステップ\s*[+＋]\s*(\d+)/g];
const NPC_SUPPORT_LV_TITLE_PATTERNS={atk:[/Support\s+Attack\s*(?:\/\s*Counter)?\s*(?:Support\s+)?LV\s*(\d+)/gi,/支援攻[撃擊](?:\s*[／/]\s*反[擊撃])?\s*(?:Support\s+)?LV\s*(\d+)/gi],def:[/Support\s+Defense\s+LV\s*(\d+)/gi,/支援防[禦御]\s*LV\s*(\d+)/gi],chance:[/Chance\s+Step\s+Increase\s+LV\s*(\d+)/gi,/チャンスステップ(?:強化|増加)?\s*LV\s*(\d+)/gi,/額外行動\s*LV\s*(\d+)/gi]};
function _npcChanceBonusFromAbilityText(tx){return Math.max(_npcRegexCaptureMaxAcrossPatterns(tx,NPC_SUPPORT_CHANCE_EXPLICIT_PATTERNS),_countCharActionPlusOne(tx,'chance'))}
function _npcAtkBonusFromAbilityText(tx){return Math.max(_npcRegexCaptureMaxAcrossPatterns(tx,NPC_SUPPORT_ATK_EXPLICIT_PATTERNS),_supportAtkBonusFromAbilityDetailText(tx))}
function _npcDetailEntityAbilityNameAndDetailStrings(ent){if(!ent||!Array.isArray(ent.abilities))return[];let rows=ent.abilities.slice();if(!S.spActive)rows=rows.filter(ba=>!(ba&&ba.sp_replacement&&isUnknownAbilityName(ba.name)));const out=[];rows.forEach(ba=>{let ab=ba;if(S.spActive&&ba.sp_replacement)ab=ba.sp_replacement;if(ab&&ab.name){const nm=String(ab.name).trim();if(nm)out.push(nm)}const ds=Array.isArray(ab.details)?ab.details:[];ds.forEach(det=>{const raw0=typeof det==='string'?det:String(det&&det.text||'');const raw=String(raw0).trim();if(!raw)return;out.push(raw)})});return out}
function _npcAbilityCombinedTexts(ent){if(!ent||!Array.isArray(ent.abilities))return[];let rows=ent.abilities.slice();if(!S.spActive)rows=rows.filter(ba=>!(ba&&ba.sp_replacement&&isUnknownAbilityName(ba.name)));const out=[];rows.forEach(ba=>{let ab=ba;if(S.spActive&&ba.sp_replacement)ab=ba.sp_replacement;const chunks=[];if(ab&&ab.name){const nm=String(ab.name).trim();if(nm)chunks.push(nm)}const ds=Array.isArray(ab.details)?ab.details:[];ds.forEach(det=>{const raw0=typeof det==='string'?det:String(det&&det.text||'');const raw=String(raw0).trim();if(raw)chunks.push(raw)});if(chunks.length)out.push(chunks.join('\n'))});return out}
function _npcContextAbilityTextsForSupport(d,includeSelf,includeChar,includeUnit){const uniq=new Set();const out=[];const push=(arr)=>{(arr||[]).forEach(x=>{const t=String(x||'').trim();if(!t||uniq.has(t))return;uniq.add(t);out.push(t)})};if(includeSelf)push(_npcDetailEntityAbilityNameAndDetailStrings(d));const ctx=d&&d.detail_npc_context||{};if(includeChar)push(_npcDetailEntityAbilityNameAndDetailStrings(ctx.character));if(includeUnit)push(_npcDetailEntityAbilityNameAndDetailStrings(ctx.unit));return out}
function _npcMaxExplicitFromTexts(texts,patterns,useMaxAcrossPatterns){
const capture=useMaxAcrossPatterns?_npcRegexCaptureMaxAcrossPatterns:_npcRegexCaptureSum;
let max=0;(texts||[]).forEach(tx=>{max=Math.max(max,capture(String(tx||''),patterns))});return max}
function _npcMaxSupportLvFromTexts(texts,kind){const pats=NPC_SUPPORT_LV_TITLE_PATTERNS[kind]||[];let max=0;(texts||[]).forEach(tx=>{const s=String(tx||'');for(let pi=0;pi<pats.length;pi++){const re=pats[pi];re.lastIndex=0;let m;while((m=re.exec(s))){const v=parseInt(m[1],10);if(!isNaN(v))max=Math.max(max,v)}}});return max}
function _npcExplicitSupportStatMax(texts,kind,explicitPatterns){return Math.max(_npcMaxExplicitFromTexts(texts,explicitPatterns,true),_npcMaxSupportLvFromTexts(texts,kind))}
function _npcApplySupportStatCap(computed,explicitMax){const ex=Number(explicitMax)||0,c=Math.max(0,Number(computed)||0);if(ex>NPC_SUPPORT_STAT_DEFAULT_CAP)return Math.max(c,ex);return c}
function getNpcCharacterChanceSupportState(d){const combined=_npcAbilityCombinedTexts(d);
let chanceAdd=0,defAdd=0,atkAdd=0,allChanceStepBoost=false;
const chanceTexts=[];
combined.forEach(ps=>{
defAdd+=_supportDefBonusFromAbilityDetailText(ps);
atkAdd+=_npcAtkBonusFromAbilityText(ps);
if(!_npcChanceTextAppliesToCurrent(ps,d))return;
chanceTexts.push(ps);
chanceAdd+=_npcChanceBonusFromAbilityText(ps);
if(/activate\s+all\s+Chance\s+Step(?:s)?/i.test(ps))allChanceStepBoost=true;
});
const atkExplicit=_npcExplicitSupportStatMax(combined,'atk',NPC_SUPPORT_ATK_EXPLICIT_PATTERNS);
const defExplicit=_npcExplicitSupportStatMax(combined,'def',SUPPORT_DEF_NUMERIC_PATTERNS);
const chanceExplicit=_npcExplicitSupportStatMax(chanceTexts,'chance',NPC_SUPPORT_CHANCE_EXPLICIT_PATTERNS);
let chanceRaw=1+chanceAdd;
if(allChanceStepBoost)chanceRaw=Math.max(chanceRaw,NPC_SUPPORT_STAT_DEFAULT_CAP);
const chanceCount=Math.max(1,_npcApplySupportStatCap(chanceRaw,chanceExplicit));
const supportDefCount=_npcApplySupportStatCap(defAdd,defExplicit);
const supportAtkCount=_npcApplySupportStatCap(atkAdd,atkExplicit);
return{chanceCount,supportDefCount,supportAtkCount}}
function getNpcPilotAccuracyPctBonusFromContext(unitData){const tx=_npcContextAbilityDetailStrings(unitData,false,true,false).join('\n');
const accPatterns=[/Increases?\s+(?:own\s+)?(?:ACC|Accuracy)\s+by\s+(\d+)\s*%/gi,/Increases?\s+own\s+(?:ACC|Accuracy)\s+and\s+(?:EVA|EVADE|Evasion)\s+by\s+(\d+)\s*%/gi,/Increases?\s+own\s+(?:ACC|Accuracy)\s+and\s+(?:Critical|CRIT)\s+by\s+(\d+)\s*%/gi,/自身の命中率が(\d+)%上昇/g,/自身の命中率と回避率が(\d+)%上昇/g,/自身命中率提升(\d+)%/g,/自身命中率及閃避率提升(\d+)%/g];
return _npcRegexCaptureSum(tx,accPatterns)}
function characterHasConditionalChanceOrSupportAbility(d){const blocks=_charAbilityTextBlocks(d);return blocks.some(b=>b&&b.conditional&&(_countCharActionPlusOne(b.text,'chance')>0||_countCharActionPlusOne(b.text,'def')>0||_supportAtkBonusFromAbilityDetailText(b.text)>0))}
function renderDetailIconCountRow(label,iconPath,count){const c=Math.max(0,Number(count)||0);const src=imgUrlPreferCdn('/static/images/UI/'+iconPath+'.webp');const icons=Array.from({length:c}).map(()=>`<img class="char-extra-info-icon" src="${src}" alt="" loading="lazy" decoding="async" onerror="this.style.display='none'">`).join('');return`<div class="char-extra-info-row"><div class="char-extra-info-label">${esc(label)}</div><div class="char-extra-info-icons">${icons||'<span class="char-extra-info-none">-</span>'}</div></div>`}
function charExtraInfoLabel(k){const l=String(S.lang||'EN');if(l==='TW'||l==='HK'){if(k==='chance')return'額外行動';if(k==='def')return'支援防禦';if(k==='atk')return'支援攻擊'}if(l==='JA'||l==='JP'){if(k==='chance')return'チャンスステップ';if(k==='def')return'支援防禦';if(k==='atk')return'支援攻擊'}if(k==='chance')return'Chance Step';if(k==='def')return'Support Defense';return'Support Attack'}
function renderCharacterExtraInfo(d){if(!d)return'';const s=d.detail_npc_context?getNpcCharacterChanceSupportState(d):getCharacterChanceSupportState(d);return`<div class="char-extra-info-wrap">${renderDetailIconCountRow(charExtraInfoLabel('chance'),'UI_Common_Icon_ChanceStep',s.chanceCount)}${renderDetailIconCountRow(charExtraInfoLabel('def'),'UI_Common_BattleIcon_AssistDeffence_S',s.supportDefCount)}${renderDetailIconCountRow(charExtraInfoLabel('atk'),'UI_Common_BattleIcon_AssistAtack_S',s.supportAtkCount)}</div>`}
function renderSspMaterialsSectionHtml(d){const m=d&&d.ssp_materials;if(!m)return'';const unlock=Array.isArray(m.unlock)?m.unlock:[];const cores=Array.isArray(m.custom_core)?m.custom_core:[];if(!unlock.length&&!cores.length)return'';function rowHtml(it,extra){const ic=it&&it.icon?`<img src="${imgUrl(it.icon)}" alt="" loading="lazy" decoding="async" style="width:28px;height:28px;object-fit:contain;margin-right:8px" onerror="this.style.display='none'">`:'';const cnt=(it&&it.count!=null)?` ×${esc(String(it.count))}`:'';const ex=extra?` <span style="opacity:.75">${esc(extra)}</span>`:'';return`<div class="ability-detail mod-details-cell" style="margin:0;display:flex;align-items:center;flex-wrap:wrap">${ic}<span>${esc((it&&it.name)||'')}${cnt}</span>${ex}</div>`}let body='';if(unlock.length){body+=`<div class="ability-detail" style="margin:0 0 6px;opacity:.85">${esc(t('ssp_mat_unlock')||'SSP unlock')}</div>`+unlock.map(it=>rowHtml(it)).join('<div style="height:6px"></div>')}if(cores.length){if(body)body+='<div style="height:10px"></div>';body+=`<div class="ability-detail" style="margin:0 0 6px;opacity:.85">${esc(t('ssp_mat_custom_core')||'Custom Core materials')}</div>`+cores.map(c=>{const lv=c.level!=null?`Lv ${c.level}`:'';const rp=c.release_point?` · ${c.release_point} pt`:'';return rowHtml(c.material,lv+rp)}).join('<div style="height:6px"></div>')}return`<div class="detail-section"><div class="section-title">${esc(t('ssp_materials')||'SSP materials')}</div><div class="ability-item"><div class="ability-info">${body}</div></div></div>`}
function fillDetailSspMaterials(type){const d=S.currentDetailData;const ssp=document.getElementById('detailSspMaterialsContainer');if(ssp)ssp.innerHTML=(type==='unit')?renderSspMaterialsSectionHtml(d):''}
function renderCharShell(d){const isNpc=!!(d&&d.detail_npc_context);const metaCore=!isNpc?(`${d.rarity_icon?`<img class="detail-rarity-icon" src="${imgUrl(d.rarity_icon)}" alt="${d.rarity}" loading="eager" decoding="async" fetchpriority="high">`:`<span class="rarity-badge rarity-${d.rarity}">${d.rarity}</span>`}<span class="detail-role-label">${d.role_icon?`<img src="${imgUrl(d.role_icon)}" alt="${d.role}" loading="eager" decoding="async">`:''}${esc(tRole(d.role))}${d.acquisition_icon?`<img class="detail-meta-icon" src="${imgUrl(d.acquisition_icon)}" alt="" loading="eager" decoding="async">`:''}</span>`):'';const metaSp=d.has_sp?`<div style="display:flex;gap:6px;align-items:center;margin-left:8px;"><button id="spToggleBtnChar" class="sp-toggle-btn${S.spActive?' active':''}" onclick="toggleStatState('sp')"><img src="${imgUrl('/static/images/UI/UI_Common_Icon_Sp.webp')}" alt="SP" loading="lazy"></button></div>`:'';return`<div class="modal-top-label">${t('char_data')}</div><div class="modal-entity-id">ID: ${d.id}</div>${renderDetailBackStrip(d)}<div class="detail-header char-detail-header${d.detail_return?' char-detail-header--tight-top':''}"><div class="detail-portrait-stack"><div class="detail-portrait-wrap">${detailHeroPortraitHtml(d.portrait,{cls:'detail-portrait',alt:esc(d.name),placeholder:'👤',onerror:"detailHeroPortraitFallback(this,'char')"})}</div><div class="detail-rec-shortcut-wrap detail-rec-shortcut--mobile">${renderRecommendUnitCard(d)}</div></div><div class="detail-title-area char-detail-title-area"><div class="char-detail-head-row"><div class="char-detail-head-main"><div class="detail-name">${esc(d.name)}</div><div class="detail-meta${isNpc?' detail-meta--npc':''}">${metaCore}${metaSp}</div><div id="charExtraInfo"></div><div id="npcUnitCondTargets"></div>${renderLimitedTimeBanner(d,'character')}</div><div class="detail-rec-shortcut-wrap detail-rec-shortcut--desktop">${renderRecommendUnitCard(d)}</div></div>${renderSeries(d.series,'characters')}${renderTags(d.tags,{type:'character',id:d.id})}<div class="header-stats-wrapper"><div id="detailStatsWrapper"></div></div></div>${renderDetailRankToggleSlotHtml(d,'character')}</div><div class="detail-body"><div id="detailAbilitiesContainer"></div><div id="detailSkillsContainer"></div></div>`}
function _detailUnitCpWeaponRangeBonus(wpn,unitData,opts){
if(!unitData||!Array.isArray(unitData.cp_weapon_range_mods))return 0;
opts=opts||{};
const cpOn=opts.assumeCondMet!=null?!!opts.assumeCondMet:(!!S.conditionalPassiveActive||!!(S.dc&&S.dc.unitCondPassive));
const vigorOnly=!!unitData.has_cond_weapon_range&&!unitData.has_cond_stats;
if(!cpOn&&!vigorOnly)return 0;
if(!cpOn&&vigorOnly&&!_dcVigorAtLeast(S.dc?S.dc.mpLevel:S.mpLevel||'medium',S.dc?._vigorCondThreshold||_dcVigorThresholdFromUnit(unitData)||'max'))return 0;
const wpnKeySet=new Set(_dcWeaponAttributeKeys(wpn));
const curVigor=VIGOR_LEVEL_ORDER[_dcNormMpLevel(S.dc?S.dc.mpLevel:S.mpLevel||'medium')]||0;
let bonus=0;
(unitData.cp_weapon_range_mods||[]).forEach(mod=>{
const types=mod.types||mod.type_keys||[];
const inc=mod.inc|0;
if(!inc)return;
if(types.length&&!types.some(t=>wpnKeySet.has(String(t).toLowerCase())))return;
const req=mod.req_vigor||'';
if(!cpOn&&req){
const reqLv=VIGOR_LEVEL_ORDER[_dcNormMpLevel(req)]!==undefined?VIGOR_LEVEL_ORDER[_dcNormMpLevel(req)]:99;
if(curVigor<reqLv)return;
}
bonus+=inc;
});
return bonus;
}
function _dcUnitCpRangeModsActive(){
const ud=S.dc&&S.dc.atkUnitData;
if(!ud||ud._manual)return false;
if(ud.has_cond_weapon_range&&!ud.has_cond_stats)return _dcIsVigorCondActive()||!!S.dc.unitCondPassive;
return !!S.dc.unitCondPassive;
}
function _dcUnitCpWeaponRangeBonusForDc(wpn){
const ud=S.dc&&S.dc.atkUnitData;
if(!ud||!_dcUnitCpRangeModsActive())return 0;
return _detailUnitCpWeaponRangeBonus(wpn,ud,{assumeCondMet:true});
}
