function invalidateEternalStageDetailCaches(stageId){const suf=':stage:'+String(stageId);for(const k of[..._detailJsonPrefetchCache.keys()]){if(k.endsWith(suf))_detailJsonPrefetchCache.delete(k)}}
function renderEternalStageLockedPanel(d){const needPw=d.password_required===true;const hint=needPw?t('er_stage_lock_hint'):t('er_stage_lock_wait');const form=needPw?`<div class="er-stage-lock-box" style="margin-top:0;border:none;background:transparent;padding:0"><p class="er-stage-lock-hint">${esc(hint)}</p><input type="password" id="erStageLockInput" autocomplete="current-password" maxlength="200" onkeydown="if(event.key==='Enter')submitEternalStageUnlock()" style="width:100%;padding:10px 12px;border-radius:var(--radius-sm);border:1px solid var(--border-color);background:var(--bg-input);color:var(--text-primary);font-size:16px;box-sizing:border-box"><div style="margin-top:12px"><button type="button" class="lr-unlock-btn" onclick="submitEternalStageUnlock()">${esc(t('er_stage_unlock_btn'))}</button></div><div class="lr-lock-err" id="erStageLockErr"></div></div>`:`<div class="er-stage-lock-box" style="margin-top:0;border:none;background:transparent;padding:0"><p class="er-stage-lock-hint">${esc(hint)}</p></div>`;return`<div class="modal-top-label">${esc(t('er_stage_redacted_title'))}</div><div class="detail-body profile-title-detail-body"><div class="er-stage-blackout"><div class="er-stage-blackout-inner"><div class="er-stage-blackout-icon" aria-hidden="true">🔒</div><div class="er-stage-blackout-title">${esc(t('er_stage_redacted_title'))}</div>${form}</div></div></div>`}
async function submitEternalStageUnlock(){const id=S.currentDetailData&&S.currentDetailData.id;const err=document.getElementById('erStageLockErr');if(id==null||id==='')return;const inp=document.getElementById('erStageLockInput');const pw=inp?String(inp.value||''):'';if(err)err.textContent='';try{const r=await fetch('/api/eternal_stages/unlock',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:pw})});if(!r.ok){if(err)err.textContent=t('er_stage_pw_wrong');return}invalidateEternalStageDetailCaches(id);browseListJsonCacheClearPrefix('/api/stages');_dcStagesCache=null;_dcStagesFetchLang=null;const inn=document.getElementById('detailInner');const d=await fetchDetailPayload('stage',String(id));if(d.content_locked){if(err)err.textContent=d.password_required?t('er_stage_pw_wrong'):t('er_stage_lock_wait');if(inn){inn.innerHTML=renderEternalStageLockedPanel(d);syncModalDetailChrome()}return}S.currentDetailData=d;if(inn){inn.innerHTML=renderStageShell(d);wireRewardDetailClicks(inn);syncModalDetailChrome()}updateDetailDynamicSections('stage');if(S.currentTab==='stages')loadStages(S.stages.page||1);const stgSel=document.getElementById('dcStageSelect');if(stgSel&&String(stgSel.value)===String(id))await onDcStageChange()}catch(e){if(err)err.textContent=String(e)}}
function renderSpConversionChipThumb(r,szOpt){const base=r&&r.sp_chip_base?String(r.sp_chip_base):'';const unit=r&&r.sp_chip_unit?String(r.sp_chip_unit):'';const frame=r&&r.sp_chip_frame?String(r.sp_chip_frame):'';if(!unit||(!frame&&!base))return'';const sz=Number(szOpt)>0?Number(szOpt):54;const layers=frame+base;const isSeriesSp=/UI_Common_Sp_Bg|UI_Common_Sp_Frame|UI_Common_Sp_Chara/i.test(layers);const isSeriesSsp=/Ssp_Frame|Ssp_Bg/i.test(layers);const isSeriesLogo=/Logo-Series|logo_l_series/i.test(unit)||isSeriesSp||isSeriesSsp;const layerImg=(path,style,alt)=>{const src=safeImgSrc(path);if(!src)return'';return`<img src="${escAttr(src)}" alt="${escAttr(alt||'')}" loading="lazy" decoding="async" style="${style}" onerror="gameImageUrlFallback(this)">`};if(isSeriesLogo){/* Series SP chips: Sp_Bg is 124x142 and must sit at (2,2) on Sp_Frame 135x146. Sp_Chara assets are same-size. Logo always on top. */const isSpChara=/Sp_Chara/i.test(layers);const logoStyle=isSeriesSp?'position:absolute;left:8%;top:30%;width:84%;height:40%;object-fit:contain;display:block;pointer-events:none;z-index:3;':'position:absolute;left:-12%;top:-12%;width:124%;height:124%;object-fit:contain;display:block;pointer-events:none;z-index:3;';const logoLayer=layerImg(unit,logoStyle,r.name||'');let baseLayer='',frameLayer='',plateWrap='';if(isSeriesSp&&!isSpChara&&base&&frame){const bgStyle='position:absolute;left:1.48148%;top:1.36986%;width:91.85185%;height:97.26027%;object-fit:fill;display:block;z-index:1;';const frStyle='position:absolute;inset:0;width:100%;height:100%;object-fit:fill;display:block;pointer-events:none;z-index:2;';baseLayer=layerImg(base,bgStyle,'');frameLayer=layerImg(frame,frStyle,'');plateWrap='1'}else{baseLayer=base?layerImg(base,'position:absolute;inset:0;width:100%;height:100%;object-fit:cover;display:block;z-index:1;',''):'';frameLayer=frame?layerImg(frame,'position:absolute;inset:0;width:100%;height:100%;object-fit:contain;display:block;pointer-events:none;z-index:2;',''):''}if(!logoLayer&&!baseLayer&&!frameLayer)return'';const cls=isSeriesSp?'sp-chip-thumb--series-sp':'sp-chip-thumb--series-ssp';const stack=`${baseLayer}${frameLayer}${logoLayer}`;const plate=plateWrap?`<div class="sp-chip-plate" style="position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);height:100%;width:auto;max-width:100%;aspect-ratio:135/146;">${stack}</div>`:stack;return`<div class="sp-chip-thumb ${cls}" style="width:${sz}px;height:${sz}px;position:relative;flex-shrink:0;overflow:visible;z-index:2;border-radius:8px;background:transparent;border:none;filter:drop-shadow(0 2px 6px rgba(0,0,0,.45));">${plate}</div>`}const baseLayer=base?layerImg(base,'position:absolute;inset:0;width:100%;height:100%;object-fit:cover;display:block;z-index:1;',''):'';if(!frame)return'';const hexClip='polygon(50% 7%, 93% 28%, 93% 72%, 50% 93%, 7% 72%, 7% 28%)';const unitLayer=layerImg(unit,`position:absolute;left:6%;top:13%;width:88%;height:74%;object-fit:cover;display:block;clip-path:${hexClip};-webkit-clip-path:${hexClip};z-index:2;`,r.name||'');const frameLayer=layerImg(frame,'position:absolute;inset:0;width:100%;height:100%;object-fit:contain;display:block;pointer-events:none;z-index:3;','');if(!unitLayer&&!baseLayer&&!frameLayer)return'';return`<div class="sp-chip-thumb" style="width:${sz}px;height:${sz}px;position:relative;flex-shrink:0;overflow:hidden;border-radius:8px;background:rgba(255,255,255,0.04);border:1px solid var(--border-color);">${baseLayer}${unitLayer}${frameLayer}</div>`}

