function ensureDetailRankingToggleDom(type){
const d=S.currentDetailData;
const header=document.querySelector('.modal-content.char-detail .detail-header,.modal-content.unit-detail .detail-header');
if(!header)return;
header.querySelectorAll('.detail-rank-toggle-btn').forEach(btn=>{if(!btn.closest('#detailRankToggleSlot'))btn.remove()});
header.querySelectorAll('.detail-rank-toggle-slot').forEach(el=>{if(el.id!=='detailRankToggleSlot')el.remove()});
let slot=document.getElementById('detailRankToggleSlot');
if(slot&&slot.parentElement!==header){slot.remove();slot=null}
if(!slot){
header.insertAdjacentHTML('beforeend','<div class="detail-rank-toggle-slot" id="detailRankToggleSlot"></div>');
slot=document.getElementById('detailRankToggleSlot');
}
if(!slot)return;
if(!(d&&d.ranking_available&&(type==='character'||type==='unit')&&!d.detail_npc_context)){slot.innerHTML='';return}
slot.innerHTML=renderDetailRankingToggle(d,type)||'';
}
function detailStatRowsForCurrentState(d,type){let hcf=type==='character'?(d.has_conditional_passive!=null?d.has_conditional_passive:d.has_ex_stats):d.has_cond_stats;const cp=hcf&&S.conditionalPassiveActive;let sr;if(type==='unit'){const td=(d.lb_data&&d.lb_data[S.currentLbTier])||(d.stats&&{stats_no_cond:d.stats,stats_with_cond:d.stats,sp_stats_no_cond:d.stats,sp_stats_with_cond:d.stats,ssp_stats_no_cond:d.stats,ssp_stats_with_cond:d.stats});if(!td)return[];if(d.has_sp){if(S.sspActive)sr=cp?td.ssp_stats_with_cond:td.ssp_stats_no_cond;else if(S.spActive)sr=cp?td.sp_stats_with_cond:td.sp_stats_no_cond;else sr=cp?td.stats_with_cond:td.stats_no_cond}else sr=cp?td.stats_with_cond:td.stats_no_cond}else{const exTiers=d.ex_supercharged_tiers;if(cp&&exTiers&&exTiers.length>1){const ti=Math.min(Math.max(0,S.charSuperchargedExTier|0),exTiers.length-1);sr=exTiers[ti].stats}else if(d.has_sp){if(S.spActive)sr=cp?d.sp_stats_with_ex:d.sp_stats;else sr=cp?d.stats_with_ex:d.stats}else sr=cp?d.stats_with_ex:d.stats}return Array.isArray(sr)?sr:[]}
function renderDetailInlineRankRadial(meta){
if(!meta||!meta.rank||!meta.total)return`<div class="stat-inline-rank is-loading"><div class="radial-loading">...</div></div>`;
const rk=Math.max(1,Number(meta.rank)||1);
const tt=Math.max(1,Number(meta.total)||1);
const pct=Math.max(1,Math.min(100,Math.round((rk/tt)*100)));
const progressPercent=Math.max(5,95-((rk-1)/tt)*90);
const fillRatio=Math.max(.05,Math.min(.95,progressPercent/100));
const r=25;
const c=(Math.PI*2*r);
const off=(c*(1-fillRatio));
let rankText='',totalLine='';
if(S.lang==='EN')rankText=`${rk}`;
else rankText=`${fmtN(rk)}`;
totalLine=`/ ${fmtN(tt)}`;
let tone='#94a3b8';
let pctText=`TOP ${pct}%`;
let pulseFillCls='',pulseTextCls='';
let leakCls='';
if(rk===1){tone='#fbbf24';pctText='Top 1';leakCls='leak-shadow-strong'}
else if(rk<=3){tone='#22d3ee';pctText=`Top ${rk}`;leakCls='leak-shadow'}
else if(rk<=10){tone='#22d3ee';pctText=`Top ${rk}`;leakCls='leak-shadow-soft'}
else if(rk<=20){tone='#22d3ee';pctText=`Top ${rk}`}
else if(rk<=tt*0.05){tone='#34d399'}
else if(rk<=tt*0.25){tone='#60a5fa'}
else if(rk>tt*0.90){tone='#f87171';pctText=`BOTTOM ${Math.max(0,100-pct)}%`}
else{tone='#a5b4fc'}
return`<div class="stat-inline-rank ${leakCls}" style="--sir-c:${c.toFixed(2)};--sir-o:${off.toFixed(2)};--rank-tone:${tone}">
<svg class="radial-svg" viewBox="0 0 74 74" aria-hidden="true">
<circle class="progress-circle" cx="37" cy="37" r="${r}"></circle>
<circle class="progress-fill ${pulseFillCls}" cx="37" cy="37" r="${r}"></circle>
</svg>
<div class="inner-circle">
<div class="rank-wrap">
<div class="rank-label">RANK</div>
<div class="rank-text ${pulseTextCls}">${rankText}</div>
<div class="total">${totalLine}</div>
<div class="percentile ${pulseTextCls}">${pctText}</div>
</div>
</div>
</div>`;
}
function kickDetailRankRadialAnimation(root){
if(!root||!root.classList||root.classList.contains('is-loading'))return;
const f=root.querySelector('.progress-fill');
if(!f)return;
f.style.strokeDashoffset='var(--sir-c)';
setTimeout(()=>{if(root.isConnected)f.style.strokeDashoffset='var(--sir-o)'},100);
}
function applyDetailRankingInline(type){
const d=S.currentDetailData;
if(!d||!d.ranking_available||!S.detailRankingOverlay||(type!=='character'&&type!=='unit'))return;
const rows=detailStatRowsForCurrentState(d,type);
const cards=Array.from(document.querySelectorAll('#detailStatsWrapper .stat-card'));
if(!cards.length)return;
const ck=detailRankingCacheKey(type,d.id);
if(!_detailRankingStatsCache.has(ck)&&!_detailRankingStatsInflight.has(ck))void ensureDetailRankingStats(type,d.id).then(()=>{if(S.currentDetailType===type&&S.currentDetailData&&String(S.currentDetailData.id)===String(d.id))updateDetailDynamicSections(type)}).catch(()=>{});
cards.forEach((c,i)=>{
const s=rows[i];
if(!s)return;
const old=c.querySelector('.stat-inline-rank');
if(old)old.remove();
if(type==='unit'&&s.name==='Move')return;
const meta=detailRankingMetaFor(type,d.id,s.name);
c.insertAdjacentHTML('beforeend',renderDetailInlineRankRadial(meta));
kickDetailRankRadialAnimation(c.querySelector('.stat-inline-rank'));
});
}
function _pilotTextTargetsUnit(ud,reqUnitRaw){
if(!ud)return false;
const unitName=(ud.name||'').toLowerCase();
const unitBare=(ud.name||'').replace(/\s*\(EX\)\s*/gi,'').trim().toLowerCase();
const ru=(reqUnitRaw||'').trim().toLowerCase();
if(!ru)return true;
const ruBare=ru.replace(/\s*\(ex\)\s*/g,'').trim();
return unitName.includes(ru)||ru.includes(unitBare)||unitBare.includes(ruBare)||ruBare.includes(unitBare);
}
function _abilityPhraseToWeaponEffectKeys(phrase){
const p=String(phrase||'').trim().toLowerCase();
const s=String(phrase||'');
const keys=new Set();
if(/^def$/i.test(p))keys.add('def_dn');
if(/^atk$/i.test(p))keys.add('atk_dn');
if(/^mob$/i.test(p))keys.add('mob_dn');
if(/^acc$/i.test(p))keys.add('acc_dn');
if(/beam.*damage taken|damage taken.*beam|ビーム武装被ダメージ/i.test(p+s))keys.add('dmg_beam');
if(/physical.*damage taken|damage taken.*physical|物理武装被ダメージ/i.test(p+s))keys.add('dmg_phys');
if(/special.*damage taken|damage taken.*special|特殊武装被ダメージ|特殊被ダメージ|特殊損傷|特殊损伤/i.test(p+s))keys.add('dmg_spec');
if(/def|防御力|防禦力/.test(p+s)&&/decrease|down|減少/.test(p+s))keys.add('def_dn');
if(/atk|attack|攻撃力|攻擊力/.test(p+s)&&/decrease|down|減少/.test(p+s))keys.add('atk_dn');
if(/mob|mobility|機動力/.test(p+s)&&/decrease|down|減少/.test(p+s))keys.add('mob_dn');
if(/acc|accuracy|命中/.test(p+s)&&/decrease|down|減少/.test(p+s))keys.add('acc_dn');
if(/ビーム武装被ダメージ上昇|ビーム.*被ダメージ.*上昇/.test(s))keys.add('dmg_beam');
if(/遭光束武裝攻擊時.*損傷提升|遭光束武裝攻擊時所受損傷提升/.test(s))keys.add('dmg_beam');
if(/遭鐳射武裝攻擊時.*損傷提升|遭鐳射武裝攻擊時所受損傷提升/.test(s))keys.add('dmg_beam');
if(/物理武装被ダメージ上昇/.test(s))keys.add('dmg_phys');
if(/特殊武装被ダメージ上昇|特殊被ダメージ上昇/.test(s))keys.add('dmg_spec');
if(/受到的特殊損傷提升|特殊損傷提升/.test(s))keys.add('dmg_spec');
if(/防御力減少/.test(s))keys.add('def_dn');
if(/防禦力減少/.test(s))keys.add('def_dn');
if(/攻撃力減少/.test(s))keys.add('atk_dn');
if(/攻擊力減少/.test(s))keys.add('atk_dn');
return keys;
}
function _traitLineWeaponEffectKeys(line){
const s=String(line||'');
const sl=s.toLowerCase();
const keys=new Set();
if(/damage taken from beam|damage taken from beam weapons up|ビーム武装(?:による)?被ダメージ|光束.*被|遭光束武裝攻擊時[，,]?受到的?損傷提升|遭鐳射武裝攻擊時[，,]?受到的?損傷提升/i.test(s))keys.add('dmg_beam');
if(/damage taken from physical|damage taken from physical weapons up|物理武装(?:による)?被ダメージ|遭物理武裝攻擊時[，,]?受到的?損傷提升/i.test(s))keys.add('dmg_phys');
if(/damage taken from special|damage taken from special weapons up|特殊武装(?:による)?被ダメージ|特殊被ダメージ|遭特殊武裝攻擊時[，,]?受到的?損傷提升|受到的特殊損傷提升/i.test(s))keys.add('dmg_spec');
if(/\bdef down\b/i.test(sl)||/防御力\s*\d+\s*%?\s*減少|防禦力\s*\d+\s*%?\s*減少|防御力減少|防禦力減少|防禦力減少\s*\d+\s*%|防御力減少\s*\d+\s*%/.test(s))keys.add('def_dn');
if(/\batk down\b/i.test(sl)||/攻撃力\s*\d+\s*%?\s*減少|攻擊力\s*\d+\s*%?\s*減少|攻撃力減少|攻擊力減少/.test(s))keys.add('atk_dn');
if(/\bmob down\b/i.test(sl)||/機動力\s*\d+\s*%?\s*減少|機動力減少/.test(s))keys.add('mob_dn');
if(/\bacc down\b/i.test(sl)||/命中率\s*\d+\s*%?\s*減少|命中率減少/.test(s))keys.add('acc_dn');
return keys;
}
function _parsePilotWeaponEffectAdditiveFromText(tx,ud,opts){
const bonuses=new Map();
const s=String(tx||'');
if(!s)return bonuses;
opts=opts||{};
const pilotPhrase=_pilotExclusiveAbilityPilotPhrase(s);
if(!opts.skipUnitGate&&pilotPhrase&&!_pilotTextTargetsUnit(ud,pilotPhrase))return bonuses;
let m;
const reEn=/improve\s+((?:(?:increase|decrease|increased|decreased)\s+)?.+?)\s+weapon effects by\s+(\d+)\s*%\s+additively/gi;
while((m=reEn.exec(s))!==null){
const pct=parseInt(m[2],10)||0;
if(!pct)continue;
_abilityPhraseToWeaponEffectKeys(m[1]).forEach(k=>bonuses.set(k,Math.max(bonuses.get(k)||0,pct)));
}
const reEn2=/additively\s+increase\s+((?:(?:increase|decrease|increased|decreased)\s+)?.+?)\s+weapon effects by\s+(\d+)\s*%/gi;
while((m=reEn2.exec(s))!==null){
const pct=parseInt(m[2],10)||0;
if(!pct)continue;
_abilityPhraseToWeaponEffectKeys(m[1]).forEach(k=>bonuses.set(k,Math.max(bonuses.get(k)||0,pct)));
}
const reJa=/(.+?)の武装効果値が(\d+)%加算/g;
while((m=reJa.exec(s))!==null){
const pct=parseInt(m[2],10)||0;
if(!pct)continue;
_abilityPhraseToWeaponEffectKeys(m[1]).forEach(k=>bonuses.set(k,Math.max(bonuses.get(k)||0,pct)));
}
const reTw=/(.+?)的武裝效果值增加(\d+)%/g;
while((m=reTw.exec(s))!==null){
const pct=parseInt(m[2],10)||0;
if(!pct)continue;
_abilityPhraseToWeaponEffectKeys(m[1]).forEach(k=>bonuses.set(k,Math.max(bonuses.get(k)||0,pct)));
}
return bonuses;
}
function _collectPilotWeaponEffectAdditiveBonuses(ud){
const merged=new Map();
if(!S.pilotConditionalPassiveActive||!ud)return merged;
const embedded=ud.pilot_weapon_effect_bonuses;
if(embedded&&typeof embedded==='object'){
Object.entries(embedded).forEach(([k,v])=>{const n=parseInt(v,10)||0;if(n)merged.set(k,n)});
if(merged.size)return merged;
}
if(!S.pilotCondCharData)return merged;
const cd=S.pilotCondCharData;
(cd.abilities||[]).forEach(ab=>{
let abilityTargetsUnit=false;
const pending=[];
(ab.details||[]).forEach(d2=>{
const tx=(typeof d2==='object'?d2.text:d2)||'';
if(!tx)return;
const phrase=_pilotExclusiveAbilityPilotPhrase(tx);
if(phrase&&_pilotTextTargetsUnit(ud,phrase))abilityTargetsUnit=true;
if(!/when piloting|搭乘|搭乗|weapon effects by|武装効果値が\d+%加算|武裝效果值增加\d+%|武裝效果.*?增加\d+%|additively\s+increase/i.test(tx))return;
let row=_parsePilotWeaponEffectAdditiveFromText(tx,ud);
if(!row.size&&abilityTargetsUnit&&/weapon effects by|武装効果値が\d+%加算|武裝效果值增加\d+%|additively\s+increase/i.test(tx)){
row=_parsePilotWeaponEffectAdditiveFromText(tx,ud,{skipUnitGate:true});
}
if(row.size)row.forEach((v,k)=>merged.set(k,Math.max(merged.get(k)||0,v)));
else if(/weapon effects by|武装効果値が\d+%加算|武裝效果值增加\d+%|additively\s+increase/i.test(tx))pending.push(tx);
});
if(abilityTargetsUnit){
pending.forEach(tx=>{
_parsePilotWeaponEffectAdditiveFromText(tx,ud,{skipUnitGate:true}).forEach((v,k)=>merged.set(k,Math.max(merged.get(k)||0,v)));
});
}
});
return merged;
}
function _textImpliesPilotingTagAffinity(tx){
return /piloting units with specified tags|指定.*?タグ|指定.*?標籤|指定.*?标签|含有上述「標籤」|搭乘單位含有上述「標籤」|上記の「タグ」|搭乗ユニットが上記の「タグ」|critical rate|暴擊率|暴击率|爆擊率|EN consumption|消費EN|消耗EN|damage dealt|与ダメージ|造成的損傷/i.test(String(tx||''));
}
function _extractEnConsumptionReductionPct(tx){
const s=String(tx||'');
let out=0;
const pats=[/reduce\s+(?:own\s+)?(?:weapon\s+)?EN\s+consumption\s+by\s+(\d+)\s*%/i,/weapon\s+EN\s+consumption\s+by\s+(\d+)\s*%/i,/消費ENが(\d+)%軽減/,/武装の消費ENが(\d+)%軽減/,/消耗EN減輕(\d+)%/,/武裝消耗EN減輕(\d+)%/];
pats.forEach(re=>{const m=s.match(re);if(m)out=Math.max(out,parseInt(m[1],10)||0)});
return out;
}
function _detailPilotEnCostReductionPct(ud){
if(!S.pilotConditionalPassiveActive||!ud)return 0;
const embedded=parseInt(ud.pilot_en_cost_reduction_pct,10)||0;
if(embedded)return embedded;
if(!S.pilotCondCharData)return 0;
let pct=0;
const cd=S.pilotCondCharData;
(cd.abilities||[]).forEach(ab=>{
(ab.details||[]).forEach(d2=>{
const tx=(typeof d2==='object'?d2.text:d2)||'';
if(!tx||!/EN\s+consumption|消費EN|消耗EN|EN消費|EN消耗/i.test(tx))return;
const phrase=_pilotExclusiveAbilityPilotPhrase(tx);
if(phrase&&_pilotTextTargetsUnit(ud,phrase)){
pct=Math.max(pct,_extractEnConsumptionReductionPct(tx));
return;
}
if(typeof d2==='object'&&_textImpliesPilotingTagAffinity(tx)&&_unitTagsMatchAbilityDetail(d2,ud.tags)){
pct=Math.max(pct,_extractEnConsumptionReductionPct(tx));
}
});
});
return pct;
}
function _detailUnitEnCostIncreasePct(ud){
if(!ud)return 0;
const emb=ud.weapon_en_cost_increase_pct;
if(emb&&typeof emb==='object'){
const base=S.sspActive?(emb.ssp|0):(emb.sp|0);
const cond=S.conditionalPassiveActive?(S.sspActive?(emb.ssp_cond|0):(emb.sp_cond|0)):0;
return Math.max(0,(base|0)+(cond|0));
}
return Math.max(0,parseInt(emb,10)||0);
}
function _detailWeaponEnCostDisplay(baseEn,ud){
const b=Math.max(0,baseEn|0);
const inc=_detailUnitEnCostIncreasePct(ud)|0;
const red=_detailPilotEnCostReductionPct(ud)|0;
// Additive EN cost mods: 45×(1+0.40−0.25)=45×1.15→51 (not multiplicative 1.4×0.75).
const net=inc-red;
const v=Math.max(0,Math.floor(b*(100+net)/100));
const delta=v-b;
let cls='';
if(delta>0)cls='weapon-en-increased';
else if(delta<0)cls='weapon-en-reduced';
const deltaHtml=delta?`<span class="weapon-en-delta">(${delta>0?'+':''}${delta})</span>`:'';
return{en:v,cls,base:b,inc,red,delta,deltaHtml};
}
function _collectLineageTagNamesFromAbilityDetail(detail){
const names=new Set();
if(!detail||typeof detail!=='object')return names;
function addConds(arr){
(arr||[]).forEach(c=>{
if(!c||typeof c!=='object')return;
const tp=String(c.type||'').toLowerCase();
if(tp==='lineage'||tp==='tag'||tp==='group'||tp==='unit'||tp==='character'||tp==='affiliation'){
const n=String(c.name||c.label||'').trim();
if(n)names.add(n.toLowerCase());
}
});
}
addConds(detail.conditions);
(detail.condition_groups||[]).forEach(g=>{if(g&&typeof g==='object')addConds(g.conditions)});
return names;
}
function _unitTagsMatchAbilityDetail(detail,unitTags){
const req=_collectLineageTagNamesFromAbilityDetail(detail);
if(!req.size)return false;
const unitNames=new Set((unitTags||[]).map(t=>String(t.name||'').trim().toLowerCase()).filter(Boolean));
return[...req].some(r=>unitNames.has(r));
}
function _extractPilotWeaponStatPctFromText(tx){
const s=String(tx||'');
const out={acc:0,crit:0};
let m=s.match(/Increases?\s+own\s+(?:ACC|Accuracy)\s+and\s+(?:EVA|EVADE|Evasion)\s+by\s+(\d+)\s*%/i);
if(m)out.acc=Math.max(out.acc,parseInt(m[1],10)||0);
m=s.match(/Increases?\s+own\s+(?:ACC|Accuracy)\s+and\s+(?:Critical|CRIT)\s+by\s+(\d+)\s*%/i);
if(m){const p=parseInt(m[1],10)||0;out.acc=Math.max(out.acc,p);out.crit=Math.max(out.crit,p)}
m=s.match(/Increases?\s+(?:own\s+)?(?:ACC|Accuracy)\s+by\s+(\d+)\s*%/i);
if(m)out.acc=Math.max(out.acc,parseInt(m[1],10)||0);
m=s.match(/Increases?\s+(?:own\s+)?(?:Critical|CRIT)\s+by\s+(\d+)\s*%/i);
if(m)out.crit=Math.max(out.crit,parseInt(m[1],10)||0);
m=s.match(/Increases?\s+own\s+critical rate by\s+(\d+)\s*%/i);
if(m)out.crit=Math.max(out.crit,parseInt(m[1],10)||0);
m=s.match(/自身の命中率と回避率が(\d+)%上昇/);
if(m)out.acc=Math.max(out.acc,parseInt(m[1],10)||0);
m=s.match(/自身命中率(?:及|和)閃避率提升(\d+)%/);
if(m)out.acc=Math.max(out.acc,parseInt(m[1],10)||0);
m=s.match(/自身(?:的)?(?:暴擊|暴击|爆擊)率提升(\d+)%/);
if(m)out.crit=Math.max(out.crit,parseInt(m[1],10)||0);
return out;
}
function _detailPilotAffinityWeaponStatBonuses(ud){
const out={acc:0,crit:0};
if(!S.pilotConditionalPassiveActive||!ud)return out;
const embedded=ud.pilot_tag_weapon_stat_bonuses;
if(embedded&&typeof embedded==='object'){
out.acc=parseInt(embedded.acc,10)||0;
out.crit=parseInt(embedded.crit,10)||0;
if(out.acc||out.crit)return out;
}
if(!S.pilotCondCharData)return out;
const cd=S.pilotCondCharData;
(cd.abilities||[]).forEach(ab=>{
(ab.details||[]).forEach(d2=>{
if(typeof d2!=='object')return;
const tx=String(d2.text||'');
if(!_textImpliesPilotingTagAffinity(tx))return;
if(!_unitTagsMatchAbilityDetail(d2,ud.tags))return;
const row=_extractPilotWeaponStatPctFromText(tx);
out.acc=Math.max(out.acc,row.acc);
out.crit=Math.max(out.crit,row.crit);
});
});
return out;
}
function _pepWeaponEffectNoteLabel(bonus,keys){
const decKeys=['def_dn','atk_dn','mob_dn','acc_dn'];
const isDec=[...keys].some(k=>decKeys.includes(k));
return isDec?`(${bonus}% Additional Decrease)`:`(${bonus}% Additional Increase)`;
}
function _applyPilotWeaponEffectAdditiveToTraitLine(line,bonuses){
if(!bonuses||!bonuses.size)return{html:esc(line),changed:false,bonus:0};
const keys=_traitLineWeaponEffectKeys(line);
if(!keys.size)return{html:esc(line),changed:false,bonus:0};
let bonus=0;
keys.forEach(k=>{if(bonuses.has(k))bonus=Math.max(bonus,bonuses.get(k));});
if(!bonus)return{html:esc(line),changed:false,bonus:0};
let out='',last=0,changed=false,newVal=0;
const rePct=/(\d+)\s*%/g;
let m;
while((m=rePct.exec(line))!==null){
const base=parseInt(m[1],10);
newVal=base+bonus;
out+=esc(line.slice(last,m.index));
if(newVal!==base){changed=true;out+=`<span class="weapon-acc-boost">${newVal}%</span>`}
else out+=esc(m[0]);
last=m.index+m[0].length;
}
out+=esc(line.slice(last));
if(!changed)return{html:esc(line),changed:false,bonus:0};
const note=_pepWeaponEffectNoteLabel(bonus,keys);
return{html:out+`<div class="weapon-trait-pep-note">${esc(note)}</div>`,changed:true,bonus};
}
function _weaponTraitsHavePilotEffectBoost(traits,pepBonuses){
if(!pepBonuses||!pepBonuses.size)return false;
return(traits||[]).some(tr=>String(tr||'').split(/\r?\n/).some(l=>{const t=l.trim();return t&&_applyPilotWeaponEffectAdditiveToTraitLine(t,pepBonuses).changed;}));
}
function _normalizePilotWeaponTypeToken(t){
const tl=String(t||'').trim().toLowerCase().replace(/\s+weapons?\s*$/,'').trim();
if(tl.includes('physical')||tl.includes('物理'))return'physical';
if(tl.includes('beam')||tl.includes('光束')||tl.includes('鐳射')||tl.includes('ビーム'))return'beam';
if(tl.includes('special')||tl.includes('特殊'))return'special';
return tl;
}
function _pilotRangeTypeKeysMatchWeapon(wpnTypesStr,wpn){
const wpnKeySet=new Set(_dcWeaponAttributeKeys(wpn));
const types=String(wpnTypesStr||'').split(/\s+or\s+|,\s*|\s+and\s+|\s*\/\s*|\s*、\s*/);
return types.some(t=>{const key=_normalizePilotWeaponTypeToken(t);return key&&wpnKeySet.has(key)});
}
function _pilotExclusiveAbilityPilotPhrase(tx){
let m=String(tx||'').match(/when\s+piloting\s+(.+?)\s+and\s+vigor/i);
if(m)return m[1];
m=String(tx||'').match(/when\s+piloting\s+([^,\n]+?(?:\(EX\))?)/i);
if(m)return m[1].replace(/\s+and\s+.*$/,'').trim();
m=String(tx||'').match(/搭乘(?:單位為)?「([^」]+)」/);
if(m)return m[1];
m=String(tx||'').match(/「([^」]+)」\s*搭乗/);
if(m)return m[1];
m=String(tx||'').match(/搭乗ユニットが「([^」]+)」/);
if(m)return m[1];
return'';
}
function _pilotExclusiveAbilityTextMatchesUnit(ud,text,charData){
const tx=String(text||'');
if(!ud||!tx)return false;
if(_pilotTagAffinityTextMatchesUnit(ud,tx,charData))return true;
if(/when piloting character/i.test(tx)){
if(/grant \+\d+% ATK and DEF|grants \+\d+% ATK and DEF|same squad|in your squad/i.test(tx))return true;
}
if(!/when piloting|搭乘|搭乗/i.test(tx))return false;
const pilotPhrase=_pilotExclusiveAbilityPilotPhrase(tx);
if(!pilotPhrase||!_pilotTextTargetsUnit(ud,pilotPhrase))return false;
if(/max range|最大射程|武[裝装]的最大射程|武装の最大射程/i.test(tx))return true;
if(/increases ATK and DEF|increased ATK and DEF|gain increased ATK and DEF|increase ATK by|grant \+\d+% ATK and DEF|攻撃力と防御力|攻擊力與防禦力|攻擊力、防禦力提升|「攻擊力提升\d+%」、「防禦力提升\d+%」|賦予「攻擊力提升/i.test(tx))return true;
if(/improve\s+.+?\s+weapon effects by\s+\d+\s*%\s+additively/i.test(tx))return true;
if(/additively\s+increase\s+.+?\s+weapon effects by\s+\d+\s*%/i.test(tx))return true;
if(/武装効果値が\d+%加算/.test(tx)||/武裝效果.*?加算/.test(tx)||/武裝效果值增加\d+%/.test(tx))return true;
if(/increase\s+(?:own\s+)?(?:Melee|Ranged|Awaken|Defense|Reaction)\s+by\s+\d+\s*%|(?:格闘|射撃|覚醒|防御|反応)値が\d+%上昇|(?:格鬥|射擊|覺醒|防禦|反應)值提升\d+%/i.test(tx))return true;
if(/reduce\s+(?:own\s+)?(?:weapon\s+)?EN\s+consumption|消費ENが\d+%軽減|消耗EN減輕\d+%/i.test(tx))return true;
const cd=charData||S.pilotCondCharData||S.currentDetailData;
const pm=cd&&cd.pair_unit_stat_mod;
if(pm&&pm[String(ud.id||'')])return true;
return false;
}
function _pilotTagAffinityTextMatchesUnit(ud,text,charData){
if(!ud||!text||!_textImpliesPilotingTagAffinity(text))return false;
const cd=charData||S.pilotCondCharData;
if(!cd||!Array.isArray(cd.abilities))return false;
const norm=String(text||'').replace(/\s+/g,' ').trim().toLowerCase();
let hit=false;
(cd.abilities||[]).forEach(ab=>{
(ab.details||[]).forEach(d2=>{
if(typeof d2!=='object')return;
const dtx=String(d2.text||'').replace(/\s+/g,' ').trim().toLowerCase();
if(!dtx||!norm.includes(dtx.slice(0,Math.min(dtx.length,48))))return;
if(_unitTagsMatchAbilityDetail(d2,ud.tags))hit=true;
});
});
return hit;
}
function _collectPilotRangeModsFromSources(sources,ud){
const mods=[];
function push(reqUnit,wpnTypes,inc){
if(!_pilotTextTargetsUnit(ud,reqUnit))return;
mods.push({wpnTypes,inc:parseInt(inc,10)||0});
}
sources.forEach(txt=>{
const s=String(txt||'');
let m;
const reAndVigor=/when\s+piloting\s+(.+?)\s+and\s+vigor\s+is\s+\w+\s+or\s+higher,?\s*increase\s+max\s+range\s+of\s+(.+?)\s+by\s+(\d+)/gi;
while((m=reAndVigor.exec(s))!==null)push(m[1],m[2],m[3]);
const reIfVigor=/when\s+piloting\s+(.+?),\s*if\s+vigor\s+is\s+\w+\s+or\s+higher,?\s*(?:the\s+)?max\s+range\s+of\s+(.+?)\s+(?:weapons?\s+)?is\s+increased\s+by\s+(\d+)/gi;
while((m=reIfVigor.exec(s))!==null)push(m[1],m[2],m[3]);
const reSimple=/when\s+piloting\s+(.+?),[\s\S]{0,160}?increase\s+max\s+range\s+of\s+(.+?)\s+by\s+(\d+)/gi;
while((m=reSimple.exec(s))!==null){if(/\band\s+vigor\b/i.test(m[1]))continue;push(m[1],m[2],m[3])}
const reBeam=/when\s+piloting\s+(.+?),[\s\S]{0,160}?increase\s+beam\s+weapon\s+max\s+range\s+by\s+(\d+)/gi;
while((m=reBeam.exec(s))!==null)push(m[1],'beam',m[2]);
const reWeaponMaxInc=/when\s+piloting\s+(.+?)[,\s][\s\S]{0,220}?((?:beam|physical|special)(?:\s+or\s+(?:beam|physical|special))*\s+weapon)\s+max\s+range\s+is\s+increased\s+by\s+(\d+)/gi;
while((m=reWeaponMaxInc.exec(s))!==null)push(m[1],m[2],m[3]);
const reIsIncreased=/when\s+piloting\s+(.+?)[,\s][\s\S]{0,200}?max\s+range\s+of\s+(.+?)\s+(?:weapons?\s+)?is\s+increased\s+by\s+(\d+)/gi;
while((m=reIsIncreased.exec(s))!==null)push(m[1],m[2],m[3]);
const reJaUnit=/搭乗ユニットが「([^」]+)」[\s\S]{0,320}?((?:物理|ビーム|特殊)(?:[、及](?:物理|ビーム|特殊))*)武装の最大射程が(\d+)上昇/g;
while((m=reJaUnit.exec(s))!==null)push(m[1],m[2],m[3]);
const reJaPilot=/「([^」]+)」\s*搭乗時[\s\S]{0,120}?((?:物理|ビーム|特殊)(?:[、及](?:物理|ビーム|特殊))*)武装の最大射程が(\d+)上昇/g;
while((m=reJaPilot.exec(s))!==null)push(m[1],m[2],m[3]);
});
const seen=new Set();
return mods.filter(m=>{const k=m.wpnTypes+'|'+m.inc;if(seen.has(k))return false;seen.add(k);return true});
}
function syncPilotCondHighlights(){
const onUnit=S.currentDetailType==='unit'&&!!S.pilotConditionalPassiveActive&&!!S.currentDetailData;
const cid=(S.currentDetailType==='character'&&S.currentDetailData&&S.currentDetailData.pilot_cond_highlight_unit_id)?String(S.currentDetailData.pilot_cond_highlight_unit_id):'';
const onChar=!!cid;
document.querySelectorAll('.detail-rec-link-card[data-rec-char-id]').forEach(card=>{
card.classList.toggle('detail-rec-link-card--pilot-cond-target',onUnit);
});
if(onUnit){
const ud=S.currentDetailData;
const cd=S.pilotCondCharData;
document.querySelectorAll('#detailAbilitiesContainer .ability-detail-chunk').forEach(chunk=>{
const block=chunk.querySelector('.ability-detail-block');
if(!block)return;
const tx=String(block.textContent||'');
const hit=_pilotExclusiveAbilityTextMatchesUnit(ud,tx,cd);
block.classList.toggle('ability-detail-block--pilot-cond-highlight',hit);
});
return;
}
if(!onChar){
document.querySelectorAll('.ability-detail-block--pilot-cond-highlight').forEach(el=>el.classList.remove('ability-detail-block--pilot-cond-highlight'));
return;
}
const d=S.currentDetailData;
const ru=d&&d.recommend_unit;
const unitStub=ru&&String(ru.id)===cid?{id:ru.id,name:ru.name}:null;
document.querySelectorAll('#detailAbilitiesContainer .ability-detail-chunk').forEach(chunk=>{
const block=chunk.querySelector('.ability-detail-block');
if(!block)return;
const tx=String(block.textContent||'');
const hit=!!unitStub&&_pilotExclusiveAbilityTextMatchesUnit(unitStub,tx,d);
block.classList.toggle('ability-detail-block--pilot-cond-highlight',hit);
});
}
async function ensurePilotCondCharData(d,allowFetch){
if(!d||!d.has_pilot_cond_passive||!d.recommend_character||!d.recommend_character.id)return null;
const cid=String(d.recommend_character.id);
if(S.pilotCondCharData&&String(S.pilotCondCharData.id)===cid)return{data:S.pilotCondCharData,fresh:false};
if(!allowFetch)return null;
if(!S._pilotCondCharInflight)S._pilotCondCharInflight=new Map();
const inflight=S._pilotCondCharInflight.get(cid);
if(inflight)return inflight;
S._pilotCondCharFetchId=cid;
const p=(async()=>{
try{
const pay=await fetchDetailPayload('character',cid,{});
S.pilotCondCharData=pay;
return{data:pay,fresh:true};
}catch(_){return null}
finally{
S._pilotCondCharInflight.delete(cid);
if(S._pilotCondCharFetchId===cid)S._pilotCondCharFetchId=null;
}
})();
S._pilotCondCharInflight.set(cid,p);
return p;
}
function queuePilotCondCharPrefetch(d){
if(!d||!d.has_pilot_cond_passive||!d.recommend_character||!d.recommend_character.id)return;
const uid=String(d.id||'');
if(S._pilotCondPrefetchUnitId===uid)return;
S._pilotCondPrefetchUnitId=uid;
void ensurePilotCondCharData(d,true).then(r=>{
if(!r||!r.data)return;
if(S.currentDetailType==='unit'&&S.currentDetailData&&String(S.currentDetailData.id)===uid){
if(S.pilotConditionalPassiveActive)_detailInitPilotCondStackCount(S.currentDetailData);
updateDetailDynamicSections('unit');
syncPilotCondHighlights();
}
}).catch(()=>{});
}
function _detailInitUnitCondControls(ud){
if(!ud)return;
S.unitCondStackCount=0;
S.unitHpAtkTierIndex=0;
const hp=ud.unit_hp_atk_tiers;
if(hp&&hp.tiers&&hp.tiers.length)S.unitHpAtkTierIndex=hp.tiers.length-1;
const cc=ud.unit_combat_count_atk;
if(cc&&cc.max_stacks)S.unitCondStackCount=cc.max_stacks|0;
}
