function _detailPilotStackSliderInfo(ud){
if(!S.pilotConditionalPassiveActive||!ud||!S.pilotCondCharData)return null;
const cd=S.pilotCondCharData;
const b=_scFindSquadConditionBinding(cd,ud);
if(!b||!(b.kind==='stack_atk'||b.kind==='dual_stack_atk'))return null;
if(b.pilotGroups&&b.pilotGroups.length&&!_dcAbilityCondContextMeetsGroups(ud,cd,b.pilotGroups))return null;
const per=Math.max(1,b.perUnit|0),maxPct=b.max|0;
const maxStacks=Math.max(1,Math.min(5,Math.ceil(maxPct/per)));
return{per,maxPct,maxStacks};
}
function _detailInitPilotCondStackCount(ud){
const info=_detailPilotStackSliderInfo(ud);
if(!info){S.pilotCondStackCount=0;return}
if(!(S.pilotCondStackCount|0))S.pilotCondStackCount=info.maxStacks;
else S.pilotCondStackCount=Math.max(1,Math.min(info.maxStacks,S.pilotCondStackCount|0));
}
function setPilotCondStackCount(n){
const d=S.currentDetailData;
const info=d&&S.currentDetailType==='unit'?_detailPilotStackSliderInfo(d):null;
if(!info)return;
S.pilotCondStackCount=Math.max(1,Math.min(info.maxStacks,Number(n)||0));
invalidateDetailRankingCachesForPerspectiveChange();
updateDetailDynamicSections('unit');
}
function _detailPilotStackSliderHtml(ud){
if(!S.pilotConditionalPassiveActive||!ud||!S.pilotCondCharData)return'';
const stackInfo=_detailPilotStackSliderInfo(ud);
if(!stackInfo)return'';
const cur=Math.max(1,Math.min(stackInfo.maxStacks,S.pilotCondStackCount|0||stackInfo.maxStacks));
const pct=Math.min(stackInfo.maxPct,stackInfo.per*cur);
const stackLab=t('pilot_exclusive_stack_label')||'Pilot exclusive stack level';
const enterCls=S._pilotStackSliderAnimate?' detail-pilot-stack-row--enter':'';
return`<div class="detail-pilot-stack-row is-open${enterCls}" onclick="event.stopPropagation()"><input type="range" class="detail-pilot-stack-slider" min="1" max="${stackInfo.maxStacks}" step="1" value="${cur}" aria-valuemin="1" aria-valuemax="${stackInfo.maxStacks}" aria-valuenow="${cur}" aria-label="${escAttr(stackLab)}" oninput="setPilotCondStackCount(this.value)"><span class="detail-pilot-stack-val">+${pct}%</span></div>`;
}
function _detailPilotStatBonusPcts(ud){
const z={atk:0,def:0};
if(!S.pilotConditionalPassiveActive||!ud||!S.pilotCondCharData)return z;
const cd=S.pilotCondCharData;
const pm=cd.pair_unit_stat_mod;
if(pm&&pm[String(ud.id||'')]){
const row=pm[String(ud.id)];
if(row.atk_pct)z.atk+=row.atk_pct|0;
if(row.def_pct)z.def+=row.def_pct|0;
}
const b=_scFindSquadConditionBinding(cd,ud);
if(!b)return z;
if(b.pilotGroups&&b.pilotGroups.length&&!_dcAbilityCondContextMeetsGroups(ud,cd,b.pilotGroups))return z;
if(b.kind==='flat_ad'&&!b.flatPerUnit){
if(b.recvGroup&&!_dcSquadRecvGroupMet(ud,cd,b.recvGroup))return z;
z.atk+=b.flatPct|0;z.def+=b.flatPct|0;
}else if(b.kind==='flat_atk'){
if(b.recvGroup&&!_dcSquadRecvGroupMet(ud,cd,b.recvGroup))return z;
z.atk+=b.flatPct|0;
}else if(b.kind==='dual_flat_ad'){
(b.parts||[]).forEach(p=>{
if(p.recvGroup&&!_dcSquadRecvGroupMet(ud,cd,p.recvGroup))return;
const v=p.flatPct|0;
z.atk+=v;z.def+=v;
});
}else if(b.kind==='stack_atk'||b.kind==='dual_stack_atk'){
const info=_detailPilotStackSliderInfo(ud);
if(!info)return z;
const n=Math.max(1,Math.min(info.maxStacks,S.pilotCondStackCount|0||info.maxStacks));
z.atk+=Math.min(info.maxPct,info.per*n);
}
return z;
}
function _detailApplyPilotStatBonusRows(sr,ud){
const p=_detailPilotStatBonusPcts(ud);
if(!p.atk&&!p.def)return sr;
const F=Math.floor;
return sr.map(s=>{
if(s.name!=='Attack'&&s.name!=='Defense')return s;
const pct=s.name==='Attack'?p.atk:p.def;
if(!pct)return s;
const base=s.base|0;
const passivePct=(s.passive_pct|0)+pct;
const tot=F(base*(100+passivePct)/100);
return Object.assign({},s,{total:tot,bonus:Math.max(0,tot-base),passive_pct:passivePct,pilot_bonus:pct});
});
}
function _detailPilotRangeBonusForWeapon(wpn,ud){
if(!S.pilotConditionalPassiveActive||!ud||!S.pilotCondCharData)return 0;
const cd=S.pilotCondCharData;
const sources=[];
(cd.abilities||[]).forEach(ab=>{
const r=_dcResolveCharAbilityForMode(ab);
if(!r)return;
(r.details||[]).forEach(d=>{if(typeof d==='object'&&d.text)sources.push(d.text);else if(typeof d==='string')sources.push(d)});
});
let bonus=0;
_collectPilotRangeModsFromSources(sources,ud).forEach(mod=>{
if(_pilotRangeTypeKeysMatchWeapon(mod.wpnTypes,wpn))bonus+=mod.inc;
});
return bonus;
}
function togglePilotConditionalPassive(c){
S.pilotConditionalPassiveActive=!!c;
if(!c){S.pilotCondStackCount=0;S._pilotStackSliderAnimate=false}
else S._pilotStackSliderAnimate=true;
invalidateDetailRankingCachesForPerspectiveChange();
const d=S.currentDetailData;
const afterRender=()=>{
if(S._pilotStackSliderAnimate){
requestAnimationFrame(()=>{
document.querySelectorAll('.detail-pilot-stack-row--enter').forEach(el=>{
el.addEventListener('animationend',()=>{el.classList.remove('detail-pilot-stack-row--enter');S._pilotStackSliderAnimate=false},{once:true});
});
});
}
syncPilotCondHighlights();
};
const finish=()=>{
if(c&&d&&S.pilotCondCharData)_detailInitPilotCondStackCount(d);
updateDetailDynamicSections(S.currentDetailType);
afterRender();
};
if(c&&d&&d.has_pilot_cond_passive&&d.recommend_character&&d.recommend_character.id){
void ensurePilotCondCharData(d,true).then(()=>finish()).catch(()=>finish());
return;
}
finish();
}
