const _stageHazardTapeAnims=new WeakMap();const STAGE_HAZARD_TAPE_STEP=28.28;const STAGE_HAZARD_TAPE_MS=1250;
function stopStageHazardTapeAnim(layer){const id=_stageHazardTapeAnims.get(layer);if(id!=null)cancelAnimationFrame(id);_stageHazardTapeAnims.delete(layer)}
function startStageHazardTapeAnim(layer){stopStageHazardTapeAnim(layer);let offset=0,lastTs=null;const step=ts=>{if(!layer.isConnected)return;lastTs=lastTs==null?ts:lastTs;const dt=ts-lastTs;lastTs=ts;offset-=(STAGE_HAZARD_TAPE_STEP/STAGE_HAZARD_TAPE_MS)*dt;if(offset<=-STAGE_HAZARD_TAPE_STEP)offset+=STAGE_HAZARD_TAPE_STEP;layer.style.webkitTransform='translate3d('+offset+'px,0,0)';layer.style.transform='translate3d('+offset+'px,0,0)';_stageHazardTapeAnims.set(layer,requestAnimationFrame(step))};_stageHazardTapeAnims.set(layer,requestAnimationFrame(step))}
