  const guestCls=opts.guestCls!=null?opts.guestCls:(u.is_guest_ally?'ally-guest':'');
  const friendlyCls=opts.friendlyCls!=null?opts.friendlyCls:(u.is_friendly_force?'friendly-force':'');
