function renderAbilIcon(ab,srcRow){const base=srcRow||ab;const hintUrl=(ab&&ab.strategy_hint_icon)||(base&&base.strategy_hint_icon);const hintSrc=hintUrl?imgUrlWebp(imgUrlPreferCdn(hintUrl)):'';const hintHtml=hintSrc?`<img class="strategy-hint-badge" src="${hintSrc}" alt="" loading="lazy" onerror="this.style.display='none'">`:'';if(!ab||!ab.icon)return hintHtml+'<div class="ability-icon-stack"><div class="ability-icon-placeholder">★</div></div>';const rawIcon=String(ab.icon);const abiSrc=/^https?:\/\//i.test(rawIcon)?imgUrlWebp(rawIcon):imgUrlWebp(imgUrlPreferCdn(rawIcon));const isEx=!!(ab.frame_overlay&&ab.is_ex);if(isEx){const fbRaw=String(ab.frame_base||ABILITY_EX_FRAME_BASE||'');const fbSrc=/^https?:\/\//i.test(fbRaw)?imgUrlWebp(fbRaw):imgUrlWebp(imgUrlPreferCdn(fbRaw));const fo=String(ab.frame_overlay);const foSrc=/^https?:\/\//i.test(fo)?imgUrlWebp(fo):imgUrlWebp(imgUrlPreferCdn(fo));const inner=`<div class="ability-icon-inner">${fbSrc?`<img class="ability-icon-base" src="${fbSrc}" alt="" loading="lazy" decoding="async" onerror="gameImageUrlFallback(this)">`:''}<img class="ability-icon" src="${abiSrc}" alt="" loading="lazy" decoding="async" onerror="abilityIconImgOnError(this);return false;"></div><img class="ability-frame-overlay" src="${foSrc}" alt="" loading="lazy" decoding="async" onerror="this.style.display='none'">`;return hintHtml+`<div class="ability-icon-stack ability-icon-stack--ex">${inner}</div>`}return hintHtml+`<div class="ability-icon-stack"><img class="ability-icon" src="${abiSrc}" alt="" loading="lazy" decoding="async" onerror="abilityIconImgOnError(this);return false;"></div>`}
function isUnknownAbilityName(n){const s=String(n||'').trim();return s==='Unknown'||/^Unknown\s*\(/i.test(s)}
function abilityConditionLabel(label){const lc=(S.lang||'EN').toUpperCase();const k=String(label||'').trim();if(k==='Condition 1')return(lc==='TW'||lc==='HK')?'[條件 1]':(lc==='JA'||lc==='JP')?'[条件 1]':'[Condition 1]';if(k==='Condition 2')return(lc==='TW'||lc==='HK')?'[條件 2]':(lc==='JA'||lc==='JP')?'[条件 2]':'[Condition 2]';if(k==='Boost Target')return(lc==='TW'||lc==='HK')?'[加成目標]':(lc==='JA'||lc==='JP')?'[強化対象]':'[Boost Target]';return k?`[${k}]`:''}
