function abilityConditionTagKey(detail){const valid=abilityUiConditionGroupsSorted(detail);if(valid.length)return valid.map(g=>(Array.isArray(g&&g.conditions)?g.conditions:[]).map(_abilityConditionTagSig).join(',')).join('||');return abilityUiFallbackConditionsSorted(detail).map(_abilityConditionTagSig).join(',')}
function normalizeAbilityDetailObj(d){if(typeof d==='string')return{text:d};if(d&&typeof d==='object')return d;return null}
function mergeConsecutiveAbilityDetails(details){const arr=Array.isArray(details)?details:[];const out=[];for(let i=0;i<arr.length;i++){const cur=normalizeAbilityDetailObj(arr[i]);if(!cur)continue;const key=abilityConditionTagKey(cur);let text=String(cur.text||'').trim();while(i+1<arr.length){const nxt=normalizeAbilityDetailObj(arr[i+1]);if(!nxt)break;const ntext=String(nxt.text||'').trim();if(!ntext)break;if(!key||abilityConditionTagKey(nxt)!==key)break;if(/^\s*When\s/i.test(ntext))break;text=text?(text+' '+ntext):ntext;i++}out.push({...cur,text})}return out}
