function renderAbilityDetailChunks(d){let obj;if(typeof d==='string')obj={text:d};else if(d&&typeof d==='object')obj=d;else return'';const raw0=String(obj.text||'').trim();const raw=normalizeAbilityDetailTextForSplit(raw0);const cond=renderAbilityConditionGroups(obj);const hasCond=!!cond;const validCgRaw=abilityValidConditionGroupsSorted(obj);const validCgUi=abilityUiConditionGroupsSorted(obj);function wrapBlock(inner){return`<div class="ability-detail-chunk"><div class="ability-detail-block"><div class="ability-detail-block-inner">${inner}</div></div></div>`}if(!raw)return hasCond?wrapBlock(cond):'';let groups=splitAbilityTextIntoBlocks(raw);if(validCgRaw.length>=2&&groups.length===1){const g0=groups[0]||'';const sub=g0.split(/\.\s+(?=When\s+Vigor\b|\b(?:Increase|Increases)\b)/i).map(x=>x.trim()).filter(x=>x.length);if(sub.length>=2&&sub.length===validCgRaw.length)groups=sub}const useParallel=validCgUi.length>=2&&validCgUi.length===groups.length;if(useParallel){const parts=[];let buf=null;for(let i=0;i<groups.length;i++){const g=groups[i]||'';const gKey=abilityConditionTagKey({condition_groups:[validCgUi[i]]});if(buf&&buf.key===gKey){buf.texts.push(g);continue}if(buf)parts.push(buf);buf={key:gKey,texts:g?[g]:[],condIdx:i}}if(buf)parts.push(buf);return parts.map(part=>{const textHtml=part.texts.filter(Boolean).map(g=>`<div class="ability-detail-text">${esc(g)}</div>`).join('');const condHtml=renderAbilityConditionGroupAt(obj,part.condIdx);return wrapBlock(textHtml+condHtml)}).join('')}const condIdx=blockIndexForConditions(groups,hasCond);return groups.map((g,i)=>{const textHtml=g?`<div class="ability-detail-text">${esc(g)}</div>`:'';const condHtml=i===condIdx?cond:'';const tagFirst=!!condHtml&&_abilityTextBlockHasTagGateProse(g);return wrapBlock((tagFirst?condHtml:'')+textHtml+(tagFirst?'':condHtml))}).join('')}
function renderAbilsDynamic(a,title,isSsp,isSp,entityType){if(!a||!a.length)return'';const et=entityType||S.currentDetailType;const canClick=(et==='character'||et==='unit');let rows=(a||[]).filter(ba=>!(ba.ssp_only&&!isSsp));if(et==='character'&&!isSp)rows=rows.filter(ba=>!(ba.sp_replacement&&isUnknownAbilityName(ba.name)));if(et==='unit'&&!isSsp)rows=rows.filter(ba=>!(ba.ssp_replacement&&isUnknownAbilityName(ba.name)));if(!rows.length)return'';return`<div class="detail-section"><div class="section-title">${title||t('sec_abilities')}</div><div class="ability-list">${rows.map(ba=>{let ab=ba,ssp=false,sp=false;if(isSsp&&ba.ssp_only){ab=ba;ssp=true}else if(isSsp&&ba.ssp_replacement){ab=ba.ssp_replacement;ssp=true}else if(isSp&&ba.sp_replacement){ab=ba.sp_replacement;sp=true}const dn=ab.display_name||ab.name;const clickAttr=canClick?` onclick="event.stopPropagation();if(event.target&&event.target.closest&&event.target.closest('.ability-conditions'))return;openAbilityModal('${escJs(ab.name)}','${et}','${escJs(dn)}')" title="${t('view_owners')||'View who has this'}"`:'';const clickCls=canClick?' ability-item-clickable':'';const ds=Array.isArray(ab.details)?ab.details:[];const condCtrl=(et==='unit'&&S.currentDetailData)?_detailAbilityCondControlHtml(ab,S.currentDetailData):'';return`<div class="ability-item${clickCls}"${ab.id!=null?` data-ability-id="${escAttr(String(ab.id))}"`:''}${clickAttr}><div class="ability-icon-wrap">${renderAbilIcon(ab,ba)}</div><div class="ability-info"><div class="ability-name" style="display:flex;align-items:center;gap:6px;">${sp?'<img src="'+imgUrl('/static/images/UI/UI_Common_Icon_Sp.webp')+'" style="height:20px;object-fit:contain;" alt="SP">':''}${ssp?'<img src="'+imgUrl('/static/images/UI/UI_Common_Icon_Ssp.webp')+'" style="height:20px;object-fit:contain;" alt="SSP">':''}${esc(dn)}</div>${renderAbilityDetailsHtml(ds)}${condCtrl}</div></div>`}).join('')}</div></div>`}
