  ec.forEach(c=>{let x=t2?c.x+sx:c.x,y=t2?c.y+sy:c.y;if(x<mnx)mnx=x;if(x>mxx)mxx=x;if(y<mny)mny=y;if(y>mxy)mxy=y});
