function resetCompare(){
S.compareList=[];S.compareData=[];S.cmpLbByUnit={};
updateCompareUI();closeCompareModal()
}

function openCompPicker(){
const pickerOverlay=document.getElementById('cmpPickerOverlay');
pickerOverlay.classList.add('active');
document.getElementById('cmpPickerSearch').value='';
document.getElementById('cmpPickerSearch').placeholder=S.compareType==='character'?t('cmp_search_char'):t('cmp_search_unit');
document.getElementById('cmpPickerBody').innerHTML=`<div style="padding:24px;text-align:center;color:var(--text-muted);font-size:15px;">${t('cmp_type_to_search')}</div>`;
document.getElementById('cmpPickerSearch').focus();
}

function closeCompPicker(){document.getElementById('cmpPickerOverlay').classList.remove('active')}

function filterCompPicker(){clearTimeout(S._cmpPickerDebounce);S._cmpPickerDebounce=setTimeout(()=>searchCompPicker(),280)}

async function searchCompPicker(){
const q=document.getElementById('cmpPickerSearch').value.trim();
const body=document.getElementById('cmpPickerBody');
if(!q){body.innerHTML=`<div style="padding:24px;text-align:center;color:var(--text-muted);font-size:15px;">${t('cmp_type_to_search')}</div>`;return}
body.innerHTML='<div class="loading-overlay"><div class="spinner"></div></div>';
try{
const base=S.compareType==='character'?'/api/characters':'/api/units';
const r=await fetch(`${base}?lang=${S.lang}&page=1&per_page=100&sort=rarity&dir=desc&q=${encodeURIComponent(q)}`);
const d=await r.json();
const items=d.rows||[];
if(!items.length){body.innerHTML='<div style="padding:20px;text-align:center;color:var(--text-muted)">No results</div>';return}
const existing=new Set(S.compareList.map(c=>c.id));
body.innerHTML=items.slice(0,100).map(r=>{
const already=existing.has(r.id);
const badges=`<span class="cmp-picker-badge-text">${esc(r.rarity||'')}</span><span class="cmp-picker-badge-text">${esc(r.role||'')}</span>`;
return`<div class="cmp-picker-item${already?' already':''}" onclick="pickCompItem('${r.id}','${escJs(r.name)}','')">
<div><div class="cmp-picker-item-name">${esc(r.name)}</div><div class="cmp-picker-item-badges">${badges}</div></div></div>`
}).join('')
}catch(e){body.innerHTML='<div class="empty-state"><div class="empty-state-text">Failed to load</div></div>'}
}

async function pickCompItem(id,name,thum){
if(S.compareList.length>=3)return;
if(S.compareList.some(c=>c.id===id))return;
S.compareList.push({id,type:S.compareType,name,thum});
if(S.compareType==='unit'&&S.cmpLbByUnit[id]===undefined)S.cmpLbByUnit[id]=3;
updateCompareUI();
closeCompPicker();
const url=S.compareType==='character'?`/api/character/${id}?lang=${S.lang}`:`/api/unit/${id}?lang=${S.lang}`;
try{
const r=await fetch(url);const d=await r.json();
S.compareData.push(d);
renderCompareContent()
}catch(e){}
}

const DC_ATK_TYPE_LABEL_MAP={
Ranged:'Ranged',Melee:'Melee',Awaken:'Awaken',Attack:'Melee',
ranged:'Ranged',melee:'Melee',awaken:'Awaken',attack:'Melee',
'射擊':'Ranged','格鬥':'Melee','覺醒':'Awaken',
'射撃':'Ranged','格闘':'Melee','覚醒':'Awaken'
};
/** Same keys as app.py ATTACK_ATTR_TYPES — used when attack_types is empty (manual weapons / edge API). */
const DC_ATTACK_ATTR_TO_KEYS={'1':['Ranged'],'2':['Melee'],'3':['Awaken'],'4':['Ranged','Melee'],'5':['Ranged','Awaken'],'6':['Melee','Awaken'],'7':['Ranged','Melee','Awaken']};
function _dcWeaponAtkStatKeys(wpn){
let atkTypes=(wpn.attack_types||[]).map(at=>{
if(typeof at==='string')return DC_ATK_TYPE_LABEL_MAP[at.trim()]||null;
const key=String(at&&at.key!=null?at.key:'').trim().toLowerCase();
if(key==='ranged'||key==='melee'||key==='awaken')return key.charAt(0).toUpperCase()+key.slice(1);
const lbl=(at&&(at.label||at.name))||'';
return DC_ATK_TYPE_LABEL_MAP[lbl]||null;
}).filter(Boolean);
if(!atkTypes.length){
const aa=String(wpn.attack_attribute||wpn.attackAttribute||'').trim();
const keys=DC_ATTACK_ATTR_TO_KEYS[aa];
if(keys&&keys.length)atkTypes=keys.slice();
}
if(!atkTypes.length)atkTypes.push('Ranged');
return atkTypes;
}
const DC_MP={medium:{dmgBonus:0,critMult:0.10},high:{dmgBonus:0.10,critMult:0.20},max:{dmgBonus:0.20,critMult:0.20},super:{dmgBonus:0.30,critMult:0.30}};
function _dcNormMpLevel(lv){
const x=String(lv!=null?lv:'').trim();
if(x==='supercharged')return'super';
if(x==='normal')return'medium';
if(DC_MP[x])return x;
return'medium';
}
function _dcMpProfile(lv){return DC_MP[_dcNormMpLevel(lv)]||DC_MP.medium;}
function _dcVigorLabel(lv){
const k=_dcNormMpLevel(lv);
if(k==='high')return t('dc_vigor_high');
if(k==='max')return t('dc_vigor_max');
if(k==='super')return t('dc_vigor_super');
return t('dc_vigor_medium');
}
function _dcApplyDcVigorButtonLabels(){
['Medium','High','Max','Super'].forEach((suf,i)=>{
const el=document.getElementById('dcMpBtn'+suf);
if(el){const key=i===0?'dc_vigor_medium':i===1?'dc_vigor_high':i===2?'dc_vigor_max':'dc_vigor_super';el.textContent=t(key)}
});
}
const DC_ATK_SLOT_COUNT=3;
const DC_SHINN_ASUKA_CHAR_IDS=new Set(['1330000101','1330000102','1330000103','1330000104','1330000105']);
function _dcIsZhCalcLang(){const lc=(S.lang||'EN').toUpperCase();return lc==='TW'||lc==='HK';}
function _dcIsJaCalcLang(){return (S.lang||'EN').toUpperCase()==='JA';}
function _dcTwZhWeaponTypesToEn(zhBlob){const map={物理:'physical',光束:'beam',特殊:'special'};return String(zhBlob||'').split(/、/).map(s=>map[s.trim()]||'').filter(Boolean).join(' or ');}
function _dcTwBattleSpiritToVigorKey(spirit){const t=String(spirit||'').trim();if(t==='超一擊')return'super';if(t==='超強勢')return'max';if(t==='強勢')return'high';return'medium';}
function _dcIsShinnAsukaCharacter(cd){if(!cd)return false;const id=String(cd.id!=null?cd.id:'').trim();if(DC_SHINN_ASUKA_CHAR_IDS.has(id))return true;const mid=cd.main_character_id!=null?String(cd.main_character_id).trim():'';if(mid&&DC_SHINN_ASUKA_CHAR_IDS.has(mid))return true;const n=(cd.name||'').toLowerCase();return n.includes('shinn')&&n.includes('asuka')}
function _dcCharAbilitiesTextBlob(cd){
if(!cd||!cd.abilities)return'';
const parts=[];
cd.abilities.forEach(ab=>{
parts.push(ab.name||'',ab.display_name||'');
(ab.details||[]).forEach(d=>{parts.push(typeof d==='string'?d:(d&&d.text)||'')});
});
return parts.join('\n').toLowerCase();
}
function _dcFindSuperchargedExAbilityDetail(cd){
if(!cd||!Array.isArray(cd.abilities))return null;
for(const ab of cd.abilities){
if(!ab||!ab.is_ex)continue;
const r=_dcResolveCharAbilityForMode(ab);
if(!r)continue;
for(const ln of r.details||[]){
if(typeof ln!=='object'||!ln)continue;
const tx=String(ln.text||'');
if(/supercharged\s+ex|超一[擊撃]EX/i.test(tx)&&_dcSliceSuperchargedExTierSections(tx).length>=2)return ln;
}
}
return null;
}
function _dcSuperchargedExConditionGroups(cd){
const det=_dcFindSuperchargedExAbilityDetail(cd);
if(!det)return[];
const groups=det.condition_groups||[];
if(groups.length)return groups;
if(Array.isArray(det.conditions)&&det.conditions.length)return[{label:'Condition 1',conditions:det.conditions}];
return[];
}
function _dcUnitMeetsSuperchargedExGate(cd,ud){
if(!cd||!ud||cd._manual||ud._manual)return false;
if(_dcIsShinnAsukaCharacter(cd))return true;
const groups=_dcSuperchargedExConditionGroups(cd);
if(!groups.length)return true;
return _dcUnitMeetsAbilityConditionGroups(ud,groups);
}
function _dcSuperchargedExStatsEligible(cd,ud,mp,charCpOn){
if(!charCpOn||!cd||!ud||cd._manual||ud._manual)return false;
if(!cd.ex_supercharged_tiers||cd.ex_supercharged_tiers.length<2)return false;
if(_dcNormMpLevel(mp)!=='super')return false;
return _dcUnitMeetsSuperchargedExGate(cd,ud);
}
function _dcShouldAutoSuperchargedVigorOnCharCp(cd){
if(!cd)return false;
if(_dcIsShinnAsukaCharacter(cd))return true;
const blob=_dcCharAbilitiesTextBlob(cd);
let abRaw='';
(cd.abilities||[]).forEach(ab=>{(ab.details||[]).forEach(d=>{abRaw+=(typeof d==='string'?d:(d&&d.text)||'')+'\n'})});
if(blob.includes('supercharged')&&blob.includes('shinn'))return true;
if(abRaw.includes('超一擊')&&abRaw.includes('飛鳥'))return true;
return false;
}
function _dcAbilityLineIsSuperchargedExSection(txt){
return/(?:Supercharged\s+EX|超一[擊撃]EX)\s*[12]\b/i.test(String(txt||''));
}
function _dcSliceSuperchargedExTierSections(blob){
if(!blob)return[];
const s=String(blob);
const rx=/(?:Supercharged\s+EX|超一[擊撃]EX)\s*([12])\b/gi;
const matches=[...s.matchAll(rx)];
if(matches.length<2)return[];
const out=[];
for(let i=0;i<matches.length;i++){
const m=matches[i];
const tier=parseInt(m[1],10);
const start=m.index|0;
const end=matches[i+1]?matches[i+1].index|0:s.length;
out.push({tier,chunk:s.slice(start,end)});
}
return out;
}
function _dcPilotExAbilityBlobs(cd){
const out=[];
if(!cd||!Array.isArray(cd.abilities))return out;
cd.abilities.forEach(ab=>{
if(!ab||!ab.is_ex)return;
const r=_dcResolveCharAbilityForMode(ab);
if(!r)return;
let blob=String(r.name||'')+'\n';
(r.details||[]).forEach(d=>{blob+=String((d&&d.text)||'')+'\n'});
out.push(blob);
});
return out;
}
function _dcSuperchargedExTierHasGuaranteedCrit(cd,tierNum){
for(const blob of _dcPilotExAbilityBlobs(cd)){
for(const sl of _dcSliceSuperchargedExTierSections(blob)){
if(sl.tier===tierNum&&DC_GUARANTEED_CRIT_RE.test(sl.chunk))return true;
}
}
return false;
}
function _dcSyncSuperchargedExTierForVigor(forceDefault){
const cd=S.dc.atkCharData;
if(!cd||!S.dc.charCondPassive){S.dc.dcSuperchargedExTier=0;S.dc._dcSuperchargedExManual=false;return;}
const tiers=cd.ex_supercharged_tiers;
if(!tiers||tiers.length<2){S.dc.dcSuperchargedExTier=0;S.dc._dcSuperchargedExManual=false;return;}
if(_dcNormMpLevel(S.dc.mpLevel)!=='super')return;
if(forceDefault||!S.dc._dcSuperchargedExManual)S.dc.dcSuperchargedExTier=tiers.length-1;
}
function _dcAutoEnableMaxDamageSkills(){
const cd=S.dc.atkCharData;
if(!cd||cd._manual)return;
const skills=_dcPilotSkillsVisibleForDc(cd)||[];
if(!skills.length)return;
S.dc._activeSkills=S.dc._activeSkills||{};
const byBase=new Map();
skills.forEach(sk=>{
const rsk=_dcResolveSkillForDcMode(sk);
const fullNm=(rsk.name||sk.name||'').trim();
const base=fullNm.replace(/\s*LV\s*\d+\s*$/i,'').trim().toLowerCase();
const lvM=fullNm.match(/\bLV\s*(\d+)\b/i);
const lv=lvM?parseInt(lvM[1],10):0;
const desc=[...(rsk.details||[]).map(d=>typeof d==='string'?d:(d&&d.text)||''),rsk.desc||'',rsk.sp_desc||''].join(' ');
if(!/(?:damage\s+dealt|造成的損傷|傷害)/i.test(desc))return;
const prev=byBase.get(base);
if(!prev||lv>prev.lv)byBase.set(base,{id:String(sk.id),lv});
});
byBase.forEach(({id})=>{S.dc._activeSkills[id]=true});
}
function _dcMsyUnitStatMode(ud){
if(!ud)return'normal';
// Ultimate (ULT) kits have no SP/SSP path — always base stats.
if(ud.is_ultimate)return'normal';
if(ud.has_sp===false)return'normal';
if(typeof _tbUnitAllowsSpSsp==='function'&&!_tbUnitAllowsSpSsp(ud))return'normal';
const ri=parseInt(String(ud.rarity_id!=null?ud.rarity_id:(ud.rarity||'5')),10);
// BSP: SSR and lower (and UR when SP exists) use SSP unit stats / SSP weapons.
if(!Number.isNaN(ri)&&(ri<=4||ri>=5))return'ssp';
return'normal';
}
function _dcMsySkillRelevantForSim(desc,skId,skName,wpnBaseCrit){
const text=String(desc||'');
if(/(?:damage\s+dealt|造成的損傷|傷害|ダメージ)/i.test(text))return true;
const add=_dcParseSkillDescAtkPct(text,{id:skId,name:skName||''});
if(add.Ranged||add.Melee||add.Awaken)return true;
if(/^200170[1-5]01$/.test(String(skId||'')))return true;
if(/awaken\s+boost|覺醒值增幅|覚醒ブースト/i.test(String(skName||'')))return true;
/* Always apply Boost Critical / crit-rate skills for max-damage BSP (not only when weapon crit is 0). */
if(/critical\s*rate|暴擊率|暴击率|爆擊率|クリティカル率|boost\s+critical/i.test(text)||/boost\s+critical/i.test(String(skName||'')))return true;
return false;
}
function _dcMsyAutoEnableSkills(ud,cd){
if(!cd||cd._manual)return;
const skills=_dcPilotSkillsVisibleForDc(cd)||[];
if(!skills.length)return;
S.dc._activeSkills=S.dc._activeSkills||{};
const byBase=new Map();
skills.forEach(sk=>{
const rsk=_dcResolveSkillForDcMode(sk);
const fullNm=(rsk.name||sk.name||'').trim();
const base=fullNm.replace(/\s*LV\s*\d+\s*$/i,'').trim().toLowerCase();
const lvM=fullNm.match(/\bLV\s*(\d+)\b/i);
const lv=lvM?parseInt(lvM[1],10):0;
const desc=[...(rsk.details||[]).map(d=>typeof d==='string'?d:(d&&d.text)||''),rsk.desc||'',rsk.sp_desc||''].join(' ');
if(!_dcMsySkillRelevantForSim(desc,sk.id,fullNm,0))return;
const prev=byBase.get(base);
if(!prev||lv>prev.lv)byBase.set(base,{id:String(sk.id),lv});
});
byBase.forEach(({id})=>{S.dc._activeSkills[id]=true});
}
function _dcMsySkillCritRate(slot,cd){
let crit=0;
if(!cd||!slot._activeSkills)return 0;
const skills=_dcPilotSkillsVisibleForDc(cd)||[];
const saveMode=S.dc.charStatMode,saveAS=S.dc._activeSkills;
try{
S.dc.charStatMode=slot.charStatMode||'normal';
S.dc._activeSkills={...slot._activeSkills};
skills.forEach(sk=>{
if(!slot._activeSkills[sk.id])return;
const rsk=_dcResolveSkillForDcMode(sk);
const desc=[...(rsk.details||[]).map(d=>typeof d==='string'?d:(d&&d.text)||''),rsk.desc||'',rsk.sp_desc||''].join(' ');
let m=desc.match(/Increases?\s+(?:own\s+)?critical\s*rate\s+by\s+(\d+)\s*%/i);
if(m)crit=Math.max(crit,parseInt(m[1],10)||0);
m=desc.match(/Increase\s+critical\s*rate\s+by\s+(\d+)\s*%/i);
if(m)crit=Math.max(crit,parseInt(m[1],10)||0);
m=desc.match(/自身(?:的)?(?:暴擊|暴击|爆擊)率提升(\d+)%/);
if(m)crit=Math.max(crit,parseInt(m[1],10)||0);
m=desc.match(/自身のクリティカル率が(\d+)%上昇/);
if(m)crit=Math.max(crit,parseInt(m[1],10)||0);
m=desc.match(/クリティカル(?:発生)?率.{0,8}?(\d+)\s*[%％]/);
if(m)crit=Math.max(crit,parseInt(m[1],10)||0);
});
}finally{S.dc.charStatMode=saveMode;S.dc._activeSkills=saveAS}
return crit;
}
function _dcMsyAffinityWeaponCrit(ud,cd){
if(!S.pilotConditionalPassiveActive||!ud||!cd)return 0;
let out=0;
(cd.abilities||[]).forEach(ab=>{
(ab.details||[]).forEach(d2=>{
if(typeof d2!=='object')return;
const tx=String(d2.text||'');
if(!_textImpliesPilotingTagAffinity(tx))return;
if(!_unitTagsMatchAbilityDetail(d2,ud.tags))return;
const row=_extractPilotWeaponStatPctFromText(tx);
out=Math.max(out,row.crit|0);
});
});
return out;
}
