if(!m&&zh)m=txt.match(/自身剩餘EN越(?:高|低)，武裝POWER越為提升（最高提升(\d+)%）/);
if(!m&&isJa)m=txt.match(/自身の残ENが(?:多い|少ない)ほど武装POWERが上昇（最大(\d+)%上昇）/);
if(m){const p=parseInt(m[1],10)||0;traits.enPowerMax=Math.max(traits.enPowerMax,p);noteHit(raw);}
